-- PT-L2 Module 2 — Advanced Penetrant Chemistry (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Komposisi Penetran & Peran Surfactant', '{"slides":[{"heading":"Anatomi formulasi penetran","body":"Penetran komersial bukan cairan tunggal — ia campuran solvent carrier (umumnya petroleum distillate/kerosene base) + dye (fluorescent atau visible) + wetting agent (surfactant) + viscosity modifier + corrosion inhibitor + (untuk Method A) emulsifier built-in. Carrier mengangkut dye ke dalam diskontinuitas; dye memberi kontras; surfactant mengontrol surface tension agar penetran membasahi permukaan dan masuk ke crack sempit."},{"heading":"Apa itu surfactant","body":"Surfactant (surface-active agent) adalah molekul amphiphilic: satu ujung hydrophilic (suka air) dan satu ujung lipophilic/hydrophobic (suka minyak). Struktur dua-kutub inilah yang menurunkan surface tension cairan. Penetran yang baik justru ber-surface tension RENDAH — tipikal ~25-35 dyne/cm dibandingkan air ~72 dyne/cm — agar sudut kontak (θ) kecil dan penetran membasahi serta menyebar ke seluruh permukaan."},{"heading":"Kenapa surface tension menentukan sensitivity","body":"Capillary rise mengikuti h = 2σ·cosθ / (ρgr). Untuk crack ber-radius r kecil, kombinasi surface tension (σ) memadai dengan sudut kontak (θ) mendekati nol membuat penetran tertarik kuat ke dalam diskontinuitas. Namun σ tidak boleh dioptimalkan sendiri — formulator menyeimbangkan σ, viscositas, dan wetting agar penetran masuk saat dwell DAN dapat ''ditarik'' keluar oleh developer saat blotting. Keseimbangan inilah ilmu di balik grading sensitivity."},{"heading":"Dye loading dan brightness","body":"Konsentrasi dye menentukan brightness. Fluorescent dye (Type I) dieksitasi UV-A (~365 nm) dan beremisi hijau-kuning (~520-560 nm), rentang yang paling sensitif untuk mata teradaptasi-gelap. Menambah dye TIDAK selalu menaikkan sensitivity — pada konsentrasi tinggi terjadi concentration quenching (self-absorption) yang justru menurunkan brightness. Sensitivity tinggi dicapai lewat carrier/surfactant yang lebih baik, bukan sekadar lebih banyak dye."}]}', 460, NULL),
  (2, 'reading', 'Komposisi Emulsifier — Lipophilic vs Hydrophilic', '{"slides":[{"heading":"Fungsi emulsifier","body":"Pada post-emulsifiable penetrant (Method B & D), penetran sendiri TIDAK water-washable. Emulsifier diterapkan sebagai langkah terpisah untuk membuat lapisan penetran berlebih di permukaan menjadi dapat dibilas air, tanpa mengganggu penetran yang sudah terperangkap di dalam crack. Inilah sumber sensitivity tinggi Method B/D — kontrol removal yang sangat presisi sehingga indikasi halus tidak ikut terbilas."},{"heading":"Lipophilic emulsifier (Method B)","body":"Emulsifier lipophilic adalah cairan berbasis minyak (oil-based), diaplikasikan tanpa pengenceran (ready-to-use, ~100%). Mekanismenya DIFUSI: emulsifier berdifusi masuk ke lapisan penetran berlebih seiring waktu hingga lapisan itu larut air. Karena difusi bergantung waktu, dwell emulsifier sangat kritis (tipikal hanya ~30 detik-2 menit) dan SULIT dihentikan dengan akurat — over-emulsification akan menarik penetran keluar dari crack juga."},{"heading":"Hydrophilic emulsifier (Method D)","body":"Emulsifier hydrophilic adalah konsentrat detergen yang DIENCERKAN dengan air. Konsentrasi tipikal per AMS 2644 / ASTM E1417: dip tank 5-20%, spray application <=5%. Mekanismenya detergent action/displacement (bukan difusi) — emulsifier mengangkat penetran berlebih dari permukaan. Karena dikontrol oleh KONSENTRASI (selain waktu), Method D lebih reproducible, lebih toleran terhadap variasi dwell, dan kini lebih umum dipakai daripada Method B."},{"heading":"HLB — Hydrophilic-Lipophilic Balance","body":"Karakter emulsifier dinyatakan oleh nilai HLB (skala ~0-20). HLB rendah (3-6) bersifat oil-soluble (cocok untuk lipophilic Method B); HLB tinggi (8-18) bersifat water-soluble (cocok untuk hydrophilic detergent Method D). Pada Method D, pre-rinse air sebelum emulsifier menghilangkan sebagian penetran permukaan dahulu sehingga beban emulsifier berkurang dan kontaminasi bath lebih lambat."}]}', 480, NULL),
  (3, 'reading', 'Sensitivity Grading per AMS 2644', '{"slides":[{"heading":"Lima level sensitivity fluorescent","body":"AMS 2644 mengkualifikasi material fluorescent (Type I) ke lima tingkat sensitivity yang meningkat: Level 1/2 (very low/ultra-low), Level 1 (low), Level 2 (medium), Level 3 (high), dan Level 4 (ultra-high). Visible dye (Type II) umumnya TIDAK diberi level numerik — sensitivitasnya setara low/medium. Level ditetapkan dari jumlah dan ketajaman indikasi yang terdeteksi pada panel referensi standar."},{"heading":"Kualifikasi pada TAM / PSM / Ni-Cr panel","body":"Sensitivity diukur memakai panel referensi seperti TAM panel (PSM-5) yang memiliki star-burst crack terkontrol, atau Ni-Cr cracked-chrome panel dengan retakan thermal/fatigue berukuran diketahui dan menurun bertahap. Level penetran ditetapkan dari jumlah dan ketajaman indikasi yang muncul dibandingkan penetran referensi ter-kualifikasi pada panel yang sama dalam kondisi terkontrol."},{"heading":"Sensitivity = properti SISTEM, bukan hanya penetran","body":"Penting bagi Level II: sensitivity adalah properti SISTEM lengkap (penetran + metode removal + developer + lighting), bukan penetran saja. Method C solvent-removable + Form d (nonaqueous wet developer, sensitivity tertinggi) memberi sensitivity tinggi pada area kecil. Method D + penetran Level 4 memberi sensitivity tertinggi untuk volume produksi aerospace. Lighting tak memenuhi syarat (UV-A < 1000 µW/cm² @ 38 cm) akan menurunkan sensitivity sistem berapapun grade penetrannya."},{"heading":"Memilih level untuk aplikasi","body":"Level rendah (1/2-2) untuk crack kasar / casting porosity, mengurangi background noise dan false call. Level tinggi (3-4) untuk fatigue crack halus, grinding crack, turbine blade — tapi background dapat naik sehingga butuh removal & developer yang lebih ketat. Over-spesifikasi sensitivity menyebabkan over-call indikasi non-relevant; Level II wajib mencocokkan grade ke critical-defect size yang dipersyaratkan kode/prosedur."}]}', 500, NULL),
  (4, 'reading', 'Kontrol Kualitas Kimia Penetran', '{"slides":[{"heading":"Water content penetran water-washable","body":"Method A (water-washable) memakai penetran dengan surfactant/emulsifier built-in, sehingga sensitif terhadap kontaminasi air. Water content dipantau berkala terhadap limit datasheet penetran (tipikal toleransi sekitar 5% air sebelum gel/separation, sesuai ASTM E1417 dan spec produk). Air berlebih membuat penetran ter-emulsifikasi sebagian, gel, atau kehilangan brightness — dibandingkan terhadap penetran referensi unused."},{"heading":"Konsentrasi & kontaminasi emulsifier bath","body":"Konsentrasi hydrophilic emulsifier (Method D) diverifikasi dengan refractometer (skala Brix) terhadap kurva kalibrasi, biasanya harian. Bath terkontaminasi penetran (drag-in) menurunkan efektivitas removal. Kontrol: cek konsentrasi, cek tingkat kontaminasi fluorescent dalam bath di bawah UV, lalu top-up/ganti sesuai SOP. Lipophilic emulsifier (Method B) tidak diencerkan tetapi tetap dipantau terhadap kontaminasi penetran dan air."},{"heading":"System performance check","body":"Verifikasi performa sistem keseluruhan dilakukan dengan menjalankan panel referensi (TAM/PSM atau Ni-Cr panel) melalui SELURUH proses dan membandingkan indikasi terhadap baseline foto. Penurunan jumlah/brightness indikasi menandakan degradasi: penetran lelah, removal over-aggressive, developer terkontaminasi, atau UV lamp lemah. Ini adalah cek ''apakah seluruh rantai kimia masih bekerja'' end-to-end."},{"heading":"Kontaminan yang merusak kimia & material","body":"Halogen (chlorine/fluorine) dan sulfur adalah kontaminan kritis untuk material nickel-base & austenitic stainless (risiko stress-corrosion cracking & intergranular attack saat dipanaskan). AMS 2644 mensyaratkan sertifikasi kandungan sulfur dan total halogen rendah — umumnya dibatasi maksimum 1% masing-masing dari residu kering yang diuapkan. Level II harus memastikan sertifikat batch dan tidak mencampur produk dari famili/merk berbeda yang dapat saling menetralkan dye atau surfactant."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Penetrant Chemistry', '{"description":"7 soal tentang komposisi penetran, surfactant, emulsifier (lipophilic vs hydrophilic), HLB, sensitivity grading AMS 2644, dan kontrol kimia.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 2
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 2 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa sifat molekul surfactant yang membuatnya mampu menurunkan surface tension penetran?',
   '["Bersifat ionik kuat sehingga menghantarkan listrik","Bersifat amphiphilic — punya ujung hydrophilic dan ujung lipophilic","Memiliki berat molekul sangat tinggi sehingga kental","Bersifat sepenuhnya hydrophobic sehingga menolak air"]', 1,
   'Surfactant adalah molekul amphiphilic: satu ujung hydrophilic dan satu ujung lipophilic. Struktur dua-kutub inilah yang menurunkan surface tension cairan sehingga penetran membasahi permukaan dan masuk ke crack via capillary action. Penetran yang baik justru ber-surface tension rendah (~25-35 dyne/cm vs air ~72 dyne/cm).', 'Penetrant Chemistry', 'easy'),
  ('Mekanisme kerja emulsifier LIPOPHILIC (Method B) untuk membuat penetran berlebih dapat dibilas air adalah:',
   '["Pengenceran air pada konsentrasi 5-20% (concentration-controlled)","Reaksi kimia langsung yang menetralkan dye penetran","Difusi emulsifier ke dalam lapisan penetran seiring waktu (time-controlled)","Penguapan solvent carrier sehingga penetran mengeras"]', 2,
   'Lipophilic emulsifier (oil-based, dipakai ~100% tanpa pengenceran) bekerja lewat DIFUSI ke dalam lapisan penetran. Karena bergantung waktu, dwell-nya sangat kritis dan sulit dihentikan akurat; over-emulsification dapat menarik penetran keluar dari crack.', 'Emulsifier Systems', 'medium'),
  ('Untuk hydrophilic emulsifier (Method D) yang diaplikasikan dengan DIP tank, rentang konsentrasi tipikal per AMS 2644 / ASTM E1417 adalah:',
   '["100% (tanpa pengenceran)","30-50%","0.1-1%","5-20%"]', 3,
   'Hydrophilic emulsifier (detergen) diencerkan air; konsentrasi dip tank tipikal 5-20%, sedangkan spray application <=5%. Karena dikontrol oleh konsentrasi (selain waktu), Method D lebih reproducible daripada Method B yang murni time-controlled.', 'Emulsifier Systems', 'medium'),
  ('Nilai HLB (Hydrophilic-Lipophilic Balance) yang TINGGI (sekitar 8-18) menandakan emulsifier yang:',
   '["Water-soluble, cocok untuk sistem hydrophilic (Method D)","Oil-soluble, cocok untuk sistem lipophilic (Method B)","Tidak larut di air maupun minyak","Hanya cocok untuk penetran visible dye Type II"]', 0,
   'Skala HLB ~0-20: nilai rendah (3-6) bersifat oil-soluble untuk lipophilic (Method B), nilai tinggi (8-18) bersifat water-soluble untuk hydrophilic detergent (Method D). HLB mengkarakterisasi keseimbangan kelarutan emulsifier.', 'Emulsifier Systems', 'hard'),
  ('Menurut AMS 2644, level sensitivity TERTINGGI (ultra-high) untuk penetran fluorescent Type I adalah:',
   '["Level 1","Level A","Level 2","Level 4"]', 3,
   'AMS 2644 mengkualifikasi fluorescent penetrant ke lima tingkat meningkat: Level 1/2 (very low), 1 (low), 2 (medium), 3 (high), hingga 4 (ultra-high). Level dievaluasi pada panel referensi seperti TAM/PSM atau Ni-Cr cracked-chrome panel.', 'Sensitivity Grading', 'easy'),
  ('Mengapa menambah konsentrasi fluorescent dye secara berlebihan TIDAK selalu menaikkan sensitivity penetran?',
   '["Dye berlebih membuat penetran menjadi visible dye Type II otomatis","Terjadi concentration quenching (self-absorption) yang justru menurunkan brightness","Dye berlebih meningkatkan surface tension hingga capillary action berhenti","Dye berlebih menguap lebih cepat dari solvent carrier"]', 1,
   'Pada konsentrasi dye tinggi terjadi concentration quenching / self-absorption — molekul dye menyerap emisi molekul lain sehingga brightness justru turun. Sensitivity tinggi dicapai lewat carrier/surfactant yang lebih baik, bukan sekadar menambah dye.', 'Penetrant Chemistry', 'hard'),
  ('Kandungan halogen (chlorine) dan sulfur dibatasi ketat pada penetran (per AMS 2644) terutama karena:',
   '["Halogen dan sulfur memadamkan fluoresensi dye secara permanen","Keduanya menaikkan surface tension hingga penetran tidak membasahi","Risiko stress-corrosion cracking & intergranular attack pada nickel-base dan austenitic stainless saat dipanaskan","Keduanya membuat developer Form d tidak bisa kering"]', 2,
   'Residu halogen dan sulfur berisiko menyebabkan stress-corrosion cracking dan intergranular attack pada material nickel-base & austenitic stainless saat terpapar panas. AMS 2644 mensyaratkan sertifikasi kandungan rendah (umumnya maksimum 1% masing-masing dari residu kering).', 'Chemical QC', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 3 — Post-Emulsifiable Systems (Method B/D) (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip Post-Emulsifiable: Mengapa Sensitivitas Naik', '{"slides":[{"heading":"Konsep dasar dua langkah","body":"Pada Method A (water-washable), emulsifier sudah tercampur dalam penetran sehingga dapat langsung dibilas air. Pada post-emulsifiable, penetran TIDAK mengandung emulsifier — emulsifier diaplikasikan sebagai langkah terpisah setelah dwell penetran. Penetran murni (tanpa emulsifier) jauh lebih tahan terhadap over-removal, sehingga indikasi halus tetap tertahan di dalam diskontinuitas saat dibilas."},{"heading":"Gain sensitivitas 2-3x","body":"Karena penetran tidak ter-emulsi sendiri, gaya kapiler menahannya lebih kuat di crack sempit/dangkal. Hasilnya sensitivitas naik 2-3x dibanding Method A, memungkinkan deteksi fatigue crack rambut dan grinding crack halus. Trade-off: kompleksitas proses sekitar 5x lebih tinggi karena adanya langkah emulsifikasi yang time-critical (B) atau concentration-critical (D)."},{"heading":"Method B vs Method D","body":"Method B = post-emulsifiable LIPOPHILIC (emulsifier berbasis minyak, bekerja melalui DIFUSI, dikendalikan oleh WAKTU). Method D = post-emulsifiable HYDROPHILIC (emulsifier berbasis detergen/air, bekerja melalui AKSI DETERJEN, dikendalikan oleh KONSENTRASI dan waktu). Keduanya menghasilkan sensitivitas tinggi (umumnya Level 3-4 per AMS 2644) tetapi mekanisme dan kontrol prosesnya berbeda total."},{"heading":"Kapan dipakai","body":"Dipilih untuk komponen kritikal di mana sensitivitas tinggi sepadan dengan kompleksitasnya: turbine blade aerospace, fastener berkekuatan tinggi, weld kritikal, dan bagian dengan permukaan relatif mulus. Post-emulsifiable kurang cocok untuk permukaan kasar karena emulsifier sulit menghilangkan background yang terperangkap pada surface roughness, menimbulkan over-background."}]}', 440, NULL),
  (2, 'reading', 'Method B Lipophilic — Kontrol oleh Waktu', '{"slides":[{"heading":"Mekanisme difusi","body":"Emulsifier lipophilic adalah cairan berbasis minyak yang diaplikasikan tanpa pengenceran (digunakan as-supplied, ~100%). Emulsifier berdifusi ke dalam lapisan penetran berlebih di permukaan, mengubahnya menjadi senyawa yang dapat dibilas air. Proses difusi berjalan terus selama emulsifier kontak dengan penetran — inilah sebabnya WAKTU menjadi variabel kontrol kritis pada Method B."},{"heading":"Emulsifier dwell time kritis","body":"Dwell emulsifier lipophilic sangat singkat — tipikal 30 detik sampai 2 menit, sesuai data sheet produk. Terlalu singkat = penetran berlebih tidak cukup ter-emulsi, menyebabkan background tinggi (over-background). Terlalu lama = emulsifier berdifusi terlalu dalam dan ikut meng-emulsi penetran DI DALAM crack sehingga indikasi ikut terbilas (over-emulsification / over-removal) — indikasi hilang permanen."},{"heading":"Aplikasi dengan dip","body":"Lipophilic umumnya diaplikasikan dengan immersion (dip), bukan spray, karena lapisan harus seragam dan timing harus presisi. Setelah dip, part diangkat lalu dibiarkan drain selama dwell time terukur, kemudian langsung dibilas. Tidak boleh ada agitasi selama dwell karena akan mempercepat difusi secara tidak terkontrol dan mempersempit jendela proses lebih lanjut."},{"heading":"Karakter proses lipophilic","body":"Kelebihan: persiapan sederhana (as-supplied, tanpa mixing konsentrasi). Kekurangan: jendela waktu sangat sempit dan tidak forgiving — sekali over-emulsified tidak bisa dikoreksi tanpa membersihkan ulang dari awal. Hydrophilic (Method D) dikembangkan sebagian untuk mengatasi keterbatasan kontrol waktu yang ketat ini dengan memberi jendela proses yang lebih lebar."}]}', 470, NULL),
  (3, 'reading', 'Method D Hydrophilic — Kontrol oleh Konsentrasi', '{"slides":[{"heading":"Mekanisme aksi deterjen","body":"Emulsifier hydrophilic adalah konsentrat detergen yang diencerkan dengan air. Mekanismenya bersifat detergent/scrubbing — emulsifier mengangkat penetran berlebih dari permukaan secara mekanis-kimiawi, BUKAN melalui difusi seperti lipophilic. Karena tidak berdifusi ke dalam crack secepat lipophilic, hydrophilic lebih tahan terhadap over-removal dan memberi jendela proses yang lebih lebar."},{"heading":"Konsentrasi adalah variabel kontrol","body":"Variabel kritis Method D adalah KONSENTRASI emulsifier dalam air. Untuk aplikasi DIP tipikal 5-20% (sering 15-20% pada dip bath). Untuk aplikasi SPRAY harus jauh lebih encer, tipikal <=5% (sering 0,1-5%). Konsentrasi terlalu tinggi = over-removal (analog over-emulsification). Konsentrasi terlalu rendah = removal tidak tuntas, background tinggi. Konsentrasi dipantau dengan refractometer."},{"heading":"Pre-rinse sebelum emulsifier","body":"Praktik standar Method D: lakukan PRE-RINSE air ringan sebelum aplikasi emulsifier hydrophilic untuk menghilangkan sebagian besar penetran permukaan terlebih dahulu. Ini mengurangi beban emulsifier, memperpanjang umur bath, dan membuat removal lebih konsisten. Lipophilic tidak menggunakan pre-rinse karena emulsifier berbasis minyak tidak kompatibel dengan air pada langkah tersebut."},{"heading":"Dwell dan jendela proses","body":"Dwell emulsifier hydrophilic tipikal 1-2 menit untuk dip, lebih singkat untuk spray, sesuai data sheet. Jendela proses lebih forgiving daripada lipophilic, tetapi tetap harus dikontrol — kombinasi konsentrasi tinggi + dwell lama tetap menyebabkan over-removal. Agitasi/aerasi pada dip bath membantu konsistensi tetapi harus terkendali agar tidak mempercepat removal secara berlebihan."}]}', 480, NULL),
  (4, 'reading', 'Lipophilic vs Hydrophilic — Perbandingan & Troubleshooting', '{"slides":[{"heading":"Tabel perbandingan kunci","body":"Method B (Lipophilic): basis minyak, mekanisme DIFUSI, kontrol oleh WAKTU (30 dtk-2 mnt), aplikasi dip as-supplied (~100%), tanpa pre-rinse, jendela sempit. Method D (Hydrophilic): basis air-detergen, mekanisme AKSI DETERJEN, kontrol oleh KONSENTRASI (dip 5-20%, spray <=5%) ditambah waktu, dengan pre-rinse, jendela lebih lebar, dipantau refractometer."},{"heading":"Mendiagnosis over-removal","body":"Gejala over-removal/over-emulsification: indikasi lemah atau hilang padahal defect diketahui ada (verifikasi dengan TAM/PSM panel atau Ni-Cr cracked-chrome panel). Penyebab pada lipophilic = dwell emulsifier terlalu lama; penyebab pada hydrophilic = konsentrasi terlalu tinggi dan/atau dwell terlalu lama. Koreksi: kurangi dwell (B) atau turunkan konsentrasi via refractometer (D)."},{"heading":"Mendiagnosis over-background","body":"Gejala over-background: fluoresensi/warna latar tinggi yang menutupi indikasi. Penyebab = emulsifikasi tidak cukup (dwell terlalu singkat pada B, konsentrasi terlalu rendah pada D) atau bilas tidak tuntas. Koreksi harus dilakukan dengan re-proses dari awal (bersihkan ulang seluruh part) — tidak boleh menambah emulsifier di atas part yang sudah masuk tahap developer."},{"heading":"Verifikasi sistem","body":"Apa pun metodenya, performa sistem post-emulsifiable diverifikasi dengan test panel (TAM/PSM atau Ni-Cr cracked-chrome panel) yang menampilkan crack berukuran terkalibrasi. Bandingkan jumlah/kecerahan indikasi panel terhadap standar referensi setiap hari sebelum produksi. Penurunan indikasi panel menandakan masalah konsentrasi emulsifier, kontaminasi bath, atau degradasi penetran."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — Post-Emulsifiable Systems (Method B/D)', '{"description":"7 soal: prinsip post-emulsifiable, lipophilic (kontrol waktu) vs hydrophilic (kontrol konsentrasi), dan troubleshooting.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 3
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 3 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa perbedaan mendasar antara penetran post-emulsifiable (Method B/D) dan penetran water-washable (Method A)?',
   '["Penetran post-emulsifiable TIDAK mengandung emulsifier; emulsifier diaplikasikan sebagai langkah terpisah","Penetran post-emulsifiable mengandung emulsifier sejak awal, sedangkan Method A tidak","Penetran post-emulsifiable hanya bisa Type II (visible), sedangkan Method A hanya Type I","Tidak ada perbedaan; keduanya dibilas dengan cara yang sama"]', 0,
   'Pada Method A emulsifier sudah tercampur dalam penetran sehingga langsung dapat dibilas air. Pada post-emulsifiable penetrannya murni tanpa emulsifier; emulsifier diaplikasikan terpisah setelah dwell penetran, membuat penetran lebih tahan over-removal dan menaikkan sensitivitas 2-3x.', 'Post-Emulsifiable Principles', 'easy'),
  ('Pada Method B (lipophilic), variabel proses apa yang paling kritis untuk dikendalikan?',
   '["Konsentrasi emulsifier dalam air","Suhu developer","Waktu (emulsifier dwell time)","pH air bilasan"]', 2,
   'Emulsifier lipophilic bekerja melalui difusi ke dalam lapisan penetran berlebih, dan difusi berjalan terus selama kontak. Karena itu WAKTU (dwell emulsifier, tipikal 30 detik-2 menit) adalah variabel kontrol kritis pada Method B. Konsentrasi justru merupakan variabel kontrol Method D (hydrophilic).', 'Method B Lipophilic', 'easy'),
  ('Mengapa emulsifier dwell time yang terlalu LAMA pada Method B menyebabkan kegagalan deteksi?',
   '["Penetran mengering di permukaan sehingga tidak bisa dibilas","Developer tidak dapat menempel pada permukaan yang sudah teremulsi","Emulsifier berdifusi terlalu dalam dan ikut meng-emulsi penetran di dalam crack sehingga indikasi terbilas (over-removal)","Lampu UV-A kehilangan intensitas saat dwell terlalu lama"]', 2,
   'Dwell emulsifier terlalu lama menyebabkan over-emulsification/over-removal: emulsifier berdifusi melewati penetran berlebih hingga ikut meng-emulsi penetran yang tertahan di dalam diskontinuitas, sehingga indikasi ikut terbilas dan hilang permanen.', 'Method B Lipophilic', 'medium'),
  ('Untuk Method D (hydrophilic) dengan aplikasi DIP, rentang konsentrasi emulsifier yang tipikal adalah?',
   '["5-20%","30-50%","60-80%","100% (as-supplied tanpa pengenceran)"]', 0,
   'Emulsifier hydrophilic untuk aplikasi dip tipikal 5-20% (sering 15-20%). Untuk aplikasi spray harus jauh lebih encer, tipikal <=5%. Konsentrasi 100% as-supplied adalah praktik untuk lipophilic (Method B), bukan hydrophilic. Konsentrasi dipantau dengan refractometer.', 'Method D Hydrophilic', 'medium'),
  ('Mekanisme kerja emulsifier HYDROPHILIC (Method D) paling tepat digambarkan sebagai?',
   '["Difusi berbasis minyak ke dalam lapisan penetran","Reaksi oksidasi yang memecah molekul penetran","Penguapan selektif komponen ringan penetran","Aksi deterjen yang mengangkat penetran berlebih secara mekanis-kimiawi"]', 3,
   'Emulsifier hydrophilic adalah konsentrat detergen yang diencerkan air dan bekerja melalui aksi deterjen (mengangkat penetran berlebih), bukan difusi. Difusi berbasis minyak adalah mekanisme lipophilic (Method B). Karena tidak berdifusi cepat ke dalam crack, hydrophilic lebih tahan over-removal.', 'Method D Hydrophilic', 'medium'),
  ('Apa fungsi langkah PRE-RINSE pada proses Method D (hydrophilic) yang umumnya TIDAK ada pada Method B?',
   '["Mengaktifkan emulsifier sebelum diaplikasikan","Menghilangkan sebagian besar penetran permukaan dulu untuk mengurangi beban emulsifier dan memperpanjang umur bath","Menetralkan pH penetran agar developer menempel","Mendinginkan part agar emulsifier tidak menguap"]', 1,
   'Pre-rinse air ringan sebelum emulsifier hydrophilic menghilangkan sebagian besar penetran permukaan, mengurangi beban emulsifier, memperpanjang umur bath, dan membuat removal lebih konsisten. Lipophilic tidak menggunakan pre-rinse karena emulsifier berbasis minyak tidak kompatibel dengan air pada langkah tersebut.', 'Method D Hydrophilic', 'hard'),
  ('Saat verifikasi sistem Method D, indikasi pada part lemah/hilang dan Ni-Cr cracked-chrome panel juga gagal menampilkan crack secara penuh. Penyebab paling mungkin dan koreksinya?',
   '["Konsentrasi emulsifier terlalu rendah; naikkan konsentrasi","Developer dwell terlalu lama; kurangi developer dwell","Konsentrasi emulsifier terlalu tinggi dan/atau dwell terlalu lama (over-removal); turunkan konsentrasi via refractometer dan/atau kurangi dwell","Intensitas UV-A terlalu tinggi; turunkan ke bawah 1000 uW/cm2"]', 2,
   'Indikasi lemah/hilang yang dikonfirmasi oleh panel yang juga gagal menampilkan crack menandakan over-removal. Pada hydrophilic penyebabnya konsentrasi emulsifier terlalu tinggi dan/atau dwell terlalu lama. Koreksinya turunkan konsentrasi (dipantau refractometer) dan/atau kurangi dwell. Konsentrasi rendah justru menyebabkan over-background, bukan indikasi hilang.', 'Troubleshooting', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 4 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Bath Maintenance & Kontaminasi Penetran', '{"slides":[{"heading":"Mengapa bath control penting","body":"Open-tank penetrant dan developer terdegradasi seiring pemakaian: drag-out (terbawa keluar bersama part), evaporasi solvent/volatil, kontaminasi air, serta tercampur dirt/oil dari permukaan part. Level II bertanggung jawab menjaga system performance tetap dalam spec sepanjang shift, bukan sekadar menjalankan proses. Tanpa kontrol, sensitivity bisa turun diam-diam tanpa indikasi visual yang jelas."},{"heading":"Kontaminasi air pada water-washable penetran","body":"Water-washable (Method A) adalah penetran yang paling rentan terhadap kontaminasi air karena formulanya memang dirancang dapat dicuci air. Per ASTM E1417/E165, batas water content umumnya maksimum 5% by volume (sebagian prosedur lebih ketat ke 3%). Air berlebih menurunkan brightness fluoresen, memicu separasi/gelling, dan dapat menyebabkan false removal (penetran terangkat dari diskontinuitas). Cek dengan water-content/water-tolerance test rutin."},{"heading":"Kontaminasi solvent & tramp oil","body":"Solvent atau oil dari part yang tidak ter-drain dapat ''mengencerkan'' penetran sehingga menurunkan viskositas dan sensitivity, atau justru menaikkan background. Kontrol: pre-clean memadai, drain part sebelum masuk tank, dan monitoring konsentrasi/sensitivity berkala. Penetran yang terkontaminasi berat (di luar batas yang dapat dikoreksi) harus di-discard dan diganti, bukan sekadar di-top-up."},{"heading":"Tanggung jawab Level II","body":"Menetapkan frekuensi pengecekan (daily/weekly/monthly), mendokumentasikan hasil ukur, dan memutuskan corrective action: top-up, adjust, atau replace bath. Semua keputusan harus traceable terhadap acceptance criteria di prosedur tertulis dan material yang qualified per AMS 2644. Keputusan tanpa dokumentasi tidak dapat dipertahankan saat audit."}]}', 440, NULL),
  (2, 'reading', 'Kontrol Konsentrasi Emulsifier Hidrofilik (Method D)', '{"slides":[{"heading":"Konsentrasi adalah parameter kunci","body":"Method D (post-emulsifiable hydrophilic) dikendalikan oleh KONSENTRASI emulsifier (detergent-type), bukan terutama oleh waktu seperti Method B lipofilik. Konsentrasi aplikasi dip umumnya 5-20% dan spray umumnya <=5%. Konsentrasi terlalu tinggi menyebabkan over-removal (penetran tercabut dari diskontinuitas, indikasi melemah/hilang); terlalu rendah menyebabkan under-removal (background tinggi menutupi indikasi)."},{"heading":"Pengukuran konsentrasi: refraktometer","body":"Konsentrasi emulsifier hidrofilik dipantau dengan refractometer; pembacaan Brix dikonversi ke persen via kurva kalibrasi dari supplier. Pengecekan minimal harian (atau per prosedur). Drag-in air dan drag-out emulsifier menggeser konsentrasi sepanjang shift, sehingga top-up dihitung dari pembacaan aktual refractometer, bukan ditebak. Refractometer dikalibrasi dengan air murni (zero reference) secara berkala."},{"heading":"Lipofilik vs hidrofilik (kontras Method B vs D)","body":"Method B lipofilik: emulsifier oil-based, removal dikontrol oleh DWELL TIME emulsifier (mekanisme difusi ke dalam penetran). Method D hidrofilik: emulsifier detergent-based, removal dikontrol oleh KONSENTRASI ditambah waktu kontak. Hidrofilik umumnya lebih toleran terhadap variasi waktu (lebih forgiving) sehingga lebih disukai untuk repeatability di production line otomatis."},{"heading":"Pre-rinse & dokumentasi","body":"Praktik hidrofilik standar: pre-rinse air untuk membuang surface penetran berlebih sebelum emulsifier, lalu aplikasi emulsifier sesuai konsentrasi terukur, lalu final wash. Catat: konsentrasi terukur, suhu bath, waktu kontak emulsifier, serta tekanan/temperatur air wash. Penyimpangan konsentrasi di luar batas prosedur mengharuskan bath di-adjust sebelum produksi dilanjutkan."}]}', 480, NULL),
  (3, 'reading', 'Monitoring Fluorescent Brightness & System Performance', '{"slides":[{"heading":"Penurunan brightness fluoresen","body":"Brightness fluoresen menurun akibat kontaminasi air, panas berlebih, paparan UV/white-light berkepanjangan, dan aging penetran. Penurunan brightness berarti indikasi kecil bisa tidak lagi terlihat meskipun crack ada — kegagalan yang berbahaya karena tidak menghasilkan alarm. Brightness adalah parameter performance yang wajib dipantau berkala terhadap referensi, bukan diasumsikan konstan."},{"heading":"TAM / PSM panel (system performance check)","body":"System performance diverifikasi dengan known-defect panel: TAM/PSM panel (memiliki star-burst crack pattern & brightness comparison areas) dan Ni-Cr cracked-chrome panel. Bandingkan jumlah dan ketajaman indikasi terhadap panel referensi yang disimpan. Pengecekan ini menguji SELURUH proses (penetran + removal + developer + lighting + operator) sekaligus, bukan hanya satu material atau satu langkah."},{"heading":"Verifikasi lighting & lingkungan","body":"Untuk Type I (fluorescent): UV-A minimum 1000 uW/cm2 pada jarak 38 cm, ambient white light maksimum 20 lux (2 fc), dan eye adaptation minimal 1 menit di booth gelap sebelum inspeksi. Untuk Type II (visible dye): white light minimum 1000 lux (100 fc) pada permukaan. Radiometer/lux meter harus dikalibrasi; bulb UV-A diperiksa rutin karena output meluruh seiring umur lampu."},{"heading":"Developer condition","body":"Form a (dry powder) harus tetap fluffy dan kering — gumpalan menandakan lembap, harus diganti. Form c (water-suspendable) dicek konsentrasi suspensinya dengan hydrometer (specific gravity) dan diberi agitasi agar partikel tidak mengendap. Form d (nonaqueous solvent-based, sensitivitas tertinggi) dicek coverage semprotannya agar tipis dan merata. Developer dwell minimal 10 menit, atau sekitar setengah dwell penetran."}]}', 480, NULL),
  (4, 'reading', 'Program Process Control & Corrective Action', '{"slides":[{"heading":"Jadwal pengecekan terstruktur","body":"Program tipikal: DAILY — system performance (TAM/PSM panel), lighting (UV-A & ambient white light), konsentrasi emulsifier hidrofilik (refractometer). WEEKLY/PERIODIK — water content WW penetran, developer condition, water-tolerance. MONTHLY — review sistem keseluruhan dan dokumentasi. Semua frekuensi dan metode mengikuti ASTM E1417 dan prosedur tertulis fasilitas."},{"heading":"Acceptance criteria & decision","body":"Setiap parameter punya batas tegas: water content WW <=5% by volume, konsentrasi hidrofilik dalam range supplier, UV-A >=1000 uW/cm2 @38 cm, ambient white <=20 lux. Bila suatu parameter gagal: hentikan inspeksi pada bath/sistem tersebut, lakukan corrective action (adjust/replace/re-lamp), re-verify dengan known-defect panel, baru lanjutkan. Part yang sudah diinspeksi sejak pengecekan terakhir yang lulus mungkin perlu di-retest."},{"heading":"Top-up vs replace","body":"Top-up valid untuk koreksi minor (misalnya menambah emulsifier konsentrat untuk menaikkan persentase sesuai pembacaan refractometer). Replace diperlukan saat kontaminasi melampaui batas yang tak dapat dikoreksi (water content WW penetran melebihi batas, brightness turun signifikan vs panel, atau oil contamination berat). Top-up tidak boleh dipakai untuk menutupi bath yang sudah failing secara fundamental."},{"heading":"Traceability & audit","body":"Level II memelihara log yang berisi: tanggal, parameter, hasil ukur, instrumen yang dipakai beserta status kalibrasinya, dan corrective action yang diambil. Log ini adalah bukti saat audit (misalnya Nadcap, atau verifikasi material AMS 2644) bahwa setiap part diinspeksi dengan sistem yang qualified. Tanpa traceability, validitas hasil inspeksi tidak dapat dipertahankan."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Process Control', '{"description":"7 soal process control: bath maintenance, konsentrasi emulsifier hidrofilik, brightness & system performance, lighting, corrective action.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 4
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 4 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Parameter utama yang mengendalikan removal pada Method D (post-emulsifiable hydrophilic) adalah:',
   '["Dwell time emulsifier (diffusion-controlled)","Temperatur penetran bath","Konsentrasi emulsifier (concentration-controlled)","Tekanan air pada final wash saja"]', 2,
   'Hydrophilic (Method D) dikendalikan oleh KONSENTRASI emulsifier detergent (dip umumnya 5-20%, spray <=5%). Ini berbeda dari Method B lipofilik yang removal-nya dikontrol oleh dwell time emulsifier (mekanisme difusi).', 'Process Control', 'medium'),
  ('Instrumen yang lazim dipakai untuk memantau konsentrasi emulsifier hidrofilik di dalam bath adalah:',
   '["pH meter","Radiometer UV-A","Hydrometer specific gravity","Refractometer (pembacaan Brix dikonversi ke %)"]', 3,
   'Konsentrasi emulsifier hidrofilik dipantau dengan refractometer; pembacaan Brix dikonversi ke persen via kurva kalibrasi supplier. Hydrometer dipakai untuk water-suspendable developer (Form c), sedangkan radiometer untuk UV-A.', 'Process Control', 'medium'),
  ('Batas maksimum kontaminasi air yang umum untuk water-washable (Method A) penetrant per ASTM E1417/E165 adalah sekitar:',
   '["5% by volume","20% by volume","50% by volume","Tidak ada batas selama masih berfluoresensi"]', 0,
   'Water content WW penetran umumnya dibatasi maksimum sekitar 5% by volume (sebagian prosedur lebih ketat ke 3%). Air berlebih menurunkan brightness, memicu gelling/separasi, dan dapat menyebabkan false removal.', 'Process Control', 'easy'),
  ('Apa konsekuensi konsentrasi emulsifier hidrofilik (Method D) yang TERLALU TINGGI?',
   '["Penetran tidak bisa masuk ke dalam crack","Over-removal — penetran ikut tercabut dari diskontinuitas sehingga indikasi melemah/hilang","Background terlalu gelap karena under-removal","Developer tidak akan pernah kering"]', 1,
   'Konsentrasi terlalu tinggi menyebabkan over-removal: penetran ikut tercabut dari diskontinuitas sehingga indikasi melemah atau hilang. Konsentrasi terlalu rendah menyebabkan under-removal dengan background tinggi yang menutupi indikasi.', 'Process Control', 'hard'),
  ('Alat yang memverifikasi system performance KESELURUHAN (penetran + removal + developer + lighting) pada sistem fluoresen adalah:',
   '["Lux meter ambient saja","Known-defect panel seperti TAM/PSM panel atau Ni-Cr cracked-chrome panel","Sertifikat batch dari supplier penetran","Refractometer Brix"]', 1,
   'TAM/PSM panel dan Ni-Cr cracked-chrome panel adalah known-defect panel yang menguji seluruh proses sekaligus, dibandingkan terhadap referensi tersimpan. Sertifikat batch hanya menyatakan material qualified, tidak menguji proses aktual di lini.', 'System Performance', 'medium'),
  ('Untuk inspeksi Type I (fluorescent), persyaratan lighting minimum yang BENAR adalah:',
   '["White light >=1000 lux tanpa batas ambient apa pun","UV-A >=100 uW/cm2 pada 1 m tanpa eye adaptation","Hanya ambient white light >=20 lux","UV-A >=1000 uW/cm2 pada 38 cm, ambient white light <=20 lux, eye adaptation >=1 menit"]', 3,
   'Type I (fluorescent): UV-A minimum 1000 uW/cm2 pada 38 cm, ambient white maksimum 20 lux (2 fc), dan eye adaptation minimal 1 menit. White light >=1000 lux (100 fc) justru merupakan syarat untuk Type II (visible dye), bukan Type I.', 'Lighting', 'medium'),
  ('Jika system performance check harian dengan TAM panel menunjukkan brightness turun signifikan vs referensi, tindakan Level II yang paling tepat adalah:',
   '["Lanjutkan produksi dan catat di log untuk dicek bulan depan","Hentikan inspeksi pada bath/sistem tersebut, lakukan corrective action, re-verify dengan panel, baru lanjut","Langsung top-up emulsifier tanpa mencari penyebabnya","Naikkan intensitas UV-A sampai indikasi terlihat lagi"]', 1,
   'Kegagalan parameter berarti stop inspeksi pada sistem itu, lakukan corrective action (adjust/replace/re-lamp), re-verify dengan known-defect panel, baru lanjut. Part sejak pengecekan lulus terakhir mungkin perlu retest. Menaikkan UV untuk ''memaksa'' indikasi terlihat menyembunyikan masalah, bukan memperbaikinya.', 'Corrective Action', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 5 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Aerospace Turbine Blade Inspection', '{"slides":[{"heading":"Mengapa turbine blade butuh sensitivity tertinggi","body":"Turbine blade (cast Ni-superalloy, mis. Inconel 718, atau single-crystal seperti CMSX-4) beroperasi pada thermal-mechanical fatigue ekstrem. Crack fatigue di trailing edge atau di root fillet bisa sangat tight (opening < 1 um). Karena itu AMS 2644 Sensitivity Level 3 (high) atau Level 4 (ultra-high) dengan Type I fluorescent penetrant adalah keharusan. Type II visible dye tidak pernah memberikan sensitivity yang cukup untuk komponen kritis ini."},{"heading":"Method pilihan: post-emulsifiable hydrophilic (Method D)","body":"Untuk crack tight pada blade, Method D (hydrophilic post-emulsifiable, Type I) adalah standar aerospace modern. Penetran tetap tertahan di crack karena removal dikontrol terpisah lewat emulsifier hydrophilic (detergent-based), bukan langsung oleh air. Konsentrasi emulsifier hydrophilic dikontrol ketat: dip umumnya 5-20%, spray <= 5%. Method A (water-washable) berisiko over-wash penetran dari crack dangkal/tight sehingga indikasi hilang."},{"heading":"Spec dominan: OEM aerospace + NADCAP","body":"Penetran material harus terdaftar di QPL AMS 2644. Prosesor PT harus terakreditasi NADCAP (audit checklist AC7114 untuk FPI). Spec OEM aerospace (mis. Pratt & Whitney PWA 269, atau spec FPI Rolls-Royce/GE setara) menetapkan sensitivity level, dwell, dan lighting yang sering lebih ketat dari ASTM E1417 generik. Persyaratan lighting tetap: UV-A >= 1000 uW/cm2 @ 38 cm, ambient white light <= 20 lux (2 fc), dan eye adaptation minimal 1 menit di booth gelap."},{"heading":"Cooling holes dan etch consideration","body":"Blade modern punya ratusan film-cooling hole hasil laser/EDM-drilling. EDM meninggalkan recast layer yang dapat menutup mulut crack sehingga penetran tidak bisa masuk -> sering diperlukan mild acid etch sebelum PT untuk membuka kembali mulut crack. Trapped penetran di dalam cooling hole dapat menimbulkan bleed-back yang menyerupai indikasi (geometric bleed-out); gunakan air blow-through terkontrol dan interpretasi hati-hati untuk membedakan bleed-out geometris dari crack relevan."}]}', 470, NULL),
  (2, 'reading', 'Plastic & Composite Component PT', '{"slides":[{"heading":"Mengapa PT untuk plastik & komposit","body":"Material non-konduktif dan non-feromagnetik (polimer, GFRP, sebagian keramik) tidak bisa diinspeksi MT, dan ET konvensional hanya berlaku untuk material konduktif — sehingga PT menjadi pilihan utama untuk surface crack. Namun PT adalah metode surface murni: hanya menemukan diskontinuitas yang tembus ke permukaan, dan TIDAK mendeteksi delaminasi subsurface pada komposit (itu domain UT atau thermography)."},{"heading":"Chemical compatibility — risiko utama","body":"Banyak penetran dan solvent remover (carrier hidrokarbon, remover berbasis ketone/alkohol) menyerang plastik dan dapat menyebabkan crazing, swelling, atau stress-cracking pada akrilik, polikarbonat, dan ABS. Karena itu compatibility test pada coupon dari material yang sama WAJIB dilakukan sebelum inspeksi produksi. Bila ragu, pilih Method A (water-washable) dengan developer non-solvent untuk meminimalkan serangan kimia."},{"heading":"Porositas & absorpsi permukaan","body":"Plastik atau komposit yang berpori dapat menyerap penetran ke seluruh permukaan -> background tinggi dan false indication. Permukaan porous mungkin perlu sealing atau penetran dwell yang lebih singkat. Developer Form a (dry powder) atau Form e (plastic film) sering lebih disukai daripada Form d (nonaqueous solvent-based) yang agresif terhadap polimer."}]}', 440, NULL),
  (3, 'reading', 'High-Temperature PT', '{"slides":[{"heading":"Kapan high-temp PT diperlukan","body":"Proses PT standar dikualifikasi untuk rentang suhu permukaan ~4-52 C (40-125 F) sesuai ASME V Article 6. Untuk inspeksi in-service tanpa cooldown — weld preheat zone, hot piping, atau awal refractory shutdown — diperlukan penetran high-temp khusus yang dikualifikasi pada suhu permukaan tinggi (formulasi tersedia hingga ~150 C / 300 F, dan beberapa formulasi khusus lebih tinggi lagi)."},{"heading":"Masalah fisika pada suhu tinggi","body":"Suhu tinggi mempercepat penguapan carrier penetran sehingga dwell efektif menyusut drastis; penetran bisa kering di permukaan sebelum sempat menembus crack. Selain itu visible dye dapat memudar (fade) karena panas. Karena itu high-temp penetran menggunakan carrier dengan flash point tinggi dan dwell yang disesuaikan, serta sering memakai Type II visible (dye merah) karena UV booth sulit diterapkan di lapangan bersuhu tinggi."},{"heading":"Kualifikasi & prosedur per ASME V Article 6","body":"ASME V Article 6 mensyaratkan kualifikasi prosedur ketika suhu permukaan di luar 4-52 C. Untuk suhu > 52 C, lakukan qualification pada comparator block (mis. cracked aluminum comparator / quench-cracked block) pada suhu aktual aplikasi, lalu bandingkan hasilnya terhadap prosedur standar yang dijalankan pada 4-52 C. Suhu permukaan part harus diukur (contact pyrometer/thermocouple) dan dicatat dalam laporan."},{"heading":"Praktik lapangan high-temp","body":"Aplikasi penetran biasanya dengan brush/swab pada area kecil karena spray menguap di udara panas. Dwell dipersingkat dan dipantau langsung. Solvent remover diaplikasikan ke lap/wiper, bukan disemprot langsung ke permukaan panas (risiko flash/penguapan). Bila memakai Form d nonaqueous developer, aplikasikan tipis dan perhatikan flash point solvent terhadap suhu permukaan demi keselamatan kebakaran."}]}', 470, NULL),
  (4, 'reading', 'Specialty: Underwater, Oxygen-Service & Process Selection', '{"slides":[{"heading":"Underwater / marine PT","body":"Untuk inspeksi struktur offshore atau lambung kapal tanpa dewatering, tersedia penetran underwater khusus yang water-insoluble dan diaplikasikan dengan brush oleh diver. Type II visible dye dengan kontras tinggi umum dipakai. Removal dan developing diadaptasi untuk lingkungan basah; sensitivity proses ini lebih rendah daripada proses booth, jadi gunakan hanya bila cooldown atau dewatering tidak feasible."},{"heading":"Cryogenic & oxygen-service consideration","body":"Komponen oxygen-service (mis. LOX) menuntut cleanliness ekstrem — residu penetran atau hidrokarbon adalah hazard kebakaran/ledakan. Gunakan penetran low-residue yang dikualifikasi untuk oxygen compatibility dan lakukan post-clean menyeluruh yang terverifikasi (mis. UV check residu). Untuk pengujian pada/menjelang suhu rendah, kualifikasi prosedur pada suhu aktual sesuai Article 6 (suhu di bawah 4 C juga membutuhkan kualifikasi)."},{"heading":"Matriks pemilihan proses (decision logic)","body":"Level II harus memilih Type/Method/Sensitivity/Developer berdasarkan: kritikalitas part, ukuran defect target, geometri (cooling hole, thread, blind hole), material compatibility, suhu, dan akses lighting. Contoh: turbine blade kritis -> Type I, Method D, Sensitivity 3-4, Developer Form a (dry). Field weld panas non-kritis -> Type II, Method C (solvent-removable) high-temp, Developer Form d nonaqueous (aplikasikan tipis). Komponen plastik -> Type II, Method A, Developer Form a atau e."}]}', 430, NULL),
  (5, 'quiz', 'Mini-quiz — Specialty Applications', '{"description":"8 soal aplikasi spesial PT Level II: turbine blade aerospace, plastik/komposit, high-temp, underwater, dan logika pemilihan proses.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 5
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 5 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Untuk inspeksi crack fatigue yang sangat tight (opening < 1 um) pada turbine blade cast Ni-superalloy aerospace, kombinasi yang paling tepat adalah:',
   '["Type I fluorescent, Method D (hydrophilic post-emulsifiable), Sensitivity Level 3-4","Type II visible dye, Method A, Sensitivity Level 1","Type III dual, Method C solvent-removable, Sensitivity Level 2","Type II visible dye, Method C, Sensitivity Level 2"]', 0,
   'Crack sangat tight pada komponen kritis aerospace menuntut sensitivity tertinggi: Type I fluorescent dengan Method D (hydrophilic post-emulsifiable) dan AMS 2644 Sensitivity Level 3 (high) atau 4 (ultra-high). Type II visible dye tidak pernah cukup untuk part kritis ini.', 'Aerospace PT', 'medium'),
  ('Mengapa Method D (hydrophilic post-emulsifiable) lebih disukai daripada Method A (water-washable) untuk turbine blade aerospace?',
   '["Method D lebih murah dan lebih cepat diproses","Method A tidak bisa dipakai pada material superalloy apa pun","Method A berisiko over-wash penetran dari crack dangkal/tight, sedangkan removal Method D dikontrol terpisah lewat emulsifier hydrophilic","Method D tidak memerlukan developer sama sekali"]', 2,
   'Pada Method A, removal terjadi langsung dengan air dan dapat mencuci penetran keluar dari crack dangkal/tight (over-wash). Pada Method D removal dikontrol terpisah melalui emulsifier hydrophilic dwell, sehingga background bersih sementara penetran di crack tetap tertahan.', 'Aerospace PT', 'medium'),
  ('Untuk Method D (hydrophilic post-emulsifiable), parameter proses yang paling kritis dikontrol adalah:',
   '["Konsentrasi emulsifier hydrophilic (dip umumnya 5-20%, spray <= 5%)","Viskositas oil-based emulsifier yang dikontrol oleh diffusion time","Tekanan UV-A pada permukaan part","Warna developer Form b yang water-soluble"]', 0,
   'Emulsifier hydrophilic adalah detergent yang removal-nya dikontrol oleh KONSENTRASI (dip 5-20%, spray <= 5%) plus contact/wash time. (Ini berbeda dengan Method B lipophilic oil-based yang dikontrol oleh diffusion/contact time.) Pengendalian konsentrasi inilah yang menjaga sensitivity dan kebersihan background.', 'Aerospace PT', 'hard'),
  ('Sebelum inspeksi PT pada turbine blade dengan film-cooling hole hasil EDM, langkah yang sering diperlukan adalah:',
   '["Memanaskan blade hingga 200 C agar crack terbuka","Etch (mild acid) untuk membuka mulut crack yang tertutup recast layer EDM","Melapisi seluruh permukaan dengan developer Form d sebelum mengaplikasikan penetran","Mengganti penetran fluorescent dengan visible dye"]', 1,
   'Proses EDM meninggalkan recast layer yang dapat menutup mulut crack sehingga penetran tidak bisa masuk. Mild acid etch membuka kembali mulut crack. Trapped penetran di cooling hole juga harus dibedakan dari indikasi relevan saat interpretasi.', 'Aerospace PT', 'hard'),
  ('Risiko utama saat melakukan PT pada komponen plastik (akrilik/polikarbonat/ABS) adalah:',
   '["Plastik memantulkan UV-A sehingga indikasi tidak pernah terlihat","Penetran tidak dapat menempel pada permukaan non-logam","Solvent dalam penetran/remover dapat menyebabkan crazing, swelling, atau stress-cracking pada plastik","Plastik selalu menghasilkan false negative pada PT"]', 2,
   'Banyak solvent carrier dan remover (ketone/alkohol/hidrokarbon) menyerang polimer sehingga timbul crazing, swelling, atau stress-cracking. Karena itu compatibility test pada coupon material yang sama wajib dilakukan sebelum produksi.', 'Plastic/Composite PT', 'medium'),
  ('Pernyataan yang BENAR mengenai keterbatasan PT pada komponen komposit (GFRP):',
   '["PT dapat mendeteksi delaminasi subsurface dengan baik","PT lebih sensitif daripada UT untuk semua jenis defect komposit","PT tidak dapat dipakai sama sekali pada material non-konduktif","PT hanya mendeteksi diskontinuitas yang tembus ke permukaan; delaminasi subsurface adalah domain UT/thermography"]', 3,
   'PT adalah metode surface — hanya mendeteksi diskontinuitas yang terbuka ke permukaan. Delaminasi internal pada komposit tidak terdeteksi PT dan membutuhkan UT atau thermography. PT justru berguna pada material non-konduktif yang tidak bisa diinspeksi MT/ET.', 'Plastic/Composite PT', 'medium'),
  ('Masalah fisika utama yang membuat PT standar gagal pada permukaan bersuhu tinggi (> 52 C) adalah:',
   '["Crack menutup total karena ekspansi termal sehingga tidak bisa diisi penetran","Penguapan carrier penetran yang cepat memperpendek dwell efektif sehingga penetran kering sebelum masuk crack","UV-A tidak bekerja pada suhu tinggi","Developer berubah menjadi konduktif pada suhu tinggi"]', 1,
   'Suhu tinggi mempercepat penguapan carrier sehingga penetran bisa kering sebelum sempat menembus crack, dan visible dye dapat fade. High-temp penetran menggunakan carrier high-flash-point dengan dwell yang disesuaikan untuk mengatasi ini.', 'High-Temp PT', 'medium'),
  ('Menurut ASME V Article 6, apa yang harus dilakukan bila PT diterapkan pada suhu permukaan di luar rentang standar 4-52 C (40-125 F)?',
   '["Tidak ada tindakan khusus, cukup dipersingkat dwell-nya","Kualifikasi prosedur pada suhu aktual aplikasi menggunakan comparator block, dan catat suhu permukaan di laporan","Otomatis gunakan Type I fluorescent tanpa kualifikasi","Naikkan sensitivity ke Level 4 tanpa pengujian apa pun"]', 1,
   'ASME V Article 6 mensyaratkan kualifikasi prosedur ketika suhu di luar 4-52 C, dilakukan pada comparator/cracked block pada suhu aktual aplikasi dibandingkan prosedur standar pada rentang normal. Suhu permukaan harus diukur dan didokumentasikan dalam laporan.', 'High-Temp PT', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 6 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Klasifikasi Indikasi: Relevant, Non-Relevant, False', '{"slides":[{"heading":"Tiga kategori indikasi","body":"Level II wajib membedakan: (1) FALSE indication - bleed-out yang tidak terkait diskontinuitas, akibat removal kurang (over-wash gagal / residual penetran di permukaan), serat lint, atau kontaminasi developer. (2) NON-RELEVANT - indikasi nyata dari fitur geometri atau struktur sah (press-fit, keyway, root thread, machining mark), bukan defect. (3) RELEVANT - disebabkan diskontinuitas aktual yang harus dievaluasi terhadap kriteria acceptance kode konstruksi."},{"heading":"Membedakan false vs relevant","body":"False indication TIDAK akan reappear setelah pembersihan ulang lokal dan re-developing; relevant indication akan muncul kembali karena penetran terus bleed dari rongga. Teknik konfirmasi: bersihkan spot dengan solvent, keringkan tuntas, aplikasikan developer Form d (nonaqueous solvent-based, sensitivitas tertinggi) dan amati bleed-back. Diskontinuitas asli memberi bleed progresif seiring waktu; kontaminasi permukaan tidak."},{"heading":"Non-relevant geometri","body":"Tanda yang konsisten muncul pada lokasi fitur desain yang dikenal (radius/sudut tajam, sambungan press-fit, root thread) umumnya non-relevant. ASME V Article 6 (T-680) mengharuskan indikasi non-relevant yang membingungkan dibuktikan ulang sebagai non-relevant. Jika ragu antara geometri vs crack, perlakukan sebagai relevant sampai terbukti sebaliknya - beban pembuktian ada pada inspektor."},{"heading":"Aturan ambang relevansi (App. 8)","body":"Per ASME VIII Div.1 Mandatory Appendix 8, suatu indikasi dianggap RELEVANT hanya bila dimensi mayor-nya melebihi 1.6 mm (1/16 in). Indikasi dengan dimensi mayor <=1.6 mm diperlakukan non-relevant untuk tujuan acceptance, namun tetap dievaluasi bila terjadi clustering/alignment. Klasifikasi yang benar mencegah over-reject (menolak false) dan under-reject (mengabaikan relevant)."}]}', 460, NULL),
  (2, 'reading', 'Sizing Indikasi: Panjang, Lebar, dan Bleed-Out', '{"slides":[{"heading":"Indikasi membesar dari diskontinuitas","body":"PT bersifat amplifikasi: bleed-out penetran lebih lebar dari rongga sebenarnya karena kapilaritas dan absorpsi developer. Karena itu yang diukur terhadap kriteria kode adalah dimensi INDIKASI (bukan crack aktual) - kode sudah memperhitungkan amplifikasi ini dalam batas acceptance-nya. Pengukuran dilakukan pada dimensi maksimum indikasi setelah developer dwell minimum tercapai."},{"heading":"Timing pengukuran kritis","body":"Developer dwell minimum 10 menit (atau ~1/2 penetrant dwell) sebelum interpretasi/pengukuran. Ukur dalam jendela waktu: terlalu cepat indikasi belum berkembang penuh (under-develop); terlalu lama bleed-out menyebar (over-bleed) dan melebih-lebihkan ukuran, terutama pada crack lebar. Catat waktu observasi. Untuk crack sangat halus, indikasi dapat terus tumbuh - ukur saat develop relatif stabil."},{"heading":"Alat dan teknik ukur","body":"Gunakan optical comparator, kaca pembesar bergradasi, atau penggaris berskala (resolusi ~0.5 mm). Untuk Type I (fluorescent), ukur di bawah UV-A >=1000 uW/cm2 pada 38 cm dengan ambient white light <=20 lux dan adaptasi mata minimal 1 menit. Untuk Type II (visible dye), white light >=1000 lux (100 fc). Ukur sumbu terpanjang; untuk indikasi linear catat panjang, untuk rounded catat dimensi mayor."},{"heading":"Linear vs rounded","body":"Indikasi LINEAR: panjang >= 3x lebar. Indikasi ROUNDED: panjang < 3x lebar (circular atau elliptical). Klasifikasi bentuk ini menentukan batas acceptance yang dipakai. Crack, lack of fusion, dan cold shut umumnya linear; porosity/gas hole umumnya rounded. Aligned indications (4 atau lebih dalam satu garis dengan spacing kecil) diperlakukan sebagai satu kelompok sesuai aturan kode."}]}', 480, NULL),
  (3, 'reading', 'Kriteria Acceptance per Kode', '{"slides":[{"heading":"ASME VIII Div.1 Appendix 8","body":"Acceptance untuk pressure vessel: indikasi LINEAR relevant dengan panjang >1.6 mm (1/16 in) = REJECT. Indikasi ROUNDED relevant >5 mm (3/16 in) = REJECT. Empat atau lebih indikasi rounded dalam satu garis dengan jarak edge-to-edge <=1.6 mm = REJECT. Crack, lack of fusion, dan incomplete penetration selalu REJECT (bersifat linear/planar kritis) tanpa memandang ukuran."},{"heading":"ASME V Article 6 vs B31.x","body":"ASME V Article 6 menetapkan TEKNIK, bukan acceptance; kriteria accept/reject dirujuk dari referencing/construction code (VIII, B31.1, B31.3). B31.3 process piping: linear >1.6 mm reject untuk normal fluid service, dengan kriteria lebih ketat pada severe cyclic service. Selalu pakai acceptance dari kode konstruksi yang governing, bukan asumsi default. Level II harus tahu kode mana yang berlaku."},{"heading":"ASTM E165 / E1417 dan AMS","body":"ASTM E165 (praktik) dan E1417 (proses, aerospace) memberi metode standar, tetapi acceptance ditetapkan oleh part drawing atau spec aplikasi. Banyak komponen aerospace: ZERO crack dan batas porosity sangat ketat. AMS 2644 mengatur KUALIFIKASI material penetran (Type I/II/III, Method A-D, Sensitivity Level 1-4), BUKAN acceptance indikasi - jangan tertukar."},{"heading":"Dokumentasi keputusan","body":"Untuk setiap indikasi relevant, catat: lokasi (peta/sketsa), tipe (linear/rounded), dimensi terukur, kode acceptance yang dipakai, dan keputusan accept/reject. Level II menandatangani laporan akhir. Indikasi yang reject memerlukan disposition (repair, re-inspect, atau scrap). Jejak audit harus memungkinkan inspektor lain memverifikasi keputusan secara independen."}]}', 500, NULL),
  (4, 'reading', 'Evaluasi Lanjutan: Clustering, Aligned, dan Borderline', '{"slides":[{"heading":"Aligned dan accumulated","body":"Indikasi terpisah yang sejajar/berdekatan sering harus digabung. ASME VIII App.8: 4 atau lebih rounded dalam satu garis dengan edge-to-edge <=1.6 mm ditolak. Untuk linear collinear dengan gap kecil, jumlahkan menjadi satu panjang efektif. Accumulated length pada panjang evaluasi tertentu (mis. per 150 mm las) dapat menjadi kriteria pada sebagian spec."},{"heading":"Kasus borderline","body":"Untuk indikasi dekat batas (mis. terukur ~1.5-1.7 mm linear pada batas 1.6 mm), re-clean dan re-test untuk mengonfirmasi dimensi sejati dan menghilangkan over-bleed. Jika tetap borderline, ambil keputusan konservatif menuju reject. Dokumentasikan metode ukur. Jangan menyesuaikan keputusan demi meluluskan part - integritas keputusan Level II adalah inti tanggung jawab."},{"heading":"Karakterisasi tipe diskontinuitas","body":"Pola bleed membantu identifikasi: garis tajam lurus/zigzag = crack; garis halus sepanjang fusi las = lack of fusion; titik bulat tunggal = gas porosity; deret titik tersebar = scattered porosity; garis intermittent = cold shut/lap. Karakterisasi memandu disposition dan root cause, walau acceptance utama tetap berdasarkan klasifikasi linear/rounded dan dimensi terukur."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Indication Sizing & Evaluation', '{"description":"7 soal evaluasi: klasifikasi indikasi, sizing, dan kriteria acceptance kode untuk PT Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 6
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 6 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Sebuah bleed-out pada lokasi tertentu MASIH muncul kembali (bleed-back progresif) setelah dibersihkan dengan solvent, dikeringkan, dan di-developing ulang memakai developer Form d. Indikasi ini paling tepat diklasifikasikan sebagai:',
   '["False indication akibat over-wash yang gagal","Relevant indication dari diskontinuitas aktual","Non-relevant indication dari fitur geometri","Kontaminasi developer yang dapat diabaikan"]', 1,
   'Indikasi yang muncul kembali secara progresif setelah re-clean dan re-developing menandakan penetran terus keluar dari rongga nyata - ciri relevant indication. False indication tidak akan reappear. Developer Form d (nonaqueous solvent-based) dipilih karena sensitivitas tertinggi untuk konfirmasi.', 'Klasifikasi Indikasi', 'medium'),
  ('Per ASME VIII Div.1 Mandatory Appendix 8, suatu indikasi baru dianggap RELEVANT (dan dievaluasi terhadap kriteria acceptance) bila dimensi mayor-nya melebihi:',
   '["0.8 mm","1.6 mm (1/16 in)","3.2 mm (1/8 in)","5 mm (3/16 in)"]', 1,
   'Appendix 8 menetapkan indikasi relevant hanya bila dimensi mayor >1.6 mm (1/16 in). Indikasi <=1.6 mm diperlakukan non-relevant untuk tujuan acceptance. Nilai 5 mm adalah batas reject untuk rounded relevant, bukan ambang relevansi.', 'Kriteria Acceptance', 'medium'),
  ('Dalam PT, dimensi mana yang diukur untuk dibandingkan dengan kriteria acceptance kode?',
   '["Lebar crack sebenarnya yang diukur dengan mikroskop","Kedalaman diskontinuitas","Panjang/dimensi INDIKASI (bleed-out), bukan crack aktual","Volume penetran yang keluar dari rongga"]', 2,
   'PT mengamplifikasi diskontinuitas; bleed-out lebih lebar dari rongga sebenarnya. Kode acceptance sudah memperhitungkan amplifikasi ini, sehingga yang diukur dan dievaluasi adalah dimensi INDIKASI, bukan crack aktual. PT juga tidak dapat menentukan kedalaman.', 'Sizing Indikasi', 'medium'),
  ('Sebuah indikasi terukur panjang 4.5 mm dan lebar 1.0 mm. Bagaimana klasifikasi bentuknya per definisi ASME?',
   '["Linear, karena panjang >= 3x lebar","Rounded, karena panjang < 5 mm","Non-relevant, karena lebar < 1.6 mm","Aligned, karena rasio panjang/lebar > 4"]', 0,
   'Indikasi linear didefinisikan bila panjang >= 3x lebar. Di sini 4.5 mm >= 3 x 1.0 mm (= 3.0 mm), sehingga LINEAR. Yang menentukan adalah rasio panjang terhadap lebar, bukan nilai absolut panjang.', 'Sizing Indikasi', 'easy'),
  ('Menurut ASME VIII Div.1 Appendix 8, indikasi ROUNDED relevant ditolak (reject) bila ukurannya melebihi:',
   '["1.6 mm (1/16 in)","3.2 mm (1/8 in)","5 mm (3/16 in)","6.4 mm (1/4 in)"]', 2,
   'Per Appendix 8, rounded relevant >5 mm (3/16 in) = reject, sedangkan linear relevant >1.6 mm (1/16 in) = reject. Membedakan kedua batas ini penting karena bergantung pada klasifikasi bentuk indikasi (linear vs rounded).', 'Kriteria Acceptance', 'medium'),
  ('Mengapa developer dwell minimum (>=10 menit atau ~1/2 penetrant dwell) penting sebelum mengukur indikasi?',
   '["Untuk memenuhi syarat intensitas UV-A 1000 uW/cm2 di 38 cm","Agar emulsifier hidrofilik selesai bereaksi","Agar indikasi berkembang penuh; terlalu cepat under-develop, terlalu lama over-bleed yang melebih-lebihkan ukuran","Agar seluruh penetran benar-benar kering sebelum diukur"]', 2,
   'Pengukuran harus dilakukan dalam jendela waktu yang tepat. Sebelum developer dwell cukup, indikasi belum berkembang penuh (under-develop). Jika terlalu lama, bleed-out menyebar (over-bleed) dan melebih-lebihkan dimensi, terutama pada crack lebar. Karena itu waktu observasi dicatat.', 'Sizing Indikasi', 'medium'),
  ('Pada inspeksi pressure vessel per ASME VIII Div.1, ditemukan crack sepanjang 0.9 mm. Disposition yang benar adalah:',
   '["Accept, karena di bawah ambang relevan 1.6 mm","Accept, karena di bawah batas rounded 5 mm","Diabaikan sebagai non-relevant geometri","Reject, karena crack/lack of fusion/incomplete penetration selalu ditolak terlepas dari ukuran"]', 3,
   'Appendix 8 menyatakan crack, lack of fusion, dan incomplete penetration selalu REJECT tanpa memandang ukuran karena sifatnya planar/linear yang kritis. Ambang 1.6 mm berlaku untuk indikasi linear umum, tetapi crack adalah kategori yang otomatis ditolak.', 'Kriteria Acceptance', 'hard'),
  ('ASME V Article 6 sering dijadikan acuan TEKNIK PT, namun untuk menentukan accept/reject suatu indikasi, kriteria acceptance harus diambil dari:',
   '["ASME V Article 6 itu sendiri, yang memuat tabel acceptance lengkap","AMS 2644, yang menetapkan batas ukuran indikasi","ISO 3452-2, yang menetapkan acceptance universal","Referencing/construction code yang berlaku (mis. ASME VIII, B31.3) atau part drawing/spec"]', 3,
   'ASME V Article 6 menetapkan TEKNIK, bukan acceptance. Kriteria accept/reject dirujuk dari construction/referencing code (ASME VIII, B31.1/B31.3) atau part drawing/spec aplikasi. AMS 2644 hanya mengatur kualifikasi material penetran (Type/Method/Sensitivity), bukan acceptance indikasi.', 'Kriteria Acceptance', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — PT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
-- Steps: ON CONFLICT DO NOTHING (safe, never deletes user progress).
-- Quiz questions: DELETE+INSERT per quiz step (idempotent).
