-- PT-L2 Module 7 — Procedure Development (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi Written Procedure PT', '{"slides":[{"heading":"Mengapa procedure tertulis wajib","body":"ASME V Article 6 T-621 mensyaratkan written procedure untuk setiap pemeriksaan PT. Procedure adalah kontrak teknis: ia mendefinisikan SEMUA variabel sehingga inspeksi dapat direproduksi oleh inspektor lain dengan hasil yang sama. Tanpa procedure tertulis dan ter-demonstrasi, sign-off Level II tidak sah secara code. Level II adalah pemegang authority untuk MENULIS dan men-demonstrate procedure ini, sedangkan persetujuan akhir prosedur tertulis umumnya berada pada Level III."},{"heading":"Essential vs nonessential variable","body":"ASME V Article 6 (lihat T-621 dan tabel variabel terkait) membagi variabel jadi dua. Essential variable (mis. tipe penetran TYPE I/II, METHOD A/B/C/D, klasifikasi & keluarga/merek material per AMS 2644, perubahan rentang suhu di luar yang ter-qualify, perubahan proses/agen pre-cleaning dan removal) — bila berubah, procedure WAJIB requalification. Nonessential variable (mis. teknik aplikasi penetran spray vs brush dalam batas yang diizinkan, detail prosedural minor) boleh berubah tanpa requalification tetapi tetap harus tercatat di procedure."},{"heading":"Elemen wajib T-621","body":"Procedure minimal memuat: identifikasi material/keluarga penetran-emulsifier-developer-cleaner (harus satu keluarga ter-qualify, tidak boleh campur merek/keluarga), teknik & agen pre-cleaning, suhu permukaan & material, dwell penetran dalam rentang 5-30 min, teknik aplikasi & removal (untuk Method D: rasio emulsifier hidrofilik dip 5-20% / spray <=5%, kontrol refractometer/Brix), drying, developer FORM a-e & dwell >=10 min, kondisi pencahayaan, teknik interpretasi & evaluasi, kriteria acceptance, dan post-cleaning."},{"heading":"Referensi dokumen induk","body":"Procedure tidak berdiri sendiri — ia merujuk referencing code/spec: ASME V Article 6 (teknik & persyaratan procedure), ASME VIII Div.1 Mandatory Appendix 8 (kriteria acceptance), ASTM E165/E1417 atau ISO 3452 sesuai kontrak, dan AMS 2644 untuk klasifikasi material. Setiap angka dalam procedure (dwell, intensitas UV-A, lux, suhu) harus dapat ditelusuri ke salah satu referensi ini, bukan ditetapkan tanpa dasar."}]}', 460, NULL),
  (2, 'reading', 'Menetapkan Variabel Teknis', '{"slides":[{"heading":"Pemilihan sistem penetran","body":"Pilih TYPE (I fluorescent untuk sensitivity tinggi / II visible untuk lapangan tanpa darkroom) dan METHOD berdasar geometri, kondisi lapangan & sensitivitas yang dibutuhkan. Contoh procedure aerospace: TYPE I, METHOD D (post-emulsifiable hidrofilik), sensitivity Level 3-4 per AMS 2644, developer FORM d (nonaqueous, sensitivitas tertinggi). Procedure weld vessel di lapangan: TYPE II, METHOD C (solvent-removable), developer FORM d. Cantumkan merek & nomor batch keluarga material — mencampur penetran keluarga A dengan developer keluarga B membatalkan qualification."},{"heading":"Dwell & temperatur — angka spesifik","body":"Tetapkan penetrant dwell di rentang 5-30 menit (mis. ''minimum 10 menit, maksimum 30 menit'') sesuai rekomendasi material; developer dwell minimum 10 menit sebelum evaluasi akhir. Suhu permukaan/material standar 10-52 derajat C per ASME V. Jika di luar rentang ini, procedure harus mensyaratkan qualification suhu khusus (high-temp penetran) menggunakan comparison block sesuai ASME V T-653. Untuk Method D, tetapkan emulsifier dwell yang tepat — terlalu lama akan meng-emulsify penetran dari dalam crack juga."},{"heading":"Pencahayaan & lingkungan evaluasi","body":"Untuk TYPE I: UV-A minimum 1000 uW/cm2 diukur pada 38 cm dari permukaan, ambient white light maksimum 20 lux, plus adaptasi gelap mata minimal 1 menit sebelum evaluasi. Untuk TYPE II: white light minimum 1000 lux pada permukaan yang dievaluasi. Procedure harus menyebut alat ukur (radiometer UV-A / lux meter terkalibrasi) dan interval verifikasi intensitas (mis. setiap shift untuk UV-A, dan cek bohlam UV-A setelah penggantian)."},{"heading":"Kriteria acceptance — kutip code","body":"Salin kriteria langsung dari referencing code agar tak ada interpretasi liar. Untuk ASME VIII Div.1 App.8: indikasi LINEAR relevan > 1.6 mm (1/16 in) = reject; ROUNDED > 5 mm (3/16 in) = reject; 4 atau lebih indikasi rounded relevan dalam satu garis berjarak <= 1.6 mm (1/16 in) tepi-ke-tepi = reject. Definisikan juga indikasi relevant vs non-relevant dan ambang ukuran minimum yang dievaluasi (umumnya > 1.6 mm dianggap relevan)."}]}', 480, NULL),
  (3, 'reading', 'Demonstration & Qualification Procedure', '{"slides":[{"heading":"Apa itu procedure demonstration","body":"ASME V T-621 menuntut procedure di-DEMONSTRATE ke kepuasan Inspector. Artinya: jalankan procedure persis seperti tertulis pada komponen/spesimen representatif, dan buktikan ia mendeteksi diskontinuitas yang relevan. Demonstration biasanya memakai cracked-chrome panel (Ni-Cr) atau TAM/PSM panel berisi crack terkalibrasi, atau komponen reject yang sudah dikenal cacatnya. Demonstration berbeda dari kalibrasi harian; ia membuktikan kapabilitas keseluruhan procedure."},{"heading":"Spesimen referensi","body":"Panel Ni-Cr cracked-chrome punya pola star-burst crack dengan ukuran bertingkat — digunakan untuk membuktikan sistem mendeteksi crack halus pada sensitivity level yang diklaim. TAM/PSM panel (umumnya pola spot bertingkat sensitivitas) memverifikasi performa sistem & komparasi sensitivitas antar batch. Demonstration mencatat: apakah semua crack/indikasi target tampak, brightness/kontras memadai, dan tidak ada masalah background atau over-removal."},{"heading":"Rekaman demonstration","body":"Hasil demonstration didokumentasikan: tanggal, operator, identitas spesimen, semua parameter aktual (dwell terukur, suhu, intensitas UV-A/lux terukur, rasio emulsifier untuk Method D via Brix/refractometer), foto/sketsa indikasi yang terdeteksi, serta tanda tangan Level II pelaksana dan Inspector. Rekaman ini menjadi bukti bahwa procedure valid dan dilampirkan/diacu oleh procedure."},{"heading":"Kapan requalification dipicu","body":"Setiap perubahan ESSENTIAL variable memicu requalification: ganti keluarga/merek material, ganti METHOD atau TYPE, naik/turun sensitivity level, perubahan suhu di luar rentang qualified, atau perubahan proses removal/pre-cleaning. Catat revisi procedure (rev number, tanggal, alasan) dan ulangi demonstration. Perubahan nonessential cukup direvisi dan dicatat tanpa demonstration ulang."}]}', 470, NULL),
  (4, 'reading', 'Studi Kasus Penyusunan Procedure', '{"slides":[{"heading":"Kasus: weld nozzle pressure vessel","body":"Permintaan: PT pada weld nozzle carbon steel, suhu ruang, lapangan tanpa darkroom. Keputusan procedure: TYPE II METHOD C (solvent-removable) — praktis lapangan, tak butuh air; developer FORM d (nonaqueous) untuk sensitivitas visible terbaik; white light >= 1000 lux pada permukaan; acceptance ASME VIII Div.1 App.8. Pre-clean solvent, dwell penetran 10 min, removal dengan lap/kain dibasahi solvent (JANGAN semprot solvent langsung ke permukaan saat removal karena dapat membilas penetran dari diskontinuitas), developer dwell >= 10 min."},{"heading":"Kasus: turbine blade aerospace","body":"Permintaan: deteksi fatigue crack sangat halus pada blade. Keputusan: TYPE I METHOD D (hidrofilik) sensitivity Level 4, developer FORM d; UV-A >= 1000 uW/cm2 @ 38 cm, ambient <= 20 lux, adaptasi gelap 1 menit. Kontrol kritis: rasio emulsifier hidrofilik (dip 5-20%, spray <= 5%) diverifikasi refractometer/Brix tiap batch/shift, water content WW dicek, dan demonstration pada panel Ni-Cr sebelum produksi."},{"heading":"Kesalahan umum penyusun","body":"Procedure ditolak auditor karena: (1) tidak menyebut keluarga/merek material spesifik (hanya ''penetran fluorescent''); (2) dwell ditulis ''secukupnya'' tanpa angka min/max; (3) tidak mencantumkan ambang acceptance dari referencing code; (4) lupa interval verifikasi UV-A/lux; (5) untuk Method D, tidak mendefinisikan metode kontrol konsentrasi emulsifier (Brix/refractometer); (6) tidak ada rekaman demonstration terlampir atau teracu."},{"heading":"Checklist final sebelum sign-off","body":"Sebelum procedure ditandatangani dan disetujui, verifikasi: semua essential variable terdefinisi dengan angka; referencing code & kriteria acceptance dikutip persis; pencahayaan + interval cek tertulis; demonstration sudah dijalankan & terdokumentasi; rev control ada; dan procedure dapat dibaca-laksana oleh Level I/II lain tanpa pertanyaan. Procedure yang baik menghapus ambiguitas, bukan menambah teks."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Procedure Development', '{"description":"7 soal penyusunan & qualification written procedure PT Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 7
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 7 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Menurut ASME V Article 6 (T-621), apa yang membuat sebuah written procedure PT menjadi valid untuk digunakan?',
   '["Cukup ditandatangani tanpa pengujian apa pun","Procedure cukup mengikuti template pabrikan penetran","Procedure valid otomatis jika mengutip ASME VIII","Procedure harus di-demonstrate ke kepuasan Inspector pada spesimen representatif"]', 3,
   'T-621 mensyaratkan procedure di-demonstrate (dijalankan persis seperti tertulis dan terbukti mendeteksi diskontinuitas relevan) ke kepuasan Inspector. Tanda tangan saja, mengikuti template, atau sekadar mengutip code tidak cukup.', 'Procedure Development', 'medium'),
  ('Manakah berikut yang merupakan ESSENTIAL variable yang, jika diubah, memicu requalification procedure PT per ASME V Article 6?',
   '["Mengganti keluarga/merek material penetran ke pabrikan lain","Memilih kuas alih-alih semprot untuk aplikasi penetran dalam batas yang diizinkan","Mengubah urutan penomoran spesimen pada laporan","Mengganti warna/format formulir laporan"]', 0,
   'Mengganti keluarga/merek material (penetran-emulsifier-developer harus satu keluarga ter-qualify) adalah essential variable dan memicu requalification. Teknik aplikasi dalam batas, penomoran, dan format formulir adalah nonessential.', 'Procedure Development', 'medium'),
  ('Sebuah procedure untuk TYPE I (fluorescent) METHOD D harus menetapkan kontrol konsentrasi emulsifier hidrofilik. Alat/metode kontrol yang tepat dicantumkan adalah?',
   '["Mengukur pH dengan kertas lakmus","Menghitung waktu dwell dengan stopwatch saja","Refractometer/Brix untuk verifikasi rasio emulsifier (dip 5-20%, spray <= 5%)","Mengukur viskositas penetran dengan cup Zahn"]', 2,
   'Emulsifier hidrofilik (Method D) dikontrol dengan refractometer/Brix; rasio dip 5-20% dan spray <= 5%. Konsentrasi yang salah menyebabkan over- atau under-removal, sehingga metode kontrol harus tercantum eksplisit di procedure.', 'Process Control', 'hard'),
  ('Untuk procedure TYPE I (fluorescent), kondisi pencahayaan evaluasi yang HARUS dicantumkan adalah?',
   '["White light minimum 1000 lux pada permukaan","UV-A minimum 1000 uW/cm2 @ 38 cm, ambient white light <= 20 lux, adaptasi gelap 1 menit","UV-A minimum 500 uW/cm2 tanpa batas ambient","Cahaya matahari langsung untuk kontras maksimum"]', 1,
   'TYPE I dievaluasi di bawah UV-A >= 1000 uW/cm2 diukur pada 38 cm, ambient white light <= 20 lux, dengan adaptasi gelap mata minimal 1 menit. White light 1000 lux adalah syarat untuk TYPE II (visible), bukan TYPE I.', 'Lighting Requirements', 'medium'),
  ('Saat menulis kriteria acceptance untuk vessel per ASME VIII Div.1 Mandatory Appendix 8, indikasi LINEAR relevan ditolak (reject) jika panjangnya melebihi?',
   '["3 mm (1/8 in)","5 mm (3/16 in)","10 mm (3/8 in)","1.6 mm (1/16 in)"]', 3,
   'Per ASME VIII Div.1 App.8, indikasi LINEAR relevan > 1.6 mm (1/16 in) di-reject. Ambang 5 mm (3/16 in) berlaku untuk indikasi ROUNDED. Kriteria ini harus dikutip persis dalam procedure.', 'Code Interpretation', 'medium'),
  ('Spesimen referensi mana yang paling tepat untuk men-demonstrate bahwa sistem PT yang dipilih mampu mendeteksi crack halus pada sensitivity yang diklaim?',
   '["Blok step-wedge densitometri","Hole-type IQI radiografi","Panel cracked-chrome (Ni-Cr) dengan pola crack terkalibrasi","Blok kalibrasi sudut UT IIW"]', 2,
   'Panel Ni-Cr cracked-chrome memiliki pola star-burst crack bertingkat untuk membuktikan deteksi crack halus; TAM/PSM panel untuk verifikasi performa & komparasi sensitivitas. IQI radiografi dan blok UT bukan untuk PT.', 'Demonstration & Qualification', 'medium'),
  ('Sebuah procedure menulis ''aplikasikan penetran lalu tunggu secukupnya sebelum developer''. Mengapa auditor menolak procedure ini?',
   '["Karena penetran harus selalu dwell tepat 60 menit","Karena dwell tidak boleh ditulis dalam procedure","Karena dwell harus dinyatakan dengan angka min/max (penetran 5-30 min; developer >= 10 min)","Karena hanya Level III yang boleh menentukan angka dwell"]', 2,
   'Procedure harus menghapus ambiguitas: dwell penetran dinyatakan dalam rentang 5-30 menit (mis. min 10/maks 30) dan developer dwell minimum 10 menit. Kata ''secukupnya'' tidak dapat direproduksi sehingga ditolak auditor.', 'Procedure Development', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 9 — Quality Control & Audit (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Filosofi QC & Hierarki Verifikasi Sistem PT', '{"slides":[{"heading":"Kenapa QC mutlak di Level II","body":"Sebagai Level II Anda menandatangani hasil dan menjamin sistem PT bekerja. Indikasi yang HILANG (false negative) berbahaya karena crack lolos ke service. QC berkala memastikan sensitivitas sistem tidak terdegradasi diam-diam. ASME V Article 6 dan ASTM E1417 mewajibkan verifikasi performa sistem terjadwal dengan rekaman terdokumentasi; T-621 (ASME V Art.6) menetapkan persyaratan prosedur tertulis yang mencakup pengendalian mutu ini."},{"heading":"Tiga tingkat verifikasi","body":"1) Verifikasi HARIAN (start-of-shift): cek performa keseluruhan sistem dengan panel referensi beretak + cek lampu (UV-A / cahaya putih). 2) Cek BERKALA (mingguan/bulanan): konsentrasi bath emulsifier, kandungan air water-washable, kondisi developer, brightness penetran. 3) AUDIT SOP periodik (kuartalan/tahunan): kesesuaian prosedur tertulis vs praktik lapangan, kalibrasi instrumen, kompetensi personel."},{"heading":"Konsep panel referensi","body":"Performa sistem (penetran + emulsifier + developer + lighting digabung) diuji dengan panel beretak. Dua panel standar: TAM/PSM panel (a.k.a. PSM-5, pelat shot-peen dengan lima titik crack terkalibrasi berbeda ukuran untuk mengukur sensitivitas) dan Ni-Cr cracked-chrome panel (pelat berlapis krom dengan jaringan retak halus untuk membandingkan dua proses/sensitivitas). Panel diproses lalu jumlah/terangnya indikasi dibandingkan terhadap foto master referensi."},{"heading":"Dokumentasi adalah bukti","body":"Setiap cek dicatat: tanggal, batch/lot material, hasil ukur (angka aktual), pass/fail, inisial operator. Tanpa rekaman, sistem dianggap TIDAK terverifikasi saat audit pihak ketiga (client/Notified Body/AI). Rekaman QC disimpan minimal sepanjang masa berlaku laporan inspeksi (umumnya >=5 tahun atau sesuai kontrak/kode)."}]}', 450, NULL),
  (2, 'reading', 'Verifikasi Harian (Start-of-Shift)', '{"slides":[{"heading":"Cek performa sistem dengan panel","body":"Awal shift (dan saat ganti batch material atau curiga ada masalah), proses panel TAM/PSM melalui SELURUH siklus PT yang sama dengan benda kerja. Bandingkan indikasi terhadap foto master. Jumlah dan brightness titik retak harus setara master; jika berkurang -> sistem GAGAL, hentikan inspeksi dan investigasi (penetran lemah/terkontaminasi, emulsifier salah konsentrasi, over-wash, atau UV-A drop)."},{"heading":"Cek lampu UV-A (fluorescent, Type I)","body":"Ukur intensitas UV-A di permukaan kerja minimal 1000 uW/cm2 pada jarak 38 cm (15 in), tiap awal shift dan setiap 8 jam (serta setelah ganti bohlam/LED). Sumber yang turun di bawah 1000 uW/cm2 harus diganti. Cek juga cahaya putih ambient di booth: maksimum 20 lux (2 fc). Operator wajib adaptasi gelap minimal 1 menit sebelum evaluasi."},{"heading":"Cek cahaya putih (visible, Type II)","body":"Untuk penetran visible (Type II), intensitas cahaya putih di permukaan inspeksi minimal 1000 lux (100 fc). Ukur dengan luxmeter terkalibrasi di area evaluasi. Hindari silau dan bayangan. Cahaya terlalu rendah membuat kontras indikasi merah-pada-latar-putih developer tidak terbaca; ini sumber umum false negative pada Method visible."},{"heading":"Cek filter UV & kontaminasi latar","body":"Filter UV-A wajib utuh (tanpa retak/crazing) agar cahaya putih dari lampu UV tidak bocor dan menurunkan kontras fluoresensi. Permukaan kerja, sarung tangan, dan meja harus bebas fluoresensi latar (penetran tercecer menimbulkan background glow yang menutup indikasi). Bersihkan dan cek background fluorescence tiap shift di bawah UV-A."}]}', 470, NULL),
  (3, 'reading', 'Cek Bath Berkala — Konsentrasi & Kondisi Material', '{"slides":[{"heading":"Konsentrasi emulsifier hidrofilik (Method D)","body":"Emulsifier hidrofilik (detergen) dikontrol dengan REFRAKTOMETER (skala Brix). Dip tank: 5-20% konsentrasi; aplikasi spray: maksimum 5%. Periksa berkala (mingguan/sesuai SOP) dan koreksi bila menyimpang dari nilai prosedur. Brix terlalu tinggi -> over-emulsifikasi (penetran ke-strip dari dalam crack, indikasi hilang); terlalu rendah -> removal tidak tuntas (background tinggi)."},{"heading":"Method B (lipophilic) & water content","body":"Emulsifier lipophilic (Method B) berbasis minyak; dikontrol via WAKTU kontak (emulsifier dwell), bukan konsentrasi. Untuk penetran WATER-WASHABLE (Method A), kandungan air dalam bath dibatasi (umumnya <=5% volume, sesuai data sheet pabrik). Kelebihan air menyebabkan gelling/separasi dan menurunkan sensitivitas — cek berkala dan buang/ganti bila melampaui batas."},{"heading":"Kondisi developer","body":"Developer kering (form a): jaga tetap fluffy & kering, ganti bila menggumpal/menyerap kelembapan. Developer larut air (form b) & suspensi air (form c): cek konsentrasi/berat jenis per data sheet, aduk agar tidak mengendap. Developer nonaqueous solvent (form d, sensitivitas tertinggi): pastikan semburan aerosol merata, kocok sebelum pakai. Developer apa pun yang terkontaminasi penetran -> ganti."},{"heading":"Kontaminasi & brightness penetran","body":"Penetran dalam tank dicek visual untuk kontaminasi air/kotoran dan dibandingkan brightness-nya terhadap referensi penetran segar (mis. via comparison panel atau fluorimeter). Jika brightness turun signifikan atau ada lapisan air/gelling, lakukan water-tolerance test dan ganti bath. Catat lot number setiap penggantian material untuk traceability."}]}', 500, NULL),
  (4, 'reading', 'Audit SOP, Kalibrasi Instrumen & Tabel Interval QC', '{"slides":[{"heading":"Audit prosedur (SOP) tertulis vs praktik","body":"Audit periodik (kuartalan/tahunan atau saat perubahan material/peralatan) membandingkan prosedur tertulis dengan praktik aktual: dwell penetran (5-30 min) & developer (>=10 min), suhu benda kerja (umumnya 10-52 C), urutan langkah metode, dan kriteria penerimaan kode (mis. ASME VIII Div.1 Mandatory App.8: linear relevan >1.6 mm reject, rounded >5 mm reject). Setiap ketidaksesuaian -> CAPA (corrective/preventive action) terdokumentasi."},{"heading":"Kalibrasi instrumen QC","body":"Instrumen ukur harus terkalibrasi & traceable: UV-A radiometer dan luxmeter (kalibrasi umumnya tahunan, traceable NIST/ISO), refraktometer (verifikasi titik nol dengan air suling), termometer, dan timer/jam. Stiker kalibrasi & sertifikat tersedia saat audit. Instrumen yang sudah kadaluwarsa kalibrasi membuat seluruh data QC dianggap tidak valid."},{"heading":"Tabel interval QC ringkas","body":"HARIAN/shift: panel TAM/PSM (performa sistem), UV-A >=1000 uW/cm2 @38cm, ambient <=20 lux (atau white >=1000 lux untuk visible), background fluorescence, kondisi developer. BERKALA (mingguan/bulanan): konsentrasi emulsifier (Brix via refraktometer), water content penetran WW, brightness penetran vs referensi. TAHUNAN: kalibrasi radiometer/luxmeter, audit SOP penuh, review kompetensi & eye exam personel."},{"heading":"Kompetensi & kewenangan","body":"Audit juga memverifikasi sertifikasi personel masih berlaku (Level I/II/III sesuai SNT-TC-1A / NAS-410 / ISO 9712), eye exam tahunan (near-vision Jaeger J1 atau setara + color/contrast), dan bahwa hanya Level II/III yang menandatangani interpretasi akhir. Semua temuan, tindakan koreksi, dan verifikasi penutupan didokumentasikan untuk traceability."}]}', 490, NULL),
  (5, 'quiz', 'Mini-quiz — Quality Control & Audit', '{"description":"6 soal tentang verifikasi harian, cek bath berkala, kalibrasi instrumen, dan audit SOP sistem PT Level II.","questionCount":6,"passingScore":80}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 9
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 9 mini-quiz (6 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Panel referensi mana yang dipakai untuk memverifikasi PERFORMA KESELURUHAN sistem PT (penetran + emulsifier + developer + lighting digabung) pada verifikasi awal shift?',
   '["Refraktometer Brix dan luxmeter yang dibaca bersamaan","Step wedge IQI dan plaque IQI seperti pada radiografi","TAM/PSM panel dan/atau Ni-Cr cracked-chrome panel, diproses lalu dibandingkan terhadap foto master","Chart brightness AMS 2644 yang ditempel di dinding booth"]', 2,
   'Performa sistem (semua komponen digabung) diverifikasi dengan MEMPROSES panel beretak TAM/PSM (PSM-5) atau Ni-Cr cracked-chrome melalui siklus PT yang sama dengan benda kerja, lalu membandingkan jumlah/terangnya indikasi terhadap foto master referensi. IQI step/plaque adalah alat radiografi, bukan PT; refraktometer dan luxmeter hanya mengukur satu parameter, bukan performa sistem total.', 'System Performance', 'easy'),
  ('Saat verifikasi harian booth fluorescent (Type I), kombinasi batas yang BENAR untuk intensitas UV-A di permukaan kerja dan cahaya putih ambient adalah:',
   '["UV-A >=1000 uW/cm2 @ 38 cm dan cahaya putih ambient <=20 lux","UV-A >=100 uW/cm2 @ 38 cm dan ambient <=1000 lux","UV-A >=1000 lux dan ambient <=100 uW/cm2","UV-A >=500 uW/cm2 @ 50 cm dan ambient <=50 lux"]', 0,
   'Untuk penetran fluorescent, intensitas UV-A minimal 1000 uW/cm2 diukur di permukaan kerja pada jarak 38 cm (15 in), dan cahaya putih ambient di booth dibatasi maksimum 20 lux (2 fc), ditambah adaptasi gelap >=1 menit. Satuan uW/cm2 untuk UV-A dan lux untuk cahaya tampak tidak dapat dipertukarkan; 100 uW/cm2 dan jarak 50 cm bukan batas yang benar.', 'Lighting QC', 'medium'),
  ('Konsentrasi emulsifier HIDROFILIK (Method D) dalam dip tank dikontrol dengan instrumen dan rentang yang mana?',
   '["pH meter, target pH 5-7","Refraktometer (skala Brix), dip 5-20% (spray maksimum 5%)","Hidrometer, 30-50% volume","Stopwatch saja karena konsentrasi tidak relevan untuk Method D"]', 1,
   'Emulsifier hidrofilik (detergen) dikontrol konsentrasinya dengan refraktometer pada skala Brix: dip tank 5-20%, spray maksimum 5%. Method B (lipophilic) justru dikontrol via WAKTU kontak, bukan konsentrasi. Brix terlalu tinggi -> over-emulsifikasi (penetran ke-strip dari crack); terlalu rendah -> removal tidak tuntas. pH meter dan hidrometer bukan alat kontrol konsentrasi emulsifier hidrofilik.', 'Bath Control', 'medium'),
  ('Pada cek bath berkala penetran WATER-WASHABLE (Method A), parameter apa yang dipantau dan apa konsekuensi bila di luar batas?',
   '["pH harus >9 agar emulsifikasi sempurna","Konsentrasi Brix 20-40%; jika rendah menyebabkan over-wash","Tidak ada parameter yang perlu dipantau untuk Method A","Kandungan air (umumnya <=5% vol); kelebihan air menyebabkan gelling/separasi dan menurunkan sensitivitas"]', 3,
   'Penetran water-washable memiliki emulsifier built-in dan membatasi kandungan air dalam bath (umumnya <=5% volume per data sheet pabrik). Kelebihan air menyebabkan gelling/separasi dan menurunkan sensitivitas, sehingga bath dicek berkala dan dibuang bila melampaui batas. Brix/refraktometer dipakai untuk emulsifier hidrofilik (Method D), bukan untuk water content Method A; pH bukan parameter kontrol di sini.', 'Bath Control', 'hard'),
  ('Saat audit pihak ketiga, instrumen QC mana yang WAJIB terkalibrasi traceable agar data verifikasi dianggap valid?',
   '["Hanya termometer ruangan booth saja","UV-A radiometer dan luxmeter (kalibrasi umumnya tahunan, traceable NIST/ISO)","Tidak ada — pembacaan visual operator sudah dianggap cukup","Hanya stopwatch dwell saja, instrumen lain tidak penting"]', 1,
   'UV-A radiometer dan luxmeter harus terkalibrasi dan traceable (umumnya tahunan, NIST/ISO) lengkap dengan sertifikat dan stiker kalibrasi; refraktometer juga di-zero dengan air suling. Instrumen yang kadaluwarsa kalibrasi membuat seluruh data QC tidak valid saat audit. Pembacaan visual tanpa instrumen terkalibrasi tidak diterima sebagai bukti objektif.', 'Calibration', 'medium'),
  ('Audit SOP menemukan operator memakai dwell developer 6 menit padahal prosedur tertulis mensyaratkan minimal 10 menit. Tindakan Level II yang BENAR adalah:',
   '["Catat sebagai ketidaksesuaian, terbitkan CAPA terdokumentasi, koreksi praktik ke >=10 menit, dan verifikasi penutupannya","Abaikan karena selisihnya kecil dan dianggap tidak memengaruhi hasil","Ubah prosedur tertulis menjadi 6 menit agar cocok dengan praktik, tanpa justifikasi teknis","Hentikan seluruh program PT secara permanen"]', 0,
   'Dwell developer minimal 10 menit; praktik 6 menit adalah ketidaksesuaian terhadap SOP yang berpotensi menyebabkan indikasi belum berkembang penuh (false negative). Prosedur audit yang benar: dokumentasikan temuan, terbitkan corrective/preventive action (CAPA), koreksi praktik kembali ke >=10 menit, dan verifikasi penutupan untuk traceability. Mengubah SOP agar ''cocok'' dengan praktik salah atau mengabaikannya melanggar pengendalian mutu.', 'SOP Audit', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 10 — Field Inspection Case Studies (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Studi Kasus 1 — Pressure Vessel Nozzle (linear vs rounded)', '{"slides":[{"heading":"Komponen & setup","body":"Nozzle-to-shell weld pada pressure vessel SA-516 Gr.70, tebal 25 mm. Sistem: Type II visible, Method C (solvent-removable), developer Form d (nonaqueous solvent-based, sensitivitas tertinggi). Dwell penetran 10 menit; developer dwell 12 menit (>= 10 menit, di atas minimum). White light diukur 1150 lux di permukaan (>= 1000 lux untuk visible). Kode acuan: ASME V Article 6 untuk TEKNIK (T-621/T-680), ASME VIII Div.1 Mandatory Appendix 8 untuk ACCEPTANCE. Ingat: Article 6 tidak memuat kriteria accept/reject — kriteria diambil dari construction code (VIII)."},{"heading":"Indikasi yang muncul","body":"Tiga indikasi terdeteksi di toe weld: (A) garis merah memanjang 2,3 mm (panjang >= 3x lebar -> linear); (B) titik bulat diameter 4 mm (rounded); (C) titik bulat diameter 6 mm (rounded). Semua dikonfirmasi relevant (bukan false/over-wash; bukan bleed-back undercut geometrik yang sudah dibersihkan). Level II mengukur dimensi maksimum tiap indikasi pada dimensi terpanjang setelah developer dwell minimum tercapai dan kontras penuh berkembang."},{"heading":"Evaluasi vs Appendix 8","body":"Aturan App 8: indikasi dianggap RELEVANT bila dimensi mayor > 1,6 mm (1/16 in). Acceptance: relevant LINEAR (panjang >= 3x lebar) dengan dimensi > 1,6 mm = REJECT; relevant ROUNDED > 5 mm (3/16 in) = REJECT. Selain itu, crack/lack of fusion/incomplete penetration SELALU reject tanpa memandang ukuran. Indikasi A = linear 2,3 mm > 1,6 mm -> REJECT. Indikasi B = rounded 4 mm < 5 mm -> ACCEPT (recordable). Indikasi C = rounded 6 mm > 5 mm -> REJECT."},{"heading":"Keputusan & repair-verify","body":"Komponen REJECT karena A dan C. Disposisi: grind-out cacat A & C, batasi kedalaman agar tidak melanggar minimum wall thickness, weld repair oleh welder berkualifikasi, lalu RE-PT seluruh area repair plus area sekitarnya (umumnya 13-25 mm). Indikasi B tetap dicatat di report sebagai accepted relevant indication (recordable) walau lolos. Jejak audit harus mencantumkan tipe, dimensi terukur, kode acceptance, dan keputusan untuk tiap indikasi."}]}', 470, NULL),
  (2, 'reading', 'Studi Kasus 2 — Aligned Rounded Indications (cluster)', '{"slides":[{"heading":"Komponen & temuan","body":"Butt weld pelat baja karbon tebal 18 mm. Sistem: Type I fluorescent, Method D (post-emulsifiable hydrophilic) untuk sensitivitas tinggi; konsentrasi emulsifier dipantau refractometer (Brix). Lighting: UV-A 1250 uW/cm2 @ 38 cm (>= 1000), ambient white light 12 lux (<= 20), dark adaptation 1 menit. Ditemukan deretan 5 indikasi rounded di sepanjang satu garis, masing-masing diameter 2-3 mm, jarak antar tepi (edge-to-edge) 1,2 mm."},{"heading":"Aturan aligned rounded","body":"App 8 memiliki kriteria khusus di luar ukuran tunggal: EMPAT atau lebih indikasi rounded dalam satu garis dengan spasi edge-to-edge <= 1,6 mm (1/16 in) = REJECT, meskipun setiap indikasi individual < 5 mm. Tujuannya menangkap porositas linear/aligned yang menandakan jalur kelemahan terus-menerus pada las."},{"heading":"Evaluasi vs Appendix 8","body":"Setiap indikasi 2-3 mm individual = ACCEPT (di bawah 5 mm dan bukan crack). NAMUN 5 indikasi (>= 4) dalam satu garis dengan spasi 1,2 mm (<= 1,6 mm) memicu kriteria aligned rounded -> REJECT. Kesalahan Level I yang umum: menerima karena tiap titik kecil; Level II harus mengenali pola aligned dan mengevaluasi grup, bukan hanya indikasi tunggal."},{"heading":"Disposisi","body":"REJECT. Repair: excavate seluruh cluster, verifikasi root cause (porositas linear sering akibat kontaminasi, kelembapan, atau shielding gas tidak memadai), weld repair, RE-PT area repair + sekitarnya. Catat di report bahwa rejection berbasis ''aligned rounded indications'' (>= 4 dalam garis, spasi <= 1,6 mm), bukan ukuran tunggal, agar audit trail jelas dan dapat diverifikasi inspektor lain."}]}', 470, NULL),
  (3, 'reading', 'Studi Kasus 3 — Relevant vs Non-Relevant (false indication)', '{"slides":[{"heading":"Komponen & indikasi meragukan","body":"Forged flange ring. Sistem: Type II visible, Method A (water-washable). Muncul indikasi merah samar mengikuti garis fillet press-fit dan beberapa bercak menyebar di area yang sebelumnya kontak dengan glove. Level II wajib memisahkan tiga kategori SEBELUM evaluasi acceptance: RELEVANT (diskontinuitas aktual), NON-RELEVANT (fitur geometri/desain sah), dan FALSE (over-wash residue, lint, kontaminasi)."},{"heading":"Teknik diskriminasi","body":"Bersihkan spot meragukan dengan solvent-dampened cloth, keringkan tuntas, lalu re-develop (Form d untuk sensitivitas tertinggi). FALSE indication (residu over-wash, kontaminasi) tidak akan muncul kembali. NON-RELEVANT geometrik (press-fit, design groove, root thread) muncul kembali tetapi konsisten mengikuti fitur geometri. RELEVANT (crack/porositas) menunjukkan bleed-back progresif & konsisten dari rongga. Bila ragu antara geometri vs crack: perlakukan sebagai relevant sampai terbukti sebaliknya — beban pembuktian ada pada inspektor (ASME V Article 6, T-680)."},{"heading":"Hasil","body":"Bercak glove = FALSE (hilang setelah re-test) -> tidak dievaluasi. Garis fillet press-fit = NON-RELEVANT geometrik -> dicatat tetapi tidak di-reject. Satu indikasi linear 1,8 mm di luar zona geometrik = RELEVANT (> 1,6 mm sehingga relevant) dan, sebagai linear > 1,6 mm, -> REJECT per App 8. Catatan: jika indikasi tersebut dikarakterisasi sebagai crack, ia tetap reject tanpa memandang ukuran."},{"heading":"Pelajaran kunci","body":"Mereject false/non-relevant indication menyebabkan repair tidak perlu dan biaya membengkak (over-reject). Sebaliknya, salah mengklasifikasi crack relevant sebagai ''geometrik'' adalah escape kritis (under-reject) yang dapat menyebabkan kegagalan in-service. Dokumentasikan justifikasi setiap klasifikasi non-relevant/false — auditor akan memintanya dan keputusan harus dapat diverifikasi secara independen."}]}', 450, NULL),
  (4, 'reading', 'Studi Kasus 4 — Repair Verification & Sign-off', '{"slides":[{"heading":"Konteks repair-verify","body":"Setelah weld repair pada vessel SA-516 (lanjutan kasus 1), area repair harus di-PT ulang. Aturan: RE-PT mencakup SELURUH metal repair PLUS area sekitarnya (umumnya 13-25 mm) untuk menangkap cacat tepi grinding/excavation (grinding burn, lap, crack tepi). System performance harus diverifikasi terlebih dahulu sebelum re-PT dimulai."},{"heading":"Verifikasi sistem sebelum re-PT","body":"Sebelum re-PT, Level II cek QC pada known-defect panel: TAM/PSM panel (sensitivitas penetran) dan Ni-Cr cracked-chrome panel (performa seluruh sistem proses), dibandingkan terhadap referensi tersimpan. Lighting fluorescent: UV-A >= 1000 uW/cm2 @ 38 cm, ambient <= 20 lux, dark adaptation 1 menit; untuk visible: white light >= 1000 lux. Untuk Method D, konsentrasi emulsifier dipantau refractometer. Jika panel gagal menampilkan indikasi referensi, sistem tidak sah — re-PT ditunda hingga dikoreksi."},{"heading":"Hasil re-PT","body":"Area repair bersih: tidak ada indikasi relevant linear. Namun di tepi excavation muncul rounded 3 mm baru (grinding-related) — di bawah 5 mm, bukan crack -> ACCEPT, tetapi tetap dicatat (recordable). Tidak ada indikasi linear dan tidak ada aligned cluster. Hasil: area repair memenuhi App 8 -> ACCEPT."},{"heading":"Dokumentasi & sign-off","body":"Report final harus mencantumkan: prosedur (no. & rev), parameter (Type/Method/developer Form, dwell penetran & developer), hasil QC panel & lighting, sketsa/peta lokasi indikasi awal vs setelah repair, disposisi (reject -> repair -> re-PT -> accept), dan tanda tangan Level II. Tanpa rantai dokumentasi lengkap, sign-off tidak dapat diaudit dan repair dianggap belum tervalidasi."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — Field Case Studies & Repair Verification', '{"description":"7 soal studi kasus lapangan: evaluasi indikasi vs ASME VIII Div.1 Appendix 8, klasifikasi relevant/non-relevant/false, aligned rounded, dan repair verification.","questionCount":7,"passingScore":75}', 700, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 10
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 10 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada nozzle weld ditemukan satu relevant LINEAR indication sepanjang 2,3 mm (panjang >= 3x lebar). Menurut ASME VIII Div.1 Mandatory Appendix 8, bagaimana disposisinya?',
   '["REJECT, karena relevant linear > 1,6 mm (1/16 in)","ACCEPT, karena linear di bawah 5 mm","ACCEPT, karena perlu minimal 3 indikasi untuk reject","Tunda penilaian sampai re-PT setelah 24 jam"]', 0,
   'App 8 menolak relevant LINEAR indication dengan dimensi > 1,6 mm (1/16 in). Indikasi linear 2,3 mm melebihi batas tersebut -> REJECT. Batas 5 mm (3/16 in) berlaku untuk indikasi ROUNDED, bukan linear. Tidak ada syarat ''minimal 3 indikasi'' untuk reject indikasi linear tunggal.', 'Code Interpretation', 'medium'),
  ('Sebuah relevant ROUNDED indication berdiameter 4 mm berdiri sendiri pada butt weld pressure vessel. Apa disposisi yang benar per Appendix 8?',
   '["REJECT, karena setiap rounded indication harus diperbaiki","REJECT, karena 4 mm > 1,6 mm","ACCEPT, karena rounded relevant ditolak hanya jika > 5 mm (3/16 in); tetap dicatat","ACCEPT tanpa perlu dicatat di report"]', 2,
   'App 8 menolak rounded relevant hanya bila dimensinya > 5 mm (3/16 in). Rounded 4 mm tunggal lolos (ACCEPT), tetapi tetap recordable dan harus dicatat di report. Batas 1,6 mm berlaku untuk linear, bukan rounded.', 'Code Interpretation', 'medium'),
  ('Ditemukan deretan 5 rounded indication berdiameter 2-3 mm dalam satu garis, dengan spasi edge-to-edge 1,2 mm. Mengapa kondisi ini REJECT meski tiap indikasi < 5 mm?',
   '["Karena total panjang gabungan melebihi 10 mm","Karena rounded berurutan otomatis dihitung sebagai satu linear 12 mm","Karena 4 atau lebih rounded dalam satu garis dengan spasi <= 1,6 mm ditolak (aligned)","Karena 5 indikasi melampaui batas jumlah maksimum per area"]', 2,
   'App 8 memiliki kriteria aligned/clustered: 4 atau lebih rounded indication dalam satu garis dengan spasi edge-to-edge <= 1,6 mm (1/16 in) = REJECT, meski setiap indikasi individual di bawah batas 5 mm. Pola ini menandakan jalur kelemahan (mis. porositas linear). Rounded tidak otomatis dijumlahkan menjadi satu linear, dan tidak ada ''batas jumlah maksimum per area''.', 'Code Interpretation', 'hard'),
  ('Saat membedakan indikasi, langkah mana yang paling tepat untuk memastikan sebuah bercak adalah FALSE indication (mis. over-wash residue/kontaminasi) dan bukan diskontinuitas relevant?',
   '["Menaikkan intensitas UV-A hingga di atas 2000 uW/cm2","Memperpanjang dwell penetran menjadi 60 menit","Mengukur kedalaman indikasi dengan pit depth gauge","Membersihkan ringan area lalu re-develop; false indication tidak muncul kembali"]', 3,
   'Bersihkan spot dengan solvent-dampened cloth, keringkan, lalu re-develop: false indication (residu/kontaminasi) tidak akan muncul kembali, sedangkan diskontinuitas relevant akan bleed out lagi secara progresif/konsisten. Indikasi non-relevant geometrik muncul kembali tetapi mengikuti fitur geometri. Menaikkan UV-A atau memperpanjang dwell tidak membedakan false vs relevant; PT tidak mengukur kedalaman.', 'Indication Evaluation', 'medium'),
  ('Pada inspeksi pressure vessel per ASME VIII Div.1 Appendix 8, ditemukan crack yang terukur hanya 0,9 mm. Disposisi yang benar adalah:',
   '["ACCEPT, karena di bawah ambang relevan 1,6 mm","ACCEPT, karena di bawah batas rounded 5 mm","REJECT, karena crack/lack of fusion/incomplete penetration selalu ditolak tanpa memandang ukuran","Diabaikan sebagai non-relevant geometri"]', 2,
   'App 8 menyatakan crack, lack of fusion, dan incomplete penetration SELALU REJECT tanpa memandang ukuran karena sifatnya planar/linear yang kritis. Ambang 1,6 mm berlaku untuk indikasi linear umum, tetapi crack adalah kategori yang otomatis ditolak meski kecil.', 'Code Interpretation', 'hard'),
  ('Setelah weld repair pada area yang sebelumnya REJECT, apa cakupan minimum yang benar untuk re-PT verifikasi repair?',
   '["Hanya bead repair tepat di garis las baru","Seluruh metal repair ditambah area sekitarnya (umumnya 13-25 mm) di sekeliling repair","Seluruh komponen wajib di-PT ulang dari awal setiap kali","Cukup visual inspection tanpa PT karena sudah pernah di-PT"]', 1,
   'Re-PT verifikasi repair harus mencakup seluruh metal repair PLUS area sekitarnya (umumnya 13-25 mm) untuk menangkap cacat akibat grinding/excavation di tepi repair (grinding burn, lap, crack tepi). Tidak perlu meng-PT seluruh komponen dari awal, dan visual saja tidak cukup menggantikan PT.', 'Repair Verification', 'medium'),
  ('Sebelum melakukan re-PT pada area repair menggunakan sistem fluorescent (Type I), pemeriksaan QC mana yang WAJIB diverifikasi terlebih dulu agar hasil sah?',
   '["White light >= 1000 lux dan IQI sensitivity 2T","Density step wedge dan calibration block V1","Panel TAM/PSM & Ni-Cr cracked-chrome menampilkan indikasi referensi, UV-A >= 1000 uW/cm2 @ 38 cm, dan ambient <= 20 lux","Couplant viscosity dan refractometer Brix saja"]', 2,
   'Untuk sistem fluorescent: verifikasi known-defect panel TAM/PSM (sensitivitas penetran) & Ni-Cr cracked-chrome (performa sistem) menampilkan indikasi referensi, UV-A >= 1000 uW/cm2 @ 38 cm, dan ambient <= 20 lux (plus 1 menit dark adaptation). White light >= 1000 lux untuk visible (Type II), bukan fluorescent. Density step wedge/IQI/V1 dan couplant adalah milik RT/UT; refractometer Brix relevan untuk emulsifier Method D tetapi bukan verifikasi sistem yang menggantikan panel.', 'Quality Control', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — PT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
-- Steps: ON CONFLICT DO NOTHING (safe, never deletes user progress).
-- Quiz questions: DELETE+INSERT per quiz step (idempotent).
