-- PT-L2 Module 8 — Advanced Code Interpretation (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'ASME V Article 6 (Technique) vs ASME VIII App 8 (Acceptance)', '{"slides":[{"heading":"Dua dokumen, dua peran","body":"ASME Section V Article 6 = HOW (cara melakukan PT yang benar / technique). ASME Section VIII Division 1 Mandatory Appendix 8 = WHAT IS ACCEPTABLE (kriteria terima/tolak). Article 6 tidak memuat acceptance criteria final — ia secara eksplisit merujuk ke construction code (VIII, B31.x, dll). Kesalahan umum Level II: mencari nomor reject di Article 6. Tidak ada di sana; acceptance ada di Appendix 8."},{"heading":"Isi inti Article 6 (technique)","body":"T-621 mensyaratkan written procedure dengan essential variables terdokumentasi dan terkualifikasi. T-651 precleaning, T-652 drying, T-653 penetrant application & dwell, T-673 developer, T-676 interpretation/evaluation. Suhu standar permukaan 10-52 C (50-125 F). Dwell penetran umumnya 5-30 menit. Bila suhu atau dwell di luar rentang standar, prosedur wajib dikualifikasi dengan demonstrasi sistem."},{"heading":"Appendix 8 — acceptance angka kunci","body":"Mandatory Appendix 8 ASME VIII Div.1 (para 8-4): indikasi RELEVAN adalah yang dimensi mayor > 1.6 mm (1/16 in). Semua crack dan linear indication relevan = REJECT. ROUNDED (panjang <= 3x lebar): reject jika > 5 mm (3/16 in). Empat atau lebih indikasi rounded relevan segaris dengan jarak tepi-ke-tepi <= 1.6 mm (1/16 in) = reject. Indikasi <= 1.6 mm dianggap non-relevant."},{"heading":"Alur kerja Level II yang benar","body":"1) Jalankan PT sesuai Article 6 (technique + demonstrasi sistem bila perlu). 2) Tentukan apakah indikasi RELEVAN (dimensi mayor > 1.6 mm). 3) Klasifikasikan linear vs rounded berdasarkan panjang:lebar. 4) Terapkan acceptance dari construction code (Appendix 8 untuk VIII Div.1). 5) Dokumentasikan & sign report. Mencampur acceptance pipa (B31.3) ke vessel (VIII) = temuan audit serius."}]}', 460, NULL),
  (2, 'reading', 'Indikasi Relevan, Non-Relevan, dan False', '{"slides":[{"heading":"Tiga kategori indikasi","body":"RELEVANT: disebabkan diskontinuitas aktual (crack, porosity, lack of fusion, lap). NON-RELEVANT: disebabkan geometri/kondisi desain (press fit, keyway, ulir, sambungan, surface roughness) — nyata tetapi bukan cacat. FALSE/spurious: artefak proses (lint, over-removal yang bleed, kontaminasi developer, sidik jari). Hanya indikasi RELEVANT yang dievaluasi terhadap acceptance criteria."},{"heading":"Threshold relevansi 1.6 mm","body":"Per ASME VIII App 8, indikasi dengan dimensi mayor <= 1.6 mm (1/16 in) dianggap non-relevant dan tidak perlu dievaluasi terhadap acceptance. Indikasi > 1.6 mm = relevant dan wajib diklasifikasi serta diukur. Penting: ini threshold RELEVANSI, bukan acceptance — linear relevant yang > 1.6 mm tetap REJECT meskipun pendek."},{"heading":"Menangani non-relevant","body":"Indikasi non-relevant dari geometri boleh diabaikan HANYA setelah penyebabnya dikonfirmasi. Cara konfirmasi: bersihkan area, re-apply developer, dan lihat apakah indikasi muncul kembali dengan pola identik serta korelasikan dengan drawing/geometri (pola geometri akan repeat persis). Catatan: crack juga bisa repeat — jadi korelasi geometri wajib. Jangan melabeli non-relevant hanya untuk menghindari reject."},{"heading":"Bleed-out dan waktu evaluasi","body":"T-676 ASME V: interpretasi/evaluasi dilakukan SELAMA developing time. Developer dwell (developing time) untuk interpretasi akhir umumnya 10-60 menit. Crack dalam akan terus bleed-out dan membesar; indikasi dangkal/non-relevant cenderung stabil. Evaluasi indikasi saat awal terbentuk DAN setelah berkembang untuk membedakan kedalaman diskontinuitas."}]}', 440, NULL),
  (3, 'reading', 'ASTM E165 / E1417 — Praktik dan Acceptance', '{"slides":[{"heading":"E165 vs E1417 — beda peran","body":"ASTM E165 = Standard Practice for Liquid Penetrant Testing (industri umum, deskripsi cara). ASTM E1417 = Standard Practice for Liquid Penetrant Testing (sering dirujuk aerospace/kontraktual, lebih ketat: mewajibkan process control, QC checks terjadwal, dan acceptance ditetapkan oleh contract/drawing). E1417 banyak dirujuk spesifikasi prime aerospace; E165 lebih umum komersial."},{"heading":"Penamaan tipe & metode (AMS 2644 / E1417)","body":"Type I = fluorescent, Type II = visible. Method A = water-washable, B = post-emulsifiable lipophilic, C = solvent-removable, D = post-emulsifiable hydrophilic. Form developer: a=dry, b=water-soluble, c=water-suspendable, d=nonaqueous (sensitivitas tertinggi), e=plastic film. Sensitivity Level 1/2/3/4 (Level 1 terendah, naik makin sensitif) per AMS 2644. Contoh klasifikasi penuh: Type I Method D Form d Level 3."},{"heading":"Process control E1417","body":"E1417 mewajibkan verifikasi terjadwal: panel referensi TAM/PSM dan Ni-Cr cracked-chrome untuk cek sensitivitas sistem, konsentrasi emulsifier hydrophilic (dip 5-20%, spray <=5%, cek via refractometer/Brix), kadar air water-washable, kondisi developer, serta UV-A >= 1000 uW/cm2 @ 38 cm + ambient <= 20 lux (visible >= 1000 lux). E165 lebih longgar pada frekuensi QC tetapi prinsipnya sama."},{"heading":"Acceptance — siapa yang menentukan","body":"Baik E165 maupun E1417 TIDAK memberi angka acceptance sendiri; keduanya menyatakan acceptance criteria harus ditetapkan dokumen rujukan (drawing, spesifikasi, atau construction code). Maka Level II harus selalu menanyakan: ''Acceptance pakai apa?'' — bisa ASME VIII App 8, AMS, atau ISO 3452/23277 level tertentu. Tanpa acceptance yang ditetapkan, report tidak boleh ditandatangani sebagai accept/reject."}]}', 450, NULL),
  (4, 'reading', 'ISO 3452 — Acceptance Levels & Klasifikasi Indikasi', '{"slides":[{"heading":"Keluarga standar ISO 3452","body":"ISO 3452-1 = prinsip umum & metode (setara fungsi dengan E165). ISO 3452-2 = pengujian material penetrant. ISO 3452-3 = test blocks (panel 1 / type 1 = Ni-Cr cracked-chrome; panel 2 / type 2 = aluminium quench-crack). Acceptance numerik TIDAK ada di 3452-1; acceptance levels berada di standar evaluasi terpisah seperti ISO 23277 (untuk weld) yang menetapkan acceptance level 1, 2, 3."},{"heading":"Klasifikasi indikasi ISO","body":"ISO membedakan: linear indication (panjang l > 3w), rounded/non-linear (l <= 3w), dan aligned (segaris). Tiap acceptance level mendefinisikan ukuran maksimum indikasi yang diizinkan. Pada ISO 23277, batas untuk linear lebih ketat daripada rounded — mirip filosofi ASME bahwa linear selalu diperlakukan lebih kritis daripada rounded."},{"heading":"ASME vs ISO — perbedaan filosofi","body":"ASME VIII App 8: angka absolut tetap (linear relevan >1.6mm reject; rounded >5mm reject) terlepas kekritisan komponen. ISO 23277: dipilih acceptance LEVEL (1/2/3) sesuai kekritisan — Level 1 paling ketat (batas terkecil, komponen kritis), Level 3 paling longgar (non-kritis). Level II harus tahu standar dan level mana yang berlaku SEBELUM mengukur, karena angka rejectnya berbeda."},{"heading":"Definisi linear vs rounded — pegangan tunggal","body":"Aturan universal: LINEAR jika panjang > 3x lebar; ROUNDED jika panjang <= 3x lebar. Definisi geometris ini konsisten di ASME, ASTM, dan ISO. Yang berbeda antar kode hanyalah angka acceptance dan threshold relevansi. Selalu ukur panjang DAN lebar indikasi sebelum mengklasifikasi — jangan menebak kategori hanya dari bentuk visual."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Code Interpretation', '{"description":"Uji penguasaan ASME V Article 6 (technique), ASME VIII Div.1 Appendix 8 (acceptance), ASTM E165/E1417, dan ISO 3452/23277.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 8
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 8 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dalam ASME Section V Article 6, di mana kriteria acceptance terima/tolak indikasi PT didefinisikan?',
   '["Pada paragraf T-621 sebagai bagian dari written procedure","Pada paragraf T-660 tentang demonstrasi sistem","Tidak di Article 6 — acceptance dirujuk ke construction code (mis. ASME VIII Div.1 Appendix 8)","Pada tabel sensitivitas AMS 2644 yang disalin ke dalam Article 6"]', 2,
   'ASME V Article 6 hanya mengatur TEKNIK (cara melakukan PT). Acceptance criteria final tidak ada di Article 6; ia merujuk ke construction code seperti ASME VIII Div.1 Mandatory Appendix 8. Kesalahan umum adalah mencari angka reject di Article 6.', 'Code Interpretation', 'medium'),
  ('Per ASME VIII Div.1 Mandatory Appendix 8, sebuah indikasi LINEAR relevan sepanjang 2.0 mm. Bagaimana statusnya?',
   '["Ditolak — indikasi linear relevan dengan panjang > 1.6 mm harus ditolak","Diterima — masih di bawah batas 5 mm yang berlaku untuk linear","Diterima — di bawah 3.0 mm dianggap non-relevant","Perlu re-test karena berada di zona abu-abu 1.6-3.0 mm"]', 0,
   'Appendix 8: indikasi relevan adalah yang dimensi mayor > 1.6 mm. Untuk LINEAR, indikasi relevan apa pun (termasuk 2.0 mm) ditolak. Batas 5 mm hanya berlaku untuk ROUNDED, bukan linear. Maka linear 2.0 mm = reject.', 'Acceptance Criteria', 'medium'),
  ('Aturan universal (ASME/ASTM/ISO) untuk membedakan indikasi LINEAR dari ROUNDED adalah:',
   '["Linear jika panjang > 1.6 mm; rounded jika <= 1.6 mm","Linear jika panjang > 3x lebar; rounded jika panjang <= 3x lebar","Linear jika lebar > 3x panjang; rounded jika sebaliknya","Linear jika panjang > 5 mm; rounded jika <= 5 mm"]', 1,
   'Definisi konsisten di semua kode: LINEAR bila panjang melebihi 3x lebar; ROUNDED bila panjang <= 3x lebar. Yang berbeda antar kode hanyalah angka acceptance dan threshold relevansi, bukan definisi geometris ini.', 'Indication Classification', 'easy'),
  ('Sebuah indikasi muncul karena keyway (alur pasak) pada poros yang merupakan fitur geometri desain. Indikasi ini diklasifikasikan sebagai:',
   '["False indication — artefak proses dari over-removal","Relevant linear — wajib diukur dan dibandingkan dengan acceptance","Relevant rounded — selalu reject jika > 5 mm","Non-relevant — disebabkan kondisi geometri desain, bukan cacat aktual"]', 3,
   'Indikasi dari fitur geometri desain (keyway, press fit, ulir, sambungan) adalah NON-RELEVANT: nyata tetapi bukan diskontinuitas cacat. False indication berasal dari artefak proses (lint, sidik jari). Hanya indikasi RELEVANT yang dievaluasi terhadap acceptance criteria.', 'Indication Classification', 'medium'),
  ('Apa perbedaan utama peran ASTM E165 dibanding ASTM E1417?',
   '["E165 untuk visible penetrant saja; E1417 untuk fluorescent saja","E165 menetapkan acceptance numerik; E1417 hanya menjelaskan teknik","E165 praktik PT industri umum; E1417 praktik yang lebih ketat (sering aerospace/kontraktual) dengan process control","E165 untuk Level I; E1417 khusus Level II dan III"]', 2,
   'E165 adalah standard practice PT untuk industri umum. E1417 lebih ketat, banyak dirujuk spesifikasi aerospace, mewajibkan process control dan QC terjadwal. Keduanya TIDAK memberi acceptance numerik sendiri — acceptance ditetapkan oleh drawing/spec/code.', 'Code Interpretation', 'medium'),
  ('Pada ISO 23277 (acceptance untuk weld PT), apa arti acceptance level 1 dibanding level 3?',
   '["Level 1 paling longgar; level 3 paling ketat","Level menunjukkan sensitivitas penetrant, bukan acceptance","Level 1 paling ketat (batas ukuran indikasi terkecil); level 3 paling longgar","Semua level memakai batas ukuran identik, hanya beda metode aplikasi"]', 2,
   'Dalam ISO 23277, acceptance level 1 adalah yang paling ketat (komponen kritis, batas ukuran indikasi terkecil), sedangkan level 3 paling longgar. Ini berbeda dari ASME VIII App 8 yang memakai angka absolut tetap tanpa tingkatan kekritisan.', 'Acceptance Criteria', 'hard'),
  ('Per ASME VIII Div.1 App 8, kapan sekelompok indikasi ROUNDED yang tersusun segaris dianggap REJECT?',
   '["Empat atau lebih indikasi rounded relevan segaris dengan jarak tepi-ke-tepi <= 1.6 mm","Dua atau lebih indikasi rounded berjarak > 5 mm","Tiga indikasi rounded berapa pun jaraknya","Setiap pasangan rounded yang masing-masing < 1.6 mm"]', 0,
   'Appendix 8: empat atau lebih indikasi rounded relevan yang tersusun segaris dengan jarak tepi-ke-tepi <= 1.6 mm (1/16 in) merupakan kondisi REJECT. Aturan ini menangani porositas aligned yang masing-masing kecil namun bermasalah secara kolektif.', 'Acceptance Criteria', 'hard'),
  ('ASME V Article 6 mewajibkan demonstrasi sistem PT memakai panel referensi cracked terutama dalam kondisi:',
   '["Hanya saat menggunakan Type II visible penetrant","Bila dwell atau suhu permukaan berada di luar rentang standar (mis. di luar 10-52 C), sehingga prosedur perlu dikualifikasi","Setiap kali developer Form a (dry) digunakan","Hanya pada inspeksi pertama setiap shift, tanpa syarat suhu"]', 1,
   'Suhu permukaan standar PT per Article 6 adalah 10-52 C (50-125 F). Bila dwell atau suhu di luar rentang yang diizinkan, prosedur harus dikualifikasi dengan demonstrasi memakai panel referensi cracked (mis. Ni-Cr atau TAM/PSM) untuk membuktikan sensitivitas tetap memadai.', 'Code Interpretation', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 11 — Recap & Practice Exam (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Recap Bagian 1 — Kimia, Sistem Post-Emulsifiable & Process Control', '{"slides":[{"heading":"Fondasi kimia penetran (Modul 2)","body":"Penetran adalah campuran solvent carrier (umumnya petroleum distillate/kerosene base) + dye (fluorescent Type I atau visible Type II) + surfactant (wetting agent) + viscosity modifier + corrosion inhibitor. Surfactant bersifat amphiphilic (satu ujung hydrophilic, satu lipophilic) sehingga menurunkan surface tension penetran ke ~25-35 dyne/cm (vs air ~72 dyne/cm) agar sudut kontak kecil dan penetran masuk crack via capillary action (h = 2σ·cosθ / ρgr). Fluorescent dye (Type I) dieksitasi UV-A ~365 nm dan beremisi hijau-kuning ~520-560 nm; menambah dye berlebih TIDAK menaikkan sensitivity karena concentration quenching (self-absorption). Halogen (chlorine/fluorine) dan sulfur dibatasi (umumnya maksimum 1% masing-masing dari residu kering) per AMS 2644 karena risiko stress-corrosion cracking & intergranular attack pada nickel-base/austenitic stainless saat dipanaskan."},{"heading":"Type, Method, Sensitivity, Developer Form (Modul 2-3)","body":"Kerangka klasifikasi yang harus hafal: TYPE I fluorescent / TYPE II visible. METHOD A = water-washable (emulsifier built-in), B = post-emulsifiable lipophilic, C = solvent-removable, D = post-emulsifiable hydrophilic. SENSITIVITY per AMS 2644 (Type I): Level 1/2 (very low), 1 (low), 2 (medium), 3 (high), 4 (ultra-high); visible Type II tidak diberi level numerik. DEVELOPER FORM: a = dry powder, b = water-soluble, c = water-suspendable, d = nonaqueous solvent (sensitivitas tertinggi), e = plastic film. Sensitivity adalah properti SISTEM lengkap (penetran + removal + developer + lighting), bukan penetran saja."},{"heading":"Post-emulsifiable: B vs D (Modul 3)","body":"Penetran post-emulsifiable TIDAK mengandung emulsifier — emulsifier diaplikasikan sebagai langkah terpisah setelah dwell penetran, menaikkan sensitivitas 2-3x dengan kompleksitas proses ~5x. Method B (LIPOPHILIC): emulsifier berbasis minyak (as-supplied ~100%), mekanisme DIFUSI, dikontrol oleh WAKTU (dwell emulsifier tipikal 30 dtk-2 mnt), jendela sempit, tanpa pre-rinse. Method D (HYDROPHILIC): emulsifier detergen yang diencerkan air, mekanisme aksi deterjen, dikontrol oleh KONSENTRASI (dip 5-20%, spray <=5%) + waktu, dengan pre-rinse, jendela lebih lebar, dipantau refractometer/Brix. HLB rendah (3-6) = oil-soluble (B); HLB tinggi (8-18) = water-soluble (D)."},{"heading":"Process control & bath maintenance (Modul 4)","body":"Level II menjaga performa sistem sepanjang shift. Water-washable (Method A) paling rentan air: batas water content umumnya <=5% by volume (sebagian prosedur 3%); air berlebih menurunkan brightness dan memicu gelling/separasi/false removal. Emulsifier hydrophilic (Method D) dipantau refractometer (Brix dikonversi ke %): konsentrasi terlalu tinggi -> over-removal (indikasi hilang), terlalu rendah -> over-background. Performa SISTEM keseluruhan diverifikasi dengan known-defect panel TAM/PSM (PSM-5) dan Ni-Cr cracked-chrome, diproses melalui seluruh siklus lalu dibandingkan foto master. Bila parameter gagal: stop, corrective action (top-up/adjust/replace/re-lamp), re-verify dengan panel, baru lanjut. Semua keputusan terdokumentasi dan traceable."}]}', 480, NULL),
  (2, 'reading', 'Recap Bagian 2 — Specialty, Sizing & Procedure Development', '{"slides":[{"heading":"Aplikasi spesial (Modul 5)","body":"Turbine blade aerospace (cast Ni-superalloy, crack fatigue tight < 1 um): Type I, Method D, Sensitivity Level 3-4, prosesor terakreditasi NADCAP (AC7114), material terdaftar QPL AMS 2644; recast layer EDM pada cooling hole sering perlu mild acid etch untuk membuka mulut crack. Plastik/komposit: PT dipilih karena MT/ET tidak berlaku pada non-konduktif/non-feromagnetik, tetapi WAJIB compatibility test (solvent dapat menyebabkan crazing/swelling/stress-cracking); PT hanya mendeteksi diskontinuitas tembus permukaan — delaminasi subsurface adalah domain UT/thermography. High-temp PT: proses standar dikualifikasi pada suhu permukaan ~4-52 C (40-125 F) per ASME V Article 6; di luar rentang itu butuh penetran high-temp + kualifikasi prosedur pada comparator block di suhu aktual; carrier menguap cepat sehingga dwell efektif menyusut."},{"heading":"Klasifikasi indikasi (Modul 6)","body":"Tiga kategori: FALSE (over-wash residue, lint, kontaminasi — tidak muncul kembali setelah re-clean & re-develop), NON-RELEVANT (fitur geometri/desain sah — muncul kembali tetapi konsisten mengikuti geometri), dan RELEVANT (diskontinuitas aktual — bleed-back progresif/konsisten dari rongga). Teknik diskriminasi: bersihkan spot dengan solvent-dampened cloth, keringkan, re-develop (Form d untuk sensitivitas tertinggi). Per ASME VIII Div.1 App.8, indikasi dianggap relevant bila dimensi mayor > 1.6 mm (1/16 in). Bila ragu geometri vs crack: perlakukan sebagai relevant sampai terbukti sebaliknya (beban pembuktian pada inspektor, ASME V Article 6 T-680)."},{"heading":"Sizing & evaluasi (Modul 6)","body":"PT mengamplifikasi — bleed-out lebih lebar dari rongga; yang diukur untuk acceptance adalah dimensi INDIKASI, bukan crack aktual, dan PT tidak mengukur kedalaman. Ukur setelah developer dwell minimum (>=10 menit atau ~1/2 penetrant dwell) dalam jendela waktu: terlalu cepat under-develop, terlalu lama over-bleed. LINEAR = panjang >= 3x lebar; ROUNDED = panjang < 3x lebar. Ukur di bawah UV-A >=1000 uW/cm2 @ 38 cm + ambient <=20 lux + adaptasi 1 menit (Type I) atau white light >=1000 lux (Type II). Untuk kasus borderline (~1.5-1.7 mm pada batas 1.6 mm): re-clean & re-test, lalu ambil keputusan konservatif menuju reject."},{"heading":"Procedure development (Modul 7)","body":"ASME V Article 6 (T-621) mewajibkan written procedure yang di-DEMONSTRATE ke kepuasan Inspector pada spesimen representatif (mis. panel Ni-Cr cracked-chrome / TAM-PSM) — tanda tangan saja tidak cukup. Essential variable (mis. ganti keluarga/merek/Type/Method material, naik-turun sensitivity, suhu di luar rentang qualified, perubahan proses removal/pre-cleaning) -> WAJIB requalification. Nonessential variable (mis. brush vs spray dalam batas izin, detail prosedural minor) cukup dicatat. Procedure harus menetapkan semua angka (dwell penetran 5-30 min, developer >=10 min, suhu standar 10-52 C, lighting + interval cek, kontrol emulsifier via Brix untuk Method D) dan mengutip kriteria acceptance dari construction code — bukan ditulis ''secukupnya''. Persetujuan akhir prosedur umumnya pada Level III."}]}', 470, NULL),
  (3, 'reading', 'Recap Bagian 3 — Code, Acceptance, QC & Studi Kasus', '{"slides":[{"heading":"Hierarki kode: teknik vs acceptance (Modul 8)","body":"ASME V Article 6 menetapkan TEKNIK (T-621 procedure, T-680 evaluasi), BUKAN kriteria accept/reject. Kriteria acceptance selalu diambil dari referencing/construction code yang governing: ASME VIII Div.1 Mandatory Appendix 8 (vessel), ASME B31.1/B31.3 (piping), atau part drawing/spec aerospace. ASTM E165 (praktik standar) / E1417 (proses aerospace) memberi metode; ISO 3452 memberi acceptance level 1/2/3 sebagai alternatif internasional. AMS 2644 hanya mengatur KUALIFIKASI material penetran (Type/Method/Sensitivity/Form), bukan acceptance indikasi — jangan tertukar."},{"heading":"Kriteria acceptance ASME VIII Div.1 App.8 (Modul 8, 10)","body":"Hafal angka kunci: indikasi relevant bila dimensi mayor > 1.6 mm (1/16 in). LINEAR relevant > 1.6 mm = REJECT. ROUNDED relevant > 5 mm (3/16 in) = REJECT. EMPAT atau lebih indikasi rounded dalam satu garis dengan spasi edge-to-edge <= 1.6 mm (1/16 in) = REJECT (aligned), meskipun tiap indikasi individual < 5 mm. Crack, lack of fusion, dan incomplete penetration SELALU REJECT tanpa memandang ukuran (sifat planar/linear kritis). Setelah reject -> repair, lalu RE-PT seluruh metal repair + area sekitarnya (umumnya 13-25 mm)."},{"heading":"Quality control & audit (Modul 9)","body":"Tiga tingkat verifikasi: HARIAN/shift (panel TAM/PSM untuk performa sistem; UV-A >=1000 uW/cm2 @ 38 cm + ambient <=20 lux + adaptasi gelap 1 menit untuk Type I, atau white >=1000 lux untuk Type II; background fluorescence; filter UV utuh), BERKALA/mingguan-bulanan (konsentrasi emulsifier via Brix, water content WW, brightness penetran vs referensi), TAHUNAN (kalibrasi radiometer/luxmeter traceable NIST/ISO, audit SOP, eye exam personel). Instrumen yang kadaluwarsa kalibrasi membuat seluruh data QC tidak valid saat audit. Ketidaksesuaian -> CAPA terdokumentasi + verifikasi penutupan."},{"heading":"Studi kasus & otoritas Level II (Modul 10)","body":"Latihan disposisi: linear 2.3 mm = reject; rounded 4 mm tunggal = accept (tetap recordable); rounded 6 mm = reject; 5 rounded sejajar spasi 1.2 mm = reject (aligned). Bedakan over-reject (menolak false/non-relevant — repair sia-sia & biaya naik) dari under-reject (meloloskan crack relevant — escape kritis menuju kegagalan in-service). Sebelum re-PT repair, verifikasi sistem dulu (panel + lighting). Level II menandatangani interpretasi akhir, menulis & men-demonstrate procedure; persetujuan akhir prosedur umumnya pada Level III. Dokumentasi (tipe, dimensi, kode acceptance, keputusan, tanda tangan) harus dapat diverifikasi inspektor lain secara independen. Bersiaplah untuk practice exam 25 soal."}]}', 460, NULL),
  (4, 'quiz', 'Practice Exam — PT Level II (25 soal)', '{"description":"Practice exam komprehensif 25 soal mencakup seluruh silabus PT Level II (Modul 1-10): kimia penetran, post-emulsifiable B/D, process control, aplikasi spesial, sizing & evaluasi, procedure development, interpretasi kode, QC & audit, dan studi kasus lapangan. Simulasi sebelum Final Assessment.","questionCount":25,"passingScore":80}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 11
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 11 mini-quiz (25 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Surface tension penetran yang baik dibuat RENDAH (tipikal ~25-35 dyne/cm vs air ~72 dyne/cm) terutama agar:',
   '["Penetran cepat menguap dari permukaan saat removal","Sudut kontak kecil sehingga penetran membasahi dan masuk crack via capillary action","Brightness fluoresensi otomatis meningkat di bawah UV-A","Developer tidak perlu diaplikasikan lagi"]', 1,
   'Surface tension rendah (dikendalikan surfactant amphiphilic) membuat sudut kontak (θ) kecil sehingga penetran membasahi permukaan dan tertarik ke dalam crack lewat capillary action (h = 2σ·cosθ / ρgr). Surface tension tidak menentukan brightness, dan penetran rendah surface tension tidak menghilangkan kebutuhan developer.', 'Penetrant Chemistry', 'easy'),
  ('Mengapa menambah konsentrasi fluorescent dye secara berlebihan TIDAK selalu menaikkan sensitivity penetran?',
   '["Dye berlebih meningkatkan surface tension hingga capillary action berhenti","Dye berlebih membuat penetran berubah menjadi visible dye Type II","Terjadi concentration quenching (self-absorption) yang justru menurunkan brightness","Dye berlebih menguap lebih cepat daripada solvent carrier"]', 2,
   'Pada konsentrasi dye tinggi terjadi concentration quenching / self-absorption: molekul dye menyerap emisi molekul lain sehingga brightness justru turun. Sensitivity tinggi dicapai lewat carrier/surfactant yang lebih baik, bukan sekadar menambah dye.', 'Penetrant Chemistry', 'hard'),
  ('Kandungan halogen (chlorine/fluorine) dan sulfur dibatasi ketat pada penetran (per AMS 2644) terutama karena:',
   '["Risiko stress-corrosion cracking & intergranular attack pada nickel-base dan austenitic stainless saat dipanaskan","Keduanya memadamkan fluoresensi dye secara permanen","Keduanya menaikkan surface tension hingga penetran tidak membasahi","Keduanya membuat developer Form d tidak bisa kering"]', 0,
   'Residu halogen dan sulfur berisiko menyebabkan stress-corrosion cracking dan intergranular attack pada material nickel-base & austenitic stainless saat terpapar panas. AMS 2644 mensyaratkan sertifikasi kandungan rendah (umumnya maksimum 1% masing-masing dari residu kering).', 'Chemical QC', 'medium'),
  ('Manakah pasangan METHOD penetran yang BENAR sesuai definisi standar?',
   '["A = post-emulsifiable hydrophilic; B = water-washable","C = post-emulsifiable lipophilic; D = solvent-removable","A = water-washable; B = post-emulsifiable lipophilic; C = solvent-removable; D = post-emulsifiable hydrophilic","A = solvent-removable; D = water-washable"]', 2,
   'Klasifikasi method standar: A = water-washable (emulsifier built-in), B = post-emulsifiable lipophilic, C = solvent-removable, D = post-emulsifiable hydrophilic. Pasangan lain menukar definisi method.', 'Klasifikasi Sistem PT', 'easy'),
  ('Manakah pernyataan yang BENAR tentang developer form?',
   '["Form a (dry powder) memberi sensitivitas tertinggi di antara semua form","Form e (plastic film) adalah developer water-soluble","Form d (nonaqueous solvent) memberi sensitivitas tertinggi","Form b (water-soluble) wajib dipakai untuk semua aplikasi aerospace"]', 2,
   'Developer FORM: a = dry, b = water-soluble, c = water-suspendable, d = nonaqueous solvent (sensitivitas tertinggi), e = plastic film. Form d memberi sensitivitas tertinggi karena membentuk lapisan tipis merata yang menarik bleed-out maksimal; Form e adalah plastic film, bukan water-soluble.', 'Klasifikasi Sistem PT', 'medium'),
  ('Menurut AMS 2644, level sensitivity TERTINGGI (ultra-high) untuk penetran fluorescent Type I adalah:',
   '["Level 1","Level 2","Level A","Level 4"]', 3,
   'AMS 2644 mengkualifikasi fluorescent ke lima tingkat meningkat: Level 1/2 (very low), 1 (low), 2 (medium), 3 (high), hingga 4 (ultra-high). Tidak ada ''Level A''. Level dievaluasi pada panel referensi seperti TAM/PSM atau Ni-Cr cracked-chrome.', 'Sensitivity Grading', 'easy'),
  ('Apa perbedaan mendasar penetran post-emulsifiable (Method B/D) dibandingkan water-washable (Method A)?',
   '["Post-emulsifiable mengandung emulsifier sejak awal, Method A tidak","Post-emulsifiable TIDAK mengandung emulsifier; emulsifier diaplikasikan sebagai langkah terpisah setelah dwell","Post-emulsifiable hanya bisa Type II visible","Keduanya dibilas dengan cara yang identik"]', 1,
   'Pada Method A emulsifier sudah tercampur sehingga langsung dibilas air. Pada post-emulsifiable penetrannya murni tanpa emulsifier; emulsifier diaplikasikan terpisah setelah dwell penetran, membuat penetran lebih tahan over-removal dan menaikkan sensitivitas 2-3x.', 'Post-Emulsifiable Principles', 'easy'),
  ('Pada Method B (lipophilic), variabel proses yang paling kritis dikendalikan adalah WAKTU karena mekanismenya:',
   '["Difusi emulsifier oil-based ke dalam lapisan penetran berlebih seiring waktu","Aksi deterjen yang dikontrol konsentrasi","Penguapan solvent carrier yang mengeraskan penetran","Reaksi oksidasi yang menetralkan dye"]', 0,
   'Emulsifier lipophilic (oil-based, ~100% as-supplied) bekerja lewat DIFUSI ke dalam lapisan penetran berlebih, dan difusi berlanjut selama kontak. Karena itu WAKTU (dwell emulsifier tipikal 30 dtk-2 menit) menjadi variabel kritis. Konsentrasi adalah variabel kontrol Method D, bukan B.', 'Method B Lipophilic', 'medium'),
  ('Untuk emulsifier HYDROPHILIC (Method D) dengan aplikasi DIP, rentang konsentrasi tipikal dan alat kontrolnya adalah:',
   '["100% as-supplied, dikontrol stopwatch","30-50%, dikontrol pH meter","0.1-1%, dipantau hydrometer","5-20% (spray <=5%), dipantau refractometer (skala Brix)"]', 3,
   'Emulsifier hydrophilic (detergen) diencerkan air: dip 5-20%, spray <=5%, dan dipantau dengan refractometer (Brix dikonversi ke %). 100% as-supplied adalah praktik lipophilic (Method B); pH meter dan hydrometer bukan alat kontrol konsentrasi emulsifier hydrophilic.', 'Method D Hydrophilic', 'medium'),
  ('Nilai HLB (Hydrophilic-Lipophilic Balance) yang TINGGI (sekitar 8-18) menandakan emulsifier yang:',
   '["Oil-soluble, cocok untuk lipophilic Method B","Water-soluble, cocok untuk hydrophilic Method D","Tidak larut di air maupun minyak","Hanya cocok untuk penetran visible Type II"]', 1,
   'Skala HLB ~0-20: nilai rendah (3-6) oil-soluble untuk lipophilic (Method B), nilai tinggi (8-18) water-soluble untuk hydrophilic detergent (Method D). HLB mengkarakterisasi keseimbangan kelarutan emulsifier.', 'Emulsifier Systems', 'hard'),
  ('Apa fungsi langkah PRE-RINSE pada Method D (hydrophilic) yang umumnya TIDAK ada pada Method B?',
   '["Mengaktifkan emulsifier sebelum diaplikasikan","Menghilangkan sebagian besar penetran permukaan dulu untuk mengurangi beban emulsifier dan memperpanjang umur bath","Menetralkan pH penetran agar developer menempel","Mendinginkan part agar emulsifier tidak menguap"]', 1,
   'Pre-rinse air ringan sebelum emulsifier hydrophilic menghilangkan sebagian besar penetran permukaan, mengurangi beban emulsifier, memperpanjang umur bath, dan membuat removal lebih konsisten. Lipophilic tidak memakai pre-rinse karena emulsifier oil-based tidak kompatibel dengan air pada langkah itu.', 'Method D Hydrophilic', 'hard'),
  ('Batas maksimum kontaminasi air yang umum untuk water-washable (Method A) penetrant per ASTM E1417/E165 adalah sekitar:',
   '["5% by volume","20% by volume","50% by volume","Tidak ada batas selama masih berfluoresensi"]', 0,
   'Water content water-washable umumnya dibatasi maksimum ~5% by volume (sebagian prosedur lebih ketat ke 3%). Air berlebih menurunkan brightness, memicu gelling/separasi, dan dapat menyebabkan false removal (penetran terangkat dari diskontinuitas).', 'Process Control', 'medium'),
  ('Alat yang memverifikasi performa SISTEM KESELURUHAN (penetran + removal + developer + lighting) pada sistem fluoresen adalah:',
   '["Lux meter ambient saja","Known-defect panel seperti TAM/PSM atau Ni-Cr cracked-chrome panel, diproses lalu dibandingkan foto master","Sertifikat batch dari supplier penetran","Refractometer Brix"]', 1,
   'TAM/PSM (PSM-5) dan Ni-Cr cracked-chrome panel diproses melalui seluruh siklus PT lalu jumlah/brightness indikasi dibandingkan terhadap foto master. Sertifikat batch hanya menyatakan material qualified; refractometer dan luxmeter hanya mengukur satu parameter, bukan performa sistem total.', 'System Performance', 'medium'),
  ('Untuk inspeksi Type I (fluorescent), kombinasi persyaratan lighting yang BENAR adalah:',
   '["White light >=1000 lux tanpa batas ambient apa pun","UV-A >=100 uW/cm2 pada 1 m tanpa adaptasi mata","UV-A >=1000 uW/cm2 pada 38 cm, ambient white light <=20 lux, adaptasi gelap >=1 menit","Hanya ambient white light >=20 lux"]', 2,
   'Type I: UV-A minimum 1000 uW/cm2 diukur pada 38 cm, ambient white light maksimum 20 lux (2 fc), plus adaptasi gelap mata minimal 1 menit. White light >=1000 lux justru syarat untuk Type II (visible), bukan Type I. Satuan uW/cm2 (UV-A) dan lux (cahaya tampak) tidak dipertukarkan.', 'Lighting Requirements', 'medium'),
  ('Untuk crack fatigue sangat tight (< 1 um) pada turbine blade cast Ni-superalloy aerospace, kombinasi sistem yang paling tepat adalah:',
   '["Type I fluorescent, Method D (hydrophilic post-emulsifiable), Sensitivity Level 3-4","Type II visible dye, Method A, Sensitivity Level 1","Type II visible dye, Method C, Sensitivity Level 2","Type I fluorescent, Method A, Sensitivity Level 1/2"]', 0,
   'Crack sangat tight pada komponen kritis aerospace menuntut sensitivity tertinggi: Type I fluorescent + Method D (hydrophilic post-emulsifiable) + Sensitivity Level 3-4 per AMS 2644. Method A berisiko over-wash penetran dari crack tight; Type II visible tidak pernah cukup untuk part kritis ini.', 'Aerospace PT', 'medium'),
  ('Mengenai PT pada komponen komposit (GFRP), pernyataan yang BENAR adalah:',
   '["PT dapat mendeteksi delaminasi subsurface dengan baik","PT tidak dapat dipakai sama sekali pada material non-konduktif","PT hanya mendeteksi diskontinuitas yang tembus ke permukaan; delaminasi subsurface adalah domain UT/thermography","PT lebih sensitif daripada UT untuk semua jenis defect komposit"]', 2,
   'PT adalah metode surface — hanya mendeteksi diskontinuitas terbuka ke permukaan. Delaminasi internal komposit tidak terdeteksi PT dan membutuhkan UT/thermography. PT justru berguna pada material non-konduktif/non-feromagnetik yang tidak bisa diinspeksi MT/ET, dengan syarat compatibility test.', 'Plastic/Composite PT', 'medium'),
  ('Menurut ASME V Article 6, apa yang harus dilakukan bila PT diterapkan pada suhu permukaan di luar rentang standar (di luar ~4-52 C / 40-125 F)?',
   '["Tidak ada tindakan khusus, cukup dipersingkat dwell-nya","Otomatis gunakan Type I fluorescent tanpa kualifikasi","Kualifikasi prosedur pada suhu aktual aplikasi menggunakan comparator block, dan catat suhu permukaan di laporan","Naikkan sensitivity ke Level 4 tanpa pengujian"]', 2,
   'ASME V Article 6 mensyaratkan kualifikasi prosedur ketika suhu di luar rentang standar (~4-52 C), dilakukan pada comparator/cracked block pada suhu aktual aplikasi dibandingkan prosedur standar pada rentang normal. Suhu permukaan harus diukur (contact pyrometer/thermocouple) dan didokumentasikan.', 'High-Temp PT', 'hard'),
  ('Sebuah bleed-out MASIH muncul kembali secara progresif setelah dibersihkan dengan solvent, dikeringkan, dan di-develop ulang dengan Form d. Indikasi ini paling tepat diklasifikasikan sebagai:',
   '["False indication akibat over-wash yang gagal","Relevant indication dari diskontinuitas aktual","Non-relevant indication dari fitur geometri","Kontaminasi developer yang dapat diabaikan"]', 1,
   'Indikasi yang muncul kembali progresif setelah re-clean dan re-develop menandakan penetran terus keluar dari rongga nyata — ciri relevant indication. False indication tidak reappear. Non-relevant geometrik muncul kembali tetapi konsisten mengikuti fitur geometri, bukan progresif dari rongga.', 'Klasifikasi Indikasi', 'medium'),
  ('Dalam PT, dimensi mana yang diukur untuk dibandingkan dengan kriteria acceptance kode?',
   '["Lebar crack sebenarnya diukur mikroskop","Kedalaman diskontinuitas","Panjang/dimensi INDIKASI (bleed-out), bukan crack aktual","Volume penetran yang keluar dari rongga"]', 2,
   'PT mengamplifikasi diskontinuitas — bleed-out lebih lebar dari rongga sebenarnya. Kode acceptance sudah memperhitungkan amplifikasi ini, sehingga yang diukur dan dievaluasi adalah dimensi INDIKASI, bukan crack aktual. PT juga tidak dapat menentukan kedalaman.', 'Sizing Indikasi', 'medium'),
  ('Sebuah indikasi terukur panjang 4.5 mm dan lebar 1.0 mm. Bagaimana klasifikasi bentuknya per definisi ASME?',
   '["Linear, karena panjang >= 3x lebar","Rounded, karena panjang < 5 mm","Non-relevant, karena lebar < 1.6 mm","Aligned, karena rasio panjang/lebar > 4"]', 0,
   'Indikasi LINEAR didefinisikan bila panjang >= 3x lebar. Di sini 4.5 mm >= 3 x 1.0 mm (=3.0 mm) sehingga LINEAR. Yang menentukan rasio panjang terhadap lebar, bukan nilai absolut panjang.', 'Sizing Indikasi', 'easy'),
  ('Per ASME VIII Div.1 Mandatory Appendix 8, indikasi LINEAR relevant ditolak (reject) bila panjangnya melebihi, dan indikasi ROUNDED relevant ditolak bila melebihi:',
   '["Linear > 5 mm; rounded > 1.6 mm","Linear > 1.6 mm (1/16 in); rounded > 5 mm (3/16 in)","Linear > 3.2 mm; rounded > 6.4 mm","Linear > 1.6 mm; rounded > 1.6 mm"]', 1,
   'Per App.8: relevant LINEAR > 1.6 mm (1/16 in) = reject; relevant ROUNDED > 5 mm (3/16 in) = reject. Membedakan kedua batas penting karena bergantung pada klasifikasi bentuk indikasi (linear vs rounded).', 'Code Interpretation', 'medium'),
  ('Ditemukan deretan 5 rounded indication berdiameter 2-3 mm dalam satu garis dengan spasi edge-to-edge 1.2 mm. Mengapa kondisi ini REJECT meski tiap indikasi < 5 mm?',
   '["Karena 4 atau lebih rounded dalam satu garis dengan spasi <= 1.6 mm ditolak (aligned)","Karena total panjang gabungan melebihi 10 mm","Karena rounded berurutan otomatis dihitung sebagai satu linear","Karena 5 indikasi melampaui batas jumlah maksimum per area"]', 0,
   'App.8 memiliki kriteria aligned/clustered: 4 atau lebih rounded dalam satu garis dengan spasi edge-to-edge <= 1.6 mm (1/16 in) = REJECT, meski tiap indikasi individual < 5 mm. Pola ini menandakan jalur kelemahan (mis. porositas linear). Tidak ada ''batas jumlah maksimum per area'' dan rounded tidak otomatis dijadikan satu linear.', 'Code Interpretation', 'hard'),
  ('Pada inspeksi pressure vessel per ASME VIII Div.1 Appendix 8, ditemukan crack terukur hanya 0.9 mm. Disposisi yang benar adalah:',
   '["Accept, karena di bawah ambang relevan 1.6 mm","Accept, karena di bawah batas rounded 5 mm","Reject, karena crack/lack of fusion/incomplete penetration selalu ditolak tanpa memandang ukuran","Diabaikan sebagai non-relevant geometri"]', 2,
   'App.8 menyatakan crack, lack of fusion, dan incomplete penetration SELALU REJECT tanpa memandang ukuran karena sifat planar/linear kritisnya. Ambang 1.6 mm berlaku untuk indikasi linear umum, tetapi crack adalah kategori yang otomatis ditolak meski kecil.', 'Code Interpretation', 'hard'),
  ('ASME V Article 6 sering dijadikan acuan untuk PT, namun untuk menentukan accept/reject suatu indikasi, kriteria acceptance harus diambil dari:',
   '["ASME V Article 6 itu sendiri, yang memuat tabel acceptance lengkap","AMS 2644, yang menetapkan batas ukuran indikasi","ISO 3452-2, yang menetapkan acceptance universal untuk semua aplikasi","Referencing/construction code yang berlaku (mis. ASME VIII, B31.3) atau part drawing/spec"]', 3,
   'ASME V Article 6 menetapkan TEKNIK, bukan acceptance. Kriteria accept/reject dirujuk dari construction/referencing code (ASME VIII, B31.1/B31.3) atau part drawing/spec. AMS 2644 hanya mengatur kualifikasi material penetran (Type/Method/Sensitivity), bukan acceptance indikasi.', 'Code Interpretation', 'hard'),
  ('Setelah weld repair pada area yang sebelumnya REJECT, apa cakupan minimum re-PT verifikasi repair yang benar, dan apa yang wajib diverifikasi sebelum re-PT dimulai?',
   '["Hanya bead repair tepat di garis las; cukup visual sebelumnya","Seluruh metal repair + area sekitarnya (umumnya 13-25 mm), dengan performa sistem (panel + lighting) diverifikasi lebih dulu","Seluruh komponen wajib di-PT ulang dari awal; tanpa cek sistem","Cukup visual inspection tanpa PT karena area sudah pernah di-PT"]', 1,
   'Re-PT repair harus mencakup seluruh metal repair PLUS area sekitarnya (umumnya 13-25 mm) untuk menangkap cacat tepi grinding/excavation. Sebelum re-PT, performa sistem wajib diverifikasi (panel TAM/PSM & Ni-Cr menampilkan indikasi referensi; UV-A >=1000 uW/cm2 @ 38 cm + ambient <=20 lux untuk Type I, atau white >=1000 lux untuk Type II). Tidak perlu meng-PT seluruh komponen dari awal, dan visual saja tidak cukup.', 'Repair Verification', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — PT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
-- Steps: ON CONFLICT DO NOTHING (safe, never deletes user progress).
-- Quiz questions: DELETE+INSERT per quiz step (idempotent).
-- ============================================================

-- PT-L2 Module 12 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'quiz', 'FINAL ASSESSMENT — PT Level II', '{"description":"Ujian sertifikasi PT Level II — 60 soal · 120 menit · minimal 80% lulus.","questionCount":60,"passingScore":80}', 7200, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 12
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 12 mini-quiz (60 questions, step 1)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 1 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Surfactant dalam formulasi penetran bersifat amphiphilic. Apa fungsi utama gugus hydrophilic dan lipophilic pada molekul surfactant?',
   '["Menurunkan surface tension sehingga sudut kontak mengecil dan wetting membaik","Menaikkan viskositas penetran agar tidak menetes dari permukaan vertikal","Memberi warna fluorescent agar terlihat di bawah UV-A","Menetralkan halogen dan sulfur agar aman pada stainless"]', 0,
   'Surfactant amphiphilic (satu ujung suka air, satu ujung suka minyak) menurunkan surface tension penetran ke ~25-35 dyne/cm (vs air ~72 dyne/cm), sehingga sudut kontak mengecil, wetting membaik, dan penetran masuk celah via aksi kapiler. Viskositas diatur viscosity modifier, warna oleh dye, dan pembatasan halogen/sulfur adalah isu komposisi terpisah.', 'chemistry', 'easy'),
  ('Nilai HLB (Hydrophilic-Lipophilic Balance) yang tinggi pada sebuah surfactant mengindikasikan bahwa surfactant tersebut cenderung lebih...',
   '["larut dalam minyak dan cocok untuk emulsifier lipophilic","larut dalam air dan cocok untuk emulsifier hydrophilic","tidak larut dalam keduanya dan berfungsi sebagai inhibitor","mudah menguap dan berfungsi sebagai solvent carrier"]', 1,
   'HLB tinggi menandakan dominasi gugus hydrophilic, sehingga surfactant lebih larut dalam air — karakteristik emulsifier hydrophilic (Method D). HLB rendah berarti lebih lipophilic/larut minyak (Method B). HLB mengukur keseimbangan, bukan ketidaklarutan total maupun volatilitas.', 'chemistry', 'medium'),
  ('Mengapa menambahkan dye fluorescent secara berlebihan ke dalam penetran TIDAK menaikkan sensitivitas dan justru dapat menurunkannya?',
   '["Karena dye berlebih menaikkan viskositas sehingga kapilaritas berhenti","Karena dye berlebih mengubah Type I menjadi Type II","Karena dye berlebih bereaksi dengan developer membentuk endapan","Karena terjadi concentration quenching (self-absorption) emisi cahaya"]', 3,
   'Pada konsentrasi dye yang terlalu tinggi terjadi concentration quenching / self-absorption: molekul dye saling menyerap kembali cahaya yang diemisikan, sehingga emisi neto justru turun. Sensitivitas optimum ada pada konsentrasi tertentu, bukan semakin banyak semakin baik.', 'chemistry', 'medium'),
  ('Penetran fluorescent Type I umumnya dieksitasi oleh UV-A pada panjang gelombang sekitar 365 nm. Pada rentang panjang gelombang berapa dye tersebut beremisi sehingga tampak oleh mata?',
   '["100-280 nm (UV-C)","280-315 nm (UV-B)","520-560 nm (hijau-kuning)","620-750 nm (merah)"]', 2,
   'Dye fluorescent Type I dieksitasi UV-A ~365 nm dan beremisi pada ~520-560 nm (hijau-kuning), wilayah puncak sensitivitas mata manusia yang teradaptasi gelap. UV-C/UV-B berada di luar rentang yang aman/relevan, dan emisi merah bukan karakteristik dye PT standar.', 'chemistry', 'medium'),
  ('Mengapa kandungan halogen (klorin/fluorin) dan sulfur dibatasi (umumnya maksimum 1% masing-masing dari residu kering) per AMS 2644 pada material penetran?',
   '["Karena halogen dan sulfur memudarkan dye fluorescent","Karena keduanya menaikkan biaya produksi penetran secara signifikan","Karena risiko stress-corrosion cracking dan intergranular attack pada nickel-base/austenitic stainless saat dipanaskan","Karena keduanya membuat penetran mudah terbakar"]', 2,
   'Residu halogen dan sulfur dapat memicu stress-corrosion cracking (SCC) dan intergranular attack pada paduan nickel-base dan austenitic stainless steel, terutama bila komponen kemudian dipanaskan. Karena itu AMS 2644 membatasi kandungannya. Ini isu metalurgi/integritas, bukan biaya, fluoresensi, atau flammability.', 'chemistry', 'hard'),
  ('Persamaan kapilaritas h = 2σ·cosθ / (ρgr) menjelaskan naiknya penetran di dalam celah. Berdasarkan persamaan ini, agar penetran masuk lebih dalam ke celah yang sangat sempit, faktor mana yang paling diinginkan?',
   '["Surface tension (σ) sangat besar dan sudut kontak (θ) besar","Surface tension (σ) cukup dengan sudut kontak (θ) kecil sehingga cosθ mendekati 1","Densitas (ρ) sangat besar","Jari-jari celah (r) sangat besar"]', 1,
   'Tinggi kenaikan kapiler berbanding lurus dengan σ·cosθ dan berbanding terbalik dengan r. Wetting yang baik berarti θ kecil sehingga cosθ → 1, memaksimalkan h. Celah yang lebih sempit (r kecil) justru menaikkan h. Densitas besar dan r besar menurunkan h.', 'chemistry', 'hard'),
  ('Dalam sistem klasifikasi penetran, kombinasi ''Type I, Method D, Sensitivity Level 3, Developer Form d'' berarti...',
   '["Visible, water-washable, low sensitivity, dry developer","Visible, post-emulsifiable lipophilic, medium sensitivity, water-soluble developer","Fluorescent, solvent-removable, ultra-high sensitivity, plastic film","Fluorescent, post-emulsifiable hydrophilic, high sensitivity, nonaqueous developer"]', 3,
   'Type I = fluorescent; Method D = post-emulsifiable hydrophilic; Sensitivity Level 3 = high (skala AMS 2644: Level 1/2 ultra-low, 1 low, 2 medium, 3 high, 4 ultra-high); Developer Form d = nonaqueous solvent (sensitivitas developer tertinggi).', 'classification', 'medium'),
  ('Penetran Method B (post-emulsifiable lipophilic) dikendalikan terutama oleh variabel apa, dan apa mekanisme emulsifikasinya?',
   '["Dikendalikan oleh konsentrasi; mekanisme aksi deterjen","Dikendalikan oleh waktu (dwell emulsifier); mekanisme difusi","Dikendalikan oleh suhu; mekanisme penguapan","Dikendalikan oleh tekanan semprot; mekanisme abrasi"]', 1,
   'Method B menggunakan emulsifier berbasis minyak (lipophilic, as-supplied ~100%) yang bekerja melalui difusi ke dalam lapisan penetran; karena itu DIKENDALIKAN OLEH WAKTU (dwell emulsifier tipikal 30 dtk-2 mnt) dengan jendela sempit. Kontrol konsentrasi dan aksi deterjen adalah karakteristik Method D (hydrophilic).', 'post-emulsifiable', 'medium'),
  ('Pada penetran Method D (post-emulsifiable hydrophilic), berapa rentang konsentrasi emulsifier yang umum digunakan untuk aplikasi celup (dip) dan aplikasi semprot (spray)?',
   '["Dip <=5%, spray 5-20%","Dip 30-50%, spray 20-30%","Dip 5-20%, spray <=5%","Dip 100%, spray 50%"]', 2,
   'Emulsifier hydrophilic Method D diencerkan dengan air: untuk celup (dip) tipikal 5-20%, sedangkan untuk semprot (spray) dibatasi <=5% karena agitasi mekanis semprotan menambah efek pembersihan. Kontrol konsentrasi (mis. via Brix) menjaga over-removal.', 'post-emulsifiable', 'easy'),
  ('Apa perbedaan paling mendasar antara penetran post-emulsifiable (Method B/D) dan penetran water-washable (Method A)?',
   '["Method A bersifat fluorescent sedangkan B/D selalu visible","Method A tidak memerlukan developer sama sekali","Method A mengandung emulsifier built-in, sedangkan B/D memerlukan langkah emulsifikasi terpisah setelah dwell penetran","Method A hanya dapat digunakan pada material non-ferro"]', 2,
   'Penetran water-washable (Method A) sudah mengandung emulsifier di dalamnya sehingga langsung dibilas air. Penetran post-emulsifiable (B/D) TIDAK mengandung emulsifier; emulsifier diaplikasikan sebagai langkah terpisah setelah dwell penetran, menaikkan sensitivitas 2-3x dengan kompleksitas proses lebih tinggi.', 'post-emulsifiable', 'easy'),
  ('Mengapa Method B (lipophilic) dianggap memiliki ''jendela proses yang sempit'' dibandingkan Method D (hydrophilic)?',
   '["Karena emulsifier B harus diencerkan dengan presisi tinggi","Karena difusi emulsifier terus berlanjut seiring waktu, sehingga over-emulsification mudah terjadi jika dwell emulsifier terlalu lama","Karena B hanya bisa dipakai pada suhu di bawah 10 C","Karena B memerlukan pre-rinse yang sangat lama"]', 1,
   'Emulsifier lipophilic bekerja via difusi yang terus berlangsung; sekali kontak, waktu menjadi variabel kritis dan window-nya sempit — terlalu lama menyebabkan over-emulsification dan over-removal penetran dari cacat. Method D dikontrol konsentrasi (lebih toleran). Method B justru TANPA pre-rinse.', 'post-emulsifiable', 'hard'),
  ('Pada Method D, mengapa sering dilakukan langkah pre-rinse air sebelum aplikasi emulsifier hydrophilic?',
   '["Untuk membuang sebagian besar penetran berlebih permukaan sehingga beban emulsifier berkurang dan kontrol lebih baik","Untuk mengaktifkan dye fluorescent","Untuk menurunkan suhu komponen ke bawah 10 C","Untuk menggantikan fungsi developer"]', 0,
   'Pre-rinse air pada Method D membuang lapisan penetran permukaan berlebih sebelum emulsifier diaplikasikan, mengurangi beban kerja emulsifier dan membuat removal lebih terkontrol serta seragam. Ini ciri khas D (hydrophilic); Method B tidak menggunakan pre-rinse.', 'post-emulsifiable', 'medium'),
  ('Seorang Level II memilih sistem post-emulsifiable hydrophilic (Method D, Type I, Sensitivity 4) untuk inspeksi turbine blade. Apa alasan teknis utama pemilihan ini dibanding water-washable?',
   '["Lebih murah dan lebih cepat untuk produksi massal","Tidak memerlukan UV-A maupun ruang gelap","Dapat mendeteksi cacat sub-permukaan pada superalloy","Memberi sensitivitas sangat tinggi untuk crack fatigue yang sangat tight, dengan removal terkontrol sehingga penetran di dalam cacat tidak ikut terbuang"]', 3,
   'Crack fatigue pada turbine blade sangat sempit; sistem post-emulsifiable Sensitivity 4 memberi sensitivitas tertinggi, dan emulsifikasi terpisah menjaga penetran di dalam cacat tidak ikut ter-wash sehingga indikasi tetap muncul. PT tetap hanya mendeteksi cacat permukaan dan tetap butuh UV-A; bukan pilihan termurah.', 'post-emulsifiable', 'hard'),
  ('Untuk penetran water-washable (Method A), kandungan air yang berlebih dalam bak penetran sangat dibatasi karena...',
   '["Kontaminasi air menurunkan sensitivitas dan dapat menyebabkan separasi/gelling penetran","Air membuat penetran mudah terbakar","Air menaikkan fluoresensi secara berlebihan","Air mempercepat dwell time sehingga indikasi hilang"]', 0,
   'Method A paling rentan terhadap kontaminasi air: air berlebih menurunkan sensitivitas, dapat memicu separasi atau gelling, dan mengubah karakteristik wash. Karena itu water content dipantau dan dibatasi sebagai bagian process control.', 'process-control', 'medium'),
  ('Dalam process control Method D, instrumen apa yang umum digunakan untuk memantau konsentrasi emulsifier hydrophilic di dalam bak?',
   '["Refraktometer (pembacaan Brix)","Magnetometer","Densitometer film radiografi","Anemometer"]', 0,
   'Konsentrasi emulsifier hydrophilic (Method D) dipantau dengan refraktometer melalui pembacaan Brix, yang berkorelasi dengan konsentrasi larutan. Magnetometer (MT), densitometer (RT), dan anemometer tidak relevan untuk kontrol konsentrasi emulsifier.', 'process-control', 'medium'),
  ('Apa pernyataan yang PALING tepat mengenai ''sensitivity'' sebuah sistem PT?',
   '["Sensitivity ditentukan sepenuhnya oleh konsentrasi dye dalam penetran","Sensitivity hanya bergantung pada intensitas lampu UV-A","Sensitivity adalah properti sistem lengkap: penetran + proses removal + developer + lighting","Sensitivity sama dengan dwell time penetran"]', 2,
   'Sensitivity adalah properti SISTEM utuh — penetran, metode removal, developer, dan kondisi pencahayaan — bukan hanya satu komponen. Karena itu mengganti developer, removal, atau lighting dapat menaik-turunkan sensitivity meski penetrannya sama.', 'process-control', 'easy'),
  ('Berapa rentang suhu standar permukaan benda uji (dan penetran) yang umumnya disyaratkan agar PT konvensional valid tanpa kualifikasi khusus?',
   '["0-10 C","10-52 C","52-100 C","100-150 C"]', 1,
   'Rentang suhu standar untuk PT konvensional adalah 10-52 C (50-125 F). Di luar rentang ini (mis. high-temp atau low-temp) diperlukan kualifikasi prosedur khusus karena viskositas, dwell, dan perilaku penetran berubah.', 'process-control', 'easy'),
  ('Untuk pemeriksaan high-temperature (di atas batas standar) menggunakan penetran khusus, langkah kualifikasi yang benar adalah...',
   '["Cukup memanjangkan dwell time dua kali lipat tanpa kualifikasi","Menggunakan developer Form e (plastic film) yang otomatis valid pada semua suhu","Mengganti Type I menjadi Type II tanpa perubahan lain","Mengkualifikasi prosedur pada suhu aktual menggunakan comparator/quench-cracked panel pada suhu tersebut"]', 3,
   'Aplikasi high-temp di luar 10-52 C adalah essential variable; prosedur harus dikualifikasi pada suhu aktual, biasanya dengan membandingkan terhadap prosedur standar memakai quench-cracked/comparator panel pada suhu tersebut untuk membuktikan sensitivitas setara. Memperpanjang dwell saja tanpa kualifikasi tidak sah.', 'specialty', 'hard'),
  ('Saat melakukan PT pada komponen plastik atau material berpori, perhatian khusus apa yang paling penting?',
   '["Risiko serangan kimia (chemical attack) oleh solvent carrier dan background tinggi akibat porositas/penyerapan penetran","Menggunakan UV-A intensitas dua kali lipat","Wajib menggunakan Method B karena plastik bersifat lipophilic","Plastik tidak dapat di-PT sama sekali dalam kondisi apa pun"]', 0,
   'Pada plastik, solvent carrier penetran dapat menyerang/melarutkan material (chemical attack), dan material berpori menyerap penetran menghasilkan background tinggi yang menutupi indikasi. Kompatibilitas kimia dan kontrol background menjadi krusial; intensitas UV dan pemilihan Method bukan isu utamanya.', 'specialty', 'medium'),
  ('Pada aplikasi aerospace untuk casting Ni-superalloy, mengapa sering disyaratkan Sensitivity Level 4 (ultra-high) dengan developer Form d?',
   '["Karena hanya kombinasi itu yang murah","Karena crack fatigue/casting yang sangat tight memerlukan deteksi maksimum dan nonaqueous developer memberi sensitivitas tertinggi","Karena Level 4 menghilangkan kebutuhan ruang gelap","Karena Form d adalah satu-satunya developer yang aman pada superalloy"]', 1,
   'Komponen aerospace kritis menuntut deteksi diskontinuitas yang sangat tight; Sensitivity Level 4 (ultra-high, Type I) dipadukan dengan developer nonaqueous (Form d) yang memberi sensitivitas developer tertinggi memaksimalkan kemampuan deteksi. Pilihan ini soal kemampuan deteksi, bukan biaya atau pengganti ruang gelap.', 'specialty', 'medium'),
  ('Sebuah komponen aluminium tipis dengan toleransi korosi rendah perlu di-PT di lapangan. Manakah pertimbangan specialty yang paling relevan dalam memilih sistem?',
   '["Memilih penetran dengan residu halogen/sulfur tinggi untuk kontras lebih baik","Mengabaikan kontrol pencahayaan karena aluminium memantulkan cahaya","Mengutamakan kompatibilitas kimia dan removability di lapangan, mis. solvent-removable (Method C) Type II bila air terbatas","Menggunakan Method A tanpa developer untuk menghemat waktu"]', 2,
   'Di lapangan dengan akses air/listrik terbatas, sistem solvent-removable (Method C) sering praktis, dan kompatibilitas kimia tetap dijaga. Residu halogen/sulfur justru harus dibatasi, kontrol pencahayaan tetap wajib, dan developer tidak boleh dihilangkan karena diperlukan untuk bleed-out.', 'specialty', 'hard'),
  ('PT ''mengamplifikasi'' indikasi sehingga bleed-out tampak lebih besar dari rongga sebenarnya. Implikasi penting untuk sizing adalah...',
   '["Dimensi yang diukur untuk acceptance adalah dimensi indikasi (bleed-out), bukan dimensi crack aktual, dan PT tidak mengukur kedalaman","Dimensi crack aktual selalu lebih besar dari indikasi","PT dapat mengukur kedalaman cacat secara presisi dari lebar bleed-out","Bleed-out selalu sama persis dengan ukuran crack"]', 0,
   'Karena bleed-out melebar dari rongga, yang diukur dan dibandingkan terhadap kriteria acceptance adalah dimensi INDIKASI, bukan crack fisik. PT juga tidak memberi informasi kedalaman. Inilah sebab penting evaluasi mengacu pada dimensi indikasi yang teramati.', 'sizing', 'easy'),
  ('Menurut konvensi evaluasi PT, sebuah indikasi diklasifikasikan sebagai LINEAR jika...',
   '["panjangnya kurang dari atau sama dengan tiga kali lebarnya","panjangnya lebih dari tiga kali lebarnya","diameternya lebih dari 5 mm","warnanya lebih terang dari background"]', 1,
   'Indikasi LINEAR didefinisikan sebagai indikasi yang panjangnya lebih dari 3x lebarnya. Bila panjang <= 3x lebar, indikasi diklasifikasikan ROUNDED. Klasifikasi ini menentukan kriteria acceptance yang diterapkan.', 'sizing', 'easy'),
  ('Kapan waktu yang benar untuk mengukur dan mengevaluasi indikasi setelah developer diaplikasikan?',
   '["Setelah developer dwell minimum (>=10 menit atau ~1/2 dwell penetran), dalam jendela waktu sebelum over-bleed","Segera setelah developer kering, tanpa menunggu","Setelah 24 jam agar bleed-out maksimal","Sebelum developer diaplikasikan, langsung pada penetran basah"]', 0,
   'Evaluasi dilakukan setelah developer dwell minimum (umumnya >=10 menit atau sekitar setengah dwell penetran) dalam jendela waktu yang sesuai: terlalu cepat berarti under-develop (indikasi belum keluar), terlalu lama berarti over-bleed (indikasi melebar/menyebar dan kabur).', 'sizing', 'medium'),
  ('Dalam evaluasi, indikasi dikategorikan menjadi FALSE, NON-RELEVANT, dan RELEVANT. Bagaimana cara terbaik membedakan indikasi FALSE dari yang lain?',
   '["Indikasi false selalu berwarna lebih gelap","Indikasi false TIDAK muncul kembali setelah re-clean dan re-develop","Indikasi false selalu lebih panjang dari 5 mm","Indikasi false hanya muncul di bawah cahaya tampak"]', 1,
   'Indikasi FALSE (mis. over-wash residue, lint, kontaminasi) tidak muncul kembali setelah area dibersihkan dengan kain ber-solvent, dikeringkan, dan di-develop ulang. NON-RELEVANT muncul kembali tetapi konsisten mengikuti geometri; RELEVANT muncul kembali dengan bleed-back progresif dari rongga aktual.', 'sizing', 'medium'),
  ('Saat mendiskriminasi sebuah spot meragukan, urutan teknik yang benar adalah membersihkan spot dengan solvent-dampened cloth, mengeringkan, lalu re-develop. Developer form mana yang paling tepat untuk diskriminasi karena sensitivitas tertinggi?',
   '["Form a (dry powder)","Form b (water-soluble)","Form c (water-suspendable)","Form d (nonaqueous)"]', 3,
   'Developer Form d (nonaqueous solvent) memberi sensitivitas tertinggi sehingga ideal untuk re-develop saat mendiskriminasi indikasi meragukan, karena bleed-back tipis sekalipun akan terlihat jelas.', 'sizing', 'medium'),
  ('Per ASME VIII Div.1 Mandatory Appendix 8, mulai dimensi mayor berapa sebuah indikasi dianggap RELEVANT (perlu dievaluasi)?',
   '["> 0.5 mm","> 3 mm (1/8 in)","> 5 mm (3/16 in)","> 1.6 mm (1/16 in)"]', 3,
   'Menurut ASME VIII Div.1 Appendix 8, indikasi dengan dimensi mayor > 1.6 mm (1/16 in) dianggap relevant dan harus dievaluasi terhadap kriteria. Indikasi <= 1.6 mm umumnya tidak dianggap relevant.', 'sizing', 'medium'),
  ('Bila Level II ragu apakah suatu indikasi berasal dari geometri sah atau dari crack, sikap yang benar menurut prinsip evaluasi (ASME V Article 6 T-680) adalah...',
   '["Anggap non-relevant agar produksi tidak terganggu","Perlakukan sebagai relevant sampai terbukti sebaliknya; beban pembuktian ada pada inspektor","Abaikan indikasi karena kurang dari 5 mm","Tunggu persetujuan Level I"]', 1,
   'Prinsip konservatif: bila ragu antara geometri dan crack, indikasi diperlakukan sebagai RELEVANT sampai terbukti sebaliknya — beban pembuktian ada pada inspektor. Pendekatan ini mencegah escape cacat kritis. Ukuran semata tidak membenarkan pengabaian, dan Level II berwenang menginterpretasi.', 'sizing', 'hard'),
  ('Dokumen mana yang menetapkan TEKNIK pemeriksaan PT (mis. T-621 procedure, T-680 evaluation) namun BUKAN kriteria accept/reject?',
   '["ASME V Article 6","ASME VIII Div.1 Appendix 8","AMS 2644","ISO 23277"]', 0,
   'ASME Section V Article 6 menetapkan TEKNIK (prosedur, evaluasi) pemeriksaan PT, tetapi TIDAK memberi kriteria accept/reject. Kriteria acceptance diambil dari referencing/construction code seperti ASME VIII Div.1 App.8. AMS 2644 mengatur kualifikasi material; ISO 23277 memberi acceptance level alternatif internasional.', 'code', 'easy'),
  ('AMS 2644 mengatur aspek apa dari pemeriksaan PT?',
   '["Kualifikasi material penetran (Type/Method/Sensitivity/Form)","Kriteria accept/reject indikasi pada vessel","Teknik pemeriksaan dan evaluasi indikasi","Frekuensi audit Level III"]', 0,
   'AMS 2644 adalah spesifikasi KUALIFIKASI material penetran — mengklasifikasikan dan mengkualifikasi Type, Method, Sensitivity, dan Developer Form. Ia tidak menetapkan kriteria acceptance indikasi (itu construction code) maupun teknik pemeriksaan (itu ASME V/ASTM E165).', 'code', 'easy'),
  ('Menurut ASME VIII Div.1 Appendix 8, indikasi LINEAR relevant dengan dimensi berapa yang harus DITOLAK (reject)?',
   '["Linear relevant > 5 mm = reject","Linear relevant > 3 mm = reject","Linear relevant > 1.6 mm = reject","Linear relevant > 10 mm = reject"]', 2,
   'Per ASME VIII Div.1 App.8, indikasi LINEAR relevant dengan panjang > 1.6 mm (1/16 in) harus ditolak. Ini berbeda dari rounded yang batas reject-nya > 5 mm. Hafalkan angka kunci ini untuk interpretasi kode.', 'code', 'medium'),
  ('Menurut ASME VIII Div.1 Appendix 8, indikasi ROUNDED relevant tunggal ditolak (reject) bila dimensinya...',
   '["> 1.6 mm (1/16 in)","> 3 mm (1/8 in)","> 5 mm (3/16 in)","> 8 mm (5/16 in)"]', 2,
   'Per ASME VIII Div.1 App.8, indikasi ROUNDED relevant ditolak bila dimensi > 5 mm (3/16 in). Indikasi rounded relevant yang <= 5 mm dapat diterima (meski tetap recordable). Bandingkan dengan linear yang batasnya > 1.6 mm.', 'code', 'medium'),
  ('ASTM E165 dan ASTM E1417 masing-masing paling tepat digambarkan sebagai...',
   '["E165 = kriteria acceptance vessel; E1417 = teknik radiografi","E165 = kualifikasi personel; E1417 = kalibrasi UV-A meter","E165 = praktik standar PT umum; E1417 = proses PT (terutama aerospace)","Keduanya identik dan dapat saling menggantikan tanpa perbedaan"]', 2,
   'ASTM E165 adalah standard practice untuk PT umum, sedangkan ASTM E1417 adalah spesifikasi proses PT yang banyak dipakai di aerospace/komersial dengan persyaratan kontrol proses lebih ketat. Keduanya memberi metode, bukan kriteria acceptance konstruksi tertentu.', 'code', 'medium'),
  ('Standar internasional ISO 3452 dan ISO 23277 dalam konteks PT berperan untuk...',
   '["ISO 3452 = metode/persyaratan umum & material PT; ISO 23277 = acceptance level untuk pengelasan","ISO 3452 = kualifikasi personel; ISO 23277 = kalibrasi suhu","Keduanya hanya berlaku untuk MT","ISO 3452 = teknik radiografi; ISO 23277 = teknik ultrasonik"]', 0,
   'Seri ISO 3452 mencakup prinsip umum, material, dan persyaratan pengujian PT, sedangkan ISO 23277 memberi acceptance level untuk indikasi PT pada sambungan las (level 1/2/3) sebagai alternatif internasional terhadap kode ASME/ASTM.', 'code', 'medium'),
  ('ASME V Article 6 mensyaratkan written procedure di-DEMONSTRATE ke kepuasan Inspector. Apa makna ''demonstrate'' di sini?',
   '["Prosedur dibuktikan pada spesimen representatif (mis. panel Ni-Cr cracked-chrome / TAM-PSM) bahwa ia benar-benar mendeteksi cacat","Cukup ditandatangani Level III tanpa pengujian fisik","Prosedur cukup dikirim ke regulator","Prosedur diuji hanya secara teoritis dalam rapat"]', 0,
   'Demonstrasi berarti prosedur benar-benar dijalankan pada spesimen representatif (mis. panel Ni-Cr cracked-chrome atau panel TAM/PSM) untuk membuktikan ia mendeteksi cacat ke kepuasan Inspector — tanda tangan saja tidak cukup. Ini inti T-621.', 'procedure', 'medium'),
  ('Dalam pengembangan prosedur PT, manakah yang merupakan ESSENTIAL VARIABLE sehingga perubahannya mewajibkan requalification?',
   '["Mengganti merek/keluarga material penetran atau mengubah Type/Method/Sensitivity","Mengganti kuas dengan semprot dalam batas yang diizinkan prosedur","Detail prosedural minor dalam batas izin","Urutan penomoran laporan"]', 0,
   'Mengganti keluarga/merek material, atau mengubah Type/Method/Sensitivity, menaik-turunkan kemampuan deteksi, sehingga merupakan essential variable yang mewajibkan requalification. Brush vs spray dalam batas izin, detail minor, dan penomoran laporan adalah nonessential (cukup dicatat).', 'procedure', 'medium'),
  ('Sebuah prosedur PT yang baik harus menetapkan angka-angka spesifik. Manakah set parameter yang benar untuk PT konvensional?',
   '["Dwell penetran 5-30 menit, developer dwell >=10 menit, suhu 10-52 C","Dwell penetran 1-2 menit, developer dwell >=60 menit, suhu 0-100 C","Dwell penetran 60 menit minimum, developer dwell 1 menit, suhu 52-100 C","Dwell penetran tidak perlu ditentukan, developer opsional"]', 0,
   'Prosedur harus menetapkan dwell penetran tipikal 5-30 menit, developer dwell minimum >=10 menit, dan rentang suhu standar 10-52 C, di samping kontrol pencahayaan, interval cek, dan kontrol emulsifier (mis. Brix untuk Method D). Angka harus eksplisit, bukan dibiarkan terbuka.', 'procedure', 'easy'),
  ('Prosedur PT harus mengutip kriteria acceptance dari mana?',
   '["Dari preferensi pribadi inspektor","Dari referencing/construction code yang governing (mis. ASME VIII Div.1 App.8, B31.3, atau part spec)","Selalu dari AMS 2644","Dari ASME V Article 6 yang memang memuat kriteria accept/reject"]', 1,
   'Kriteria acceptance harus dikutip dari referencing/construction code yang governing — misalnya ASME VIII Div.1 App.8 untuk vessel, ASME B31.1/B31.3 untuk piping, atau drawing/spec aerospace. ASME V Article 6 hanya teknik dan tidak memuat kriteria; AMS 2644 hanya kualifikasi material.', 'procedure', 'easy'),
  ('Suhu kerja yang diperlukan untuk inspeksi keluar dari rentang 10-52 C yang sudah dikualifikasi. Tindakan yang benar untuk Level II adalah...',
   '["Lanjutkan inspeksi karena penyimpangan suhu adalah nonessential variable","Naikkan konsentrasi dye untuk mengompensasi suhu","Ganti laporan agar mencatat suhu 25 C","Hentikan/kualifikasi ulang prosedur untuk suhu tersebut; perubahan suhu di luar rentang qualified adalah essential variable"]', 3,
   'Suhu di luar rentang yang dikualifikasi adalah essential variable; prosedur harus dikualifikasi ulang untuk suhu aktual sebelum diteruskan. Melanjutkan tanpa kualifikasi, mengubah dye, atau memalsukan laporan tidak dapat diterima dan melanggar integritas.', 'procedure', 'hard'),
  ('Untuk pemeriksaan fluorescent (Type I), kondisi pencahayaan minimum yang disyaratkan adalah...',
   '["UV-A >=1000 uW/cm2 @ 38 cm, ambient white light <=20 lux, dengan adaptasi mata >=1 menit","UV-A >=100 uW/cm2 @ 100 cm, ambient bebas, tanpa adaptasi","White light >=1000 lux saja","UV-A apa saja asal ruangan gelap total tanpa pengukuran"]', 0,
   'Pemeriksaan fluorescent membutuhkan iradiansi UV-A >=1000 uW/cm2 pada 38 cm, ambient white light <=20 lux untuk kontras, dan adaptasi gelap mata minimal 1 menit. Pengukuran kuantitatif wajib; ''gelap total tanpa ukur'' tidak memenuhi syarat.', 'qc-audit', 'medium'),
  ('Untuk pemeriksaan visible (Type II), intensitas cahaya tampak (white light) minimum pada permukaan benda uji umumnya disyaratkan...',
   '[">=100 lux",">=500 lux",">=20 lux",">=1000 lux"]', 3,
   'Pemeriksaan visible (Type II) memerlukan white light minimum >=1000 lux (100 fc) pada permukaan agar kontras dye merah terhadap developer putih memadai. Nilai 20 lux justru batas maksimum ambient untuk pemeriksaan fluorescent.', 'qc-audit', 'easy'),
  ('Panel referensi mana yang umum digunakan untuk verifikasi performa sistem PT harian/per shift?',
   '["Panel TAM/PSM dan panel Ni-Cr (cracked-chrome)","IIW block dan step wedge","DSC dan IQI hole-type","Penetrameter dan densitometer"]', 0,
   'Panel TAM/PSM (untuk sensitivitas/wash) dan panel Ni-Cr cracked-chrome (crack halus terkontrol) adalah comparator standar untuk verifikasi performa sistem PT. IIW/step wedge dan DSC adalah untuk UT; IQI/penetrameter/densitometer untuk RT.', 'qc-audit', 'easy'),
  ('Dalam program QC PT, salah satu verifikasi rutin adalah kalibrasi/cek UV-A radiometer dan white light meter. Mengapa hal ini penting?',
   '["Agar penetran tidak menguap","Karena lampu UV-A meluruh seiring waktu; intensitas di bawah ambang menurunkan deteksi tanpa disadari operator","Karena radiometer mengubah Type I menjadi Type II","Karena white light meter mengatur dwell time"]', 1,
   'Output lampu UV-A menurun (degradasi) seiring jam pemakaian; tanpa pengecekan radiometer, iradiansi bisa jatuh di bawah 1000 uW/cm2 sehingga indikasi lemah tidak terlihat — escape berbahaya. Pengukuran rutin lighting menjaga validitas pemeriksaan.', 'qc-audit', 'medium'),
  ('Dalam audit sistem mutu PT Level III/auditor, siapa yang umumnya berwenang memberi PERSETUJUAN AKHIR (approval) terhadap prosedur PT?',
   '["Level III","Level I","Operator produksi","Klien tanpa kualifikasi NDT"]', 0,
   'Level II menulis dan men-demonstrate prosedur serta menandatangani interpretasi akhir, namun persetujuan akhir prosedur umumnya berada pada Level III. Level I bekerja di bawah supervisi dan tidak menyetujui prosedur.', 'qc-audit', 'medium'),
  ('Mengapa kontrol ambient white light <=20 lux penting saat inspeksi fluorescent, dari sisi audit/QC?',
   '["Cahaya ambient tinggi memudarkan dye secara permanen","Cahaya ambient tinggi merusak lampu UV-A","Cahaya ambient tinggi menurunkan kontras fluoresensi sehingga indikasi lemah tidak terlihat","Cahaya ambient tinggi memperpanjang dwell penetran"]', 2,
   'Ambient white light yang tinggi membanjiri mata dan menurunkan kontras antara emisi fluorescent (hijau-kuning) dan latar gelap, sehingga indikasi lemah tertutup. Karena itu QC mensyaratkan ambient <=20 lux dan adaptasi mata. Dye tidak rusak permanen oleh ambient sebatas ini.', 'qc-audit', 'hard'),
  ('Sebuah audit menemukan teknisi langsung mengevaluasi tanpa adaptasi gelap dan dengan ambient ~50 lux. Risiko utama temuan ini adalah...',
   '["Over-reject indikasi geometri","Under-reject / escape: indikasi fluorescent lemah tidak terlihat sehingga cacat relevant lolos","Developer mengering terlalu cepat","Penetran terkontaminasi air"]', 1,
   'Tanpa adaptasi gelap dan dengan ambient terlalu tinggi, indikasi fluorescent lemah tidak terlihat, sehingga risiko utamanya adalah under-reject/escape — cacat relevant lolos. Ini temuan audit kritis karena menyangkut keandalan deteksi, bukan masalah developer atau kontaminasi.', 'qc-audit', 'hard'),
  ('Studi kasus disposisi: ditemukan indikasi LINEAR relevant sepanjang 2.3 mm pada vessel (ASME VIII Div.1 App.8). Keputusan yang benar adalah...',
   '["Reject, karena linear relevant > 1.6 mm","Accept, karena di bawah 5 mm","Accept, karena linear tidak pernah ditolak","Tunda, butuh persetujuan klien"]', 0,
   'Per App.8, indikasi linear relevant > 1.6 mm harus ditolak. 2.3 mm > 1.6 mm => REJECT. Batas 5 mm berlaku untuk rounded, bukan linear; jadi opsi accept salah.', 'case-study', 'medium'),
  ('Studi kasus: satu indikasi ROUNDED relevant berdiameter 4 mm pada vessel (App.8). Disposisi yang benar adalah...',
   '["Reject, karena > 1.6 mm","Reject, semua rounded ditolak","Accept, tetapi tetap recordable (di bawah batas reject rounded 5 mm)","Abaikan, tidak perlu dicatat"]', 2,
   'Rounded relevant ditolak bila > 5 mm. 4 mm <= 5 mm, sehingga dapat DITERIMA, namun tetap RECORDABLE karena > 1.6 mm (relevant). Indikasi tidak boleh diabaikan/tidak dicatat.', 'case-study', 'medium'),
  ('Studi kasus: lima indikasi rounded relevant tersusun dalam satu garis dengan spasi edge-to-edge 1.2 mm. Menurut App.8 (aturan aligned rounded), disposisinya adalah...',
   '["Reject, karena empat atau lebih indikasi rounded segaris dengan spasi edge-to-edge <=1.6 mm tergolong aligned dan ditolak","Accept, karena masing-masing < 5 mm","Accept, karena rounded tidak pernah dievaluasi secara kelompok","Reject hanya jika ada enam atau lebih"]', 0,
   'ASME VIII Div.1 App.8 menolak EMPAT atau lebih indikasi rounded relevant yang tersusun dalam satu garis dengan spasi edge-to-edge 1.6 mm (1/16 in) atau kurang (aligned rounded) — pola ini bisa menandakan diskontinuitas linear tersembunyi. Lima rounded segaris dengan spasi 1.2 mm (<=1.6 mm) => REJECT meski tiap individu < 5 mm.', 'case-study', 'hard'),
  ('Studi kasus: indikasi ROUNDED tunggal 6 mm ditemukan. Disposisi yang benar (App.8) adalah...',
   '["Accept, karena rounded selalu diterima","Accept, karena < 1.6 mm","Reklasifikasi sebagai linear lalu accept","Reject, karena rounded relevant > 5 mm"]', 3,
   'Rounded relevant > 5 mm (3/16 in) ditolak per App.8. 6 mm > 5 mm => REJECT. Mereklasifikasi rounded menjadi linear tanpa dasar bukti tidak sah; klasifikasi ditentukan oleh rasio panjang:lebar (linear bila > 3x).', 'case-study', 'easy'),
  ('Sebelum melakukan re-PT atas area yang telah di-repair, langkah yang benar terlebih dahulu adalah...',
   '["Langsung re-PT karena sistem pasti masih valid","Verifikasi sistem dulu (panel TAM/PSM/Ni-Cr + pengukuran lighting) baru re-PT","Hanya mengganti developer","Menurunkan kriteria acceptance agar repair lulus"]', 1,
   'Sebelum re-PT repair, sistem harus diverifikasi ulang menggunakan panel comparator (TAM/PSM, Ni-Cr) dan pengecekan lighting untuk memastikan sensitivitas masih memadai — agar hasil re-PT dapat dipercaya. Menurunkan kriteria acceptance melanggar kode dan integritas.', 'case-study', 'medium'),
  ('Bedakan konsekuensi over-reject dan under-reject. Manakah pasangan yang benar?',
   '["Over-reject = meloloskan crack relevant; under-reject = repair sia-sia","Over-reject = menolak indikasi false/non-relevant sehingga repair sia-sia & biaya naik; under-reject = meloloskan crack relevant (escape kritis)","Keduanya tidak berdampak pada biaya maupun keselamatan","Over-reject selalu lebih berbahaya daripada under-reject"]', 1,
   'Over-reject berarti menolak indikasi yang sebenarnya false/non-relevant, menimbulkan repair sia-sia dan biaya naik. Under-reject berarti meloloskan crack relevant — escape kritis yang dapat berujung kegagalan in-service. Keduanya merugikan, tetapi under-reject lebih berbahaya untuk keselamatan.', 'case-study', 'hard'),
  ('Dokumentasi hasil PT yang baik (Level II) minimal harus mencakup...',
   '["Tipe indikasi, dimensi, kode acceptance yang dipakai, keputusan, dan tanda tangan — sehingga dapat diverifikasi inspektor lain secara independen","Hanya tanda tangan inspektor","Hanya foto tanpa angka","Hanya nomor batch penetran"]', 0,
   'Laporan harus memungkinkan verifikasi independen: mencatat tipe indikasi, dimensi, kode/kriteria acceptance yang diterapkan, keputusan accept/reject, dan tanda tangan. Tanda tangan, foto, atau nomor batch saja tidak cukup untuk traceability.', 'case-study', 'easy'),
  ('Studi kasus high-temp: komponen harus diperiksa pada 90 C menggunakan penetran high-temp khusus. Pernyataan yang benar adalah...',
   '["PT konvensional 10-52 C tetap berlaku tanpa perubahan","Cukup memakai developer Form e","Suhu tidak memengaruhi PT sama sekali","Diperlukan penetran yang dikualifikasi untuk suhu tersebut dan prosedur dikualifikasi pada suhu aktual karena ini essential variable"]', 3,
   '90 C berada di luar 10-52 C; ini essential variable yang menuntut penetran high-temp khusus dan kualifikasi prosedur pada suhu aktual (perbandingan terhadap prosedur standar pada comparator). Suhu sangat memengaruhi viskositas, dwell, dan penguapan penetran.', 'case-study', 'medium'),
  ('Studi kasus removal: pada Method D, teknisi melakukan emulsifikasi dengan konsentrasi jauh di atas batas dan waktu kontak lama, lalu tidak ada indikasi muncul. Penyebab paling mungkin adalah...',
   '["Over-removal: penetran dari dalam cacat ikut terbuang (over-emulsification) sehingga indikasi hilang","Developer terlalu tipis","UV-A terlalu kuat","Dwell penetran terlalu lama"]', 0,
   'Konsentrasi emulsifier berlebih dan waktu kontak lama menyebabkan over-emulsification/over-removal: penetran dari dalam cacat ikut terbuang sehingga tidak ada bleed-back dan indikasi ''hilang''. Ini false negative berbahaya yang dikendalikan dengan kontrol konsentrasi (Brix) dan waktu.', 'case-study', 'hard'),
  ('Studi kasus background tinggi: setelah develop, seluruh permukaan menyala redup merata sehingga indikasi sulit dibaca. Penyebab paling mungkin dan tindakan benar adalah...',
   '["Dwell penetran terlalu singkat; perpanjang ke 60 menit lalu lanjut baca","Developer terlalu tebal; lanjutkan membaca apa adanya","UV-A terlalu lemah; cukup naikkan suhu komponen","Removal kurang/insufficient wash (residu penetran permukaan); bersihkan ulang, verifikasi sistem, dan ulangi proses"]', 3,
   'Background fluorescent merata biasanya akibat removal/wash yang kurang sehingga penetran permukaan tertinggal. Tindakan benar: bersihkan ulang, periksa parameter removal, verifikasi sistem, dan ulangi — bukan memaksakan pembacaan. Memperpanjang dwell tidak memperbaiki over-background.', 'case-study', 'medium'),
  ('Studi kasus kewenangan: siapa yang menandatangani INTERPRETASI AKHIR indikasi dan boleh menulis serta men-demonstrate prosedur, sementara persetujuan akhir prosedur tetap di tangan Level III?',
   '["Level I","Level II","Operator tanpa sertifikasi","Klien"]', 1,
   'Level II berwenang menandatangani interpretasi akhir indikasi serta menulis dan men-demonstrate prosedur. Persetujuan akhir prosedur umumnya ada pada Level III. Level I bekerja di bawah supervisi dan tidak menafsirkan/menyetujui secara mandiri.', 'case-study', 'easy'),
  ('Saat memilih antara Method B dan Method D untuk produksi rutin volume tinggi dengan banyak geometri kompleks, pertimbangan yang menguntungkan Method D adalah...',
   '["Jendela proses lebih lebar karena dikontrol konsentrasi, lebih toleran terhadap variasi waktu, dan removal lebih seragam pada geometri rumit","Tidak memerlukan emulsifier sama sekali","Selalu lebih murah daripada water-washable","Memberikan informasi kedalaman cacat"]', 0,
   'Method D (hydrophilic) dikontrol konsentrasi sehingga jendela prosesnya lebih lebar dan lebih toleran terhadap variasi waktu dibanding Method B yang dikontrol waktu (window sempit); removal pada geometri kompleks pun lebih seragam (dibantu pre-rinse). D tetap memakai emulsifier dan tidak memberi kedalaman.', 'post-emulsifiable', 'medium'),
  ('Mengapa surface tension air (~72 dyne/cm) membuatnya buruk sebagai penetran dibanding penetran ber-surfactant (~25-35 dyne/cm)?',
   '["Air menguap terlalu lambat","Air tidak berwarna sehingga tidak fluoresen","Surface tension tinggi membuat sudut kontak besar dan kapilaritas ke celah sempit buruk (wetting jelek)","Air terlalu kental untuk mengalir"]', 2,
   'Surface tension air yang tinggi menghasilkan wetting buruk (sudut kontak besar) sehingga kapilaritas masuk celah sempit lemah. Penetran menurunkan surface tension ke 25-35 dyne/cm agar wetting baik dan masuk crack. Warna/fluoresensi dan viskositas adalah faktor terpisah.', 'chemistry', 'medium'),
  ('Pada developer, mengapa Form d (nonaqueous solvent) memberi sensitivitas tertinggi dibanding Form a (dry) atau b/c (aqueous)?',
   '["Karena solvent membantu menarik penetran keluar (re-dissolve/wicking) membentuk lapisan tipis seragam yang memaksimalkan bleed-out dan kontras","Karena solvent melarutkan dye menjadi lebih terang secara kimia permanen","Karena Form d tidak memerlukan dwell sama sekali","Karena Form d mengubah Type II menjadi Type I"]', 0,
   'Developer nonaqueous (Form d) menggunakan carrier solvent yang membantu menarik penetran keluar dari cacat dan membentuk lapisan developer tipis seragam, memaksimalkan bleed-out dan kontras — karenanya sensitivitas tertinggi dan disukai untuk re-develop diskriminasi. Ia tetap butuh dwell dan tidak mengubah Type dye.', 'process-control', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 1 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- PT-L2 Module 1 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (4, 'quiz', 'Mini-quiz — PT-L2 scope', '{"description":"5 soal scope & batas wewenang Level II PT (SNT-TC-1A / ISO 9712).","questionCount":5,"passingScore":75}', 600, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 1
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- PT-L2 Module 1 mini-quiz (5 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'PT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'PT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Menurut SNT-TC-1A, apa perbedaan utama wewenang antara PT Level I dan PT Level II?',
   '["Level I boleh mengembangkan prosedur sedangkan Level II hanya menjalankan instruksi tertulis","Level I melakukan kalibrasi peralatan di bawah arahan Level II tanpa boleh menyentuh part","Level I melakukan pengujian dan mencatat indikasi mengikuti instruksi, sedangkan Level II berwenang menyetel/mengkalibrasi, mengevaluasi & menginterpretasi hasil terhadap kode/spec, dan mengesahkan","Tidak ada perbedaan wewenang; keduanya boleh mengevaluasi dan menyetujui hasil secara setara"]', 2,
   'Per SNT-TC-1A, Level I berwenang melakukan kalibrasi spesifik, menjalankan pengujian, dan mencatat hasil sesuai instruksi tertulis di bawah supervisi. Level II berwenang menyetel & mengkalibrasi peralatan, MENGINTERPRETASI dan MENGEVALUASI hasil terhadap kode/standar/prosedur, serta mengesahkan (sign-off). Pengembangan prosedur adalah tanggung jawab tambahan Level II/III, bukan Level I. Distraktor A membalik peran (jelas salah); B dan D melebih-lebihkan/menyamakan wewenang.', 'Certification Scope', 'easy'),
  ('Tanggung jawab tambahan berikut yang DIBERIKAN kepada PT Level II (dan TIDAK dimiliki Level I) adalah:',
   '["Membersihkan permukaan part sebelum aplikasi penetran","Menginterpretasi indikasi terhadap kriteria penerimaan kode dan mengesahkan hasil inspeksi","Mengaplikasikan penetran dan developer sesuai instruksi langkah-demi-langkah","Mencatat waktu dwell penetran pada lembar kerja"]', 1,
   'Interpretasi indikasi terhadap kriteria penerimaan (mis. ASME VIII Div.1 App.8, ASTM E1417) dan pengesahan (sign-off) hasil adalah wewenang Level II. Membersihkan permukaan, mengaplikasikan penetran/developer, dan mencatat dwell adalah tugas pelaksanaan yang juga dapat dilakukan Level I di bawah instruksi tertulis.', 'Level II Responsibilities', 'easy'),
  ('Dalam alur kerja inspeksi PT, siapa yang berwenang menyusun/menyiapkan instruksi atau prosedur tertulis yang akan dijalankan oleh Level I?',
   '["Hanya Level I, karena merekalah yang menjalankan pengujian di lapangan","Level II atau Level III, dengan prosedur induk disetujui (approved) oleh Level III","Operator produksi yang mengoperasikan komponen","Auditor eksternal independen dari badan sertifikasi"]', 1,
   'Penyusunan/pengembangan instruksi & prosedur tertulis adalah tanggung jawab Level II atau Level III; di banyak organisasi prosedur induk disetujui (approved) oleh Level III, sedangkan Level II dapat menyiapkan instruksi spesifik berbasis prosedur tersebut. Level I menjalankan instruksi tetapi tidak menyusunnya. Operator produksi dan auditor eksternal bukan pemegang wewenang teknis NDT ini.', 'Procedure Development', 'medium'),
  ('Menurut SNT-TC-1A, faktor apa yang menentukan apakah seorang kandidat dapat disertifikasi sebagai Level II PT pada suatu organisasi?',
   '["Hanya lama bekerja di perusahaan, tanpa ujian apa pun","Kepemilikan sertifikat ISO 9712 yang secara otomatis mewajibkan sertifikasi Level II tanpa syarat lain","Pemenuhan training, pengalaman, dan kelulusan ujian (general, specific, practical) sesuai Written Practice pemberi kerja","Rekomendasi lisan dari satu rekan Level II yang sudah bersertifikat"]', 2,
   'SNT-TC-1A adalah recommended practice berbasis EMPLOYER: sertifikasi diterbitkan oleh pemberi kerja berdasarkan Written Practice yang mensyaratkan jam training, pengalaman terdokumentasi, dan kelulusan ujian general, specific, serta practical (plus uji penglihatan). Ini berbeda dari ISO 9712 yang berbasis sertifikasi pihak ketiga/sentral. Distraktor lain mengabaikan ujian/pengalaman formal.', 'Certification Requirements', 'medium'),
  ('Seorang Level I menemukan indikasi linear pada weld dan ingin mengetahui apakah part diterima atau ditolak. Tindakan yang benar sesuai batas wewenang adalah:',
   '["Level I langsung menyatakan reject dan menandatangani laporan akhir sendiri","Level I memutuskan accept karena indikasi terlihat kecil secara visual","Level I mencatat indikasi lalu menyerahkan evaluasi & keputusan acceptance kepada Level II yang menginterpretasi terhadap kriteria kode dan mengesahkan","Level I membuang part tanpa pencatatan karena ada indikasi"]', 2,
   'Level I berwenang mendeteksi dan mencatat indikasi mengikuti instruksi, tetapi TIDAK berwenang mengevaluasi/menginterpretasi terhadap kriteria penerimaan maupun mengesahkan keputusan accept/reject. Interpretasi terhadap kode (mis. ASME VIII Div.1 App.8: indikasi linear relevant >1.6 mm ditolak) dan sign-off adalah wewenang Level II. Distraktor menggambarkan tindakan di luar wewenang Level I atau pelanggaran prosedur (membuang tanpa catat).', 'Authority Limits', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'PT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;
